export const SAYINGS = [["Pirkei_Avot:1:1:0",0,1,1,"פרק א׳, משנה א׳","משֶׁה קִבֵּל תּוֹרָה מִסִּינַי, וּמְסָרָהּ לִיהוֹשֻׁעַ, וִיהוֹשֻׁעַ לִזְקֵנִים, וּזְקֵנִים לִנְבִיאִים, וּנְבִיאִים מְסָרוּהָ לְאַנְשֵׁי כְנֶסֶת הַגְּדוֹלָה. הֵם אָמְרוּ שְׁלשָׁה דְבָרִים, הֱווּ מְתוּנִים בַּדִּין, וְהַעֲמִידוּ תַלְמִידִים הַרְבֵּה, וַעֲשׂוּ סְיָג לַתּוֹרָה:"],
["Pirkei_Avot:1:2:0",0,1,2,"פרק א׳, משנה ב׳","שִׁמְעוֹן הַצַּדִּיק הָיָה מִשְּׁיָרֵי כְנֶסֶת הַגְּדוֹלָה. הוּא הָיָה אוֹמֵר, עַל שְׁלשָׁה דְבָרִים הָעוֹלָם עוֹמֵד, עַל הַתּוֹרָה וְעַל הָעֲבוֹדָה וְעַל גְּמִילוּת חֲסָדִים:"],
["Pirkei_Avot:1:3:0",0,1,3,"פרק א׳, משנה ג׳","אַנְטִיגְנוֹס אִישׁ סוֹכוֹ קִבֵּל מִשִּׁמְעוֹן הַצַּדִּיק. הוּא הָיָה אוֹמֵר, אַל תִּהְיוּ כַעֲבָדִים הַמְשַׁמְּשִׁין אֶת הָרַב עַל מְנָת לְקַבֵּל פְּרָס, אֶלָּא הֱווּ כַעֲבָדִים הַמְשַׁמְּשִׁין אֶת הָרַב שֶׁלֹּא עַל מְנָת לְקַבֵּל פְּרָס, וִיהִי מוֹרָא שָׁמַיִם עֲלֵיכֶם:"],
["Pirkei_Avot:1:4:0",0,1,4,"פרק א׳, משנה ד׳","יוֹסֵי בֶן יוֹעֶזֶר אִישׁ צְרֵדָה וְיוֹסֵי בֶן יוֹחָנָן אִישׁ יְרוּשָׁלַיִם קִבְּלוּ מֵהֶם. יוֹסֵי בֶן יוֹעֶזֶר אִישׁ צְרֵדָה אוֹמֵר, יְהִי בֵיתְךָ בֵית וַעַד לַחֲכָמִים, וֶהֱוֵי מִתְאַבֵּק בַּעֲפַר רַגְלֵיהֶם, וֶהֱוֵי שׁוֹתֶה בְצָמָא אֶת דִּבְרֵיהֶם:"],
["Pirkei_Avot:1:5:0",0,1,5,"פרק א׳, משנה ה׳","יוֹסֵי בֶן יוֹחָנָן אִישׁ יְרוּשָׁלַיִם אוֹמֵר, יְהִי בֵיתְךָ פָתוּחַ לִרְוָחָה, וְיִהְיוּ עֲנִיִּים בְּנֵי בֵיתֶךָ, וְאַל תַּרְבֶּה שִׂיחָה עִם הָאִשָּׁה. בְּאִשְׁתּוֹ אָמְרוּ, קַל וָחֹמֶר בְּאֵשֶׁת חֲבֵרוֹ. מִכָּאן אָמְרוּ חֲכָמִים, כָּל זְמַן שֶׁאָדָם מַרְבֶּה שִׂיחָה עִם הָאִשָּׁה, גּוֹרֵם רָעָה לְעַצְמוֹ, וּבוֹטֵל מִדִּבְרֵי תוֹרָה, וְסוֹפוֹ יוֹרֵשׁ גֵּיהִנֹּם:"],
["Pirkei_Avot:1:6:0",0,1,6,"פרק א׳, משנה ו׳","יְהוֹשֻׁעַ בֶּן פְּרַחְיָה וְנִתַּאי הָאַרְבֵּלִי קִבְּלוּ מֵהֶם. יְהוֹשֻׁעַ בֶּן פְּרַחְיָה אוֹמֵר, עֲשֵׂה לְךָ רַב, וּקְנֵה לְךָ חָבֵר, וֶהֱוֵי דָן אֶת כָּל הָאָדָם לְכַף זְכוּת:"],
["Pirkei_Avot:1:7:0",0,1,7,"פרק א׳, משנה ז׳","נִתַּאי הָאַרְבֵּלִי אוֹמֵר, הַרְחֵק מִשָּׁכֵן רָע, וְאַל תִּתְחַבֵּר לָרָשָׁע, וְאַל תִּתְיָאֵשׁ מִן הַפֻּרְעָנוּת:"],
["Pirkei_Avot:1:8:0",0,1,8,"פרק א׳, משנה ח׳","יְהוּדָה בֶן טַבַּאי וְשִׁמְעוֹן בֶּן שָׁטָח קִבְּלוּ מֵהֶם. יְהוּדָה בֶן טַבַּאי אוֹמֵר, אַל תַּעַשׂ עַצְמְךָ כְעוֹרְכֵי הַדַּיָּנִין. וּכְשֶׁיִּהְיוּ בַעֲלֵי דִינִין עוֹמְדִים לְפָנֶיךָ, יִהְיוּ בְעֵינֶיךָ כִרְשָׁעִים. וּכְשֶׁנִּפְטָרִים מִלְּפָנֶיךָ, יִהְיוּ בְעֵינֶיךָ כְזַכָּאִין, כְּשֶׁקִּבְּלוּ עֲלֵיהֶם אֶת הַדִּין:"],
["Pirkei_Avot:1:9:0",0,1,9,"פרק א׳, משנה ט׳","שִׁמְעוֹן בֶּן שָׁטָח אוֹמֵר, הֱוֵי מַרְבֶּה לַחְקֹר אֶת הָעֵדִים, וֶהֱוֵי זָהִיר בִּדְבָרֶיךָ, שֶׁמָּא מִתּוֹכָם יִלְמְדוּ לְשַׁקֵּר:"],
["Pirkei_Avot:1:10:0",0,1,10,"פרק א׳, משנה י׳","שְׁמַעְיָה וְאַבְטַלְיוֹן קִבְּלוּ מֵהֶם. שְׁמַעְיָה אוֹמֵר, אֱהֹב אֶת הַמְּלָאכָה, וּשְׂנָא אֶת הָרַבָּנוּת, וְאַל תִּתְוַדַּע לָרָשׁוּת:"],
["Pirkei_Avot:1:11:0",0,1,11,"פרק א׳, משנה י״א","אַבְטַלְיוֹן אוֹמֵר, חֲכָמִים, הִזָּהֲרוּ בְדִבְרֵיכֶם, שֶׁמָּא תָחוּבוּ חוֹבַת גָּלוּת וְתִגְלוּ לִמְקוֹם מַיִם הָרָעִים, וְיִשְׁתּוּ הַתַּלְמִידִים הַבָּאִים אַחֲרֵיכֶם וְיָמוּתוּ, וְנִמְצָא שֵׁם שָׁמַיִם מִתְחַלֵּל:"],
["Pirkei_Avot:1:12:0",0,1,12,"פרק א׳, משנה י״ב","הִלֵּל וְשַׁמַּאי קִבְּלוּ מֵהֶם. הִלֵּל אוֹמֵר, הֱוֵי מִתַּלְמִידָיו שֶׁל אַהֲרֹן, אוֹהֵב שָׁלוֹם וְרוֹדֵף שָׁלוֹם, אוֹהֵב אֶת הַבְּרִיּוֹת וּמְקָרְבָן לַתּוֹרָה:"],
["Pirkei_Avot:1:13:0",0,1,13,"פרק א׳, משנה י״ג","הוּא הָיָה אוֹמֵר, נָגֵד שְׁמָא, אָבֵד שְׁמֵהּ. וּדְלֹא מוֹסִיף, יָסֵף. וּדְלֹא יָלֵיף, קְטָלָא חַיָּב. וּדְאִשְׁתַּמֵּשׁ בְּתָגָא, חָלֵף:"],
["Pirkei_Avot:1:14:0",0,1,14,"פרק א׳, משנה י״ד","הוּא הָיָה אוֹמֵר, אִם אֵין אֲנִי לִי, מִי לִי. וּכְשֶׁאֲנִי לְעַצְמִי, מָה אֲנִי. וְאִם לֹא עַכְשָׁיו, אֵימָתָי:"],
["Pirkei_Avot:1:15:0",0,1,15,"פרק א׳, משנה ט״ו","שַׁמַּאי אוֹמֵר, עֲשֵׂה תוֹרָתְךָ קֶבַע. אֱמֹר מְעַט וַעֲשֵׂה הַרְבֵּה, וֶהֱוֵי מְקַבֵּל אֶת כָּל הָאָדָם בְּסֵבֶר פָּנִים יָפוֹת:"],
["Pirkei_Avot:1:16:0",0,1,16,"פרק א׳, משנה ט״ז","רַבָּן גַּמְלִיאֵל הָיָה אוֹמֵר, עֲשֵׂה לְךָ רַב, וְהִסְתַּלֵּק מִן הַסָּפֵק, וְאַל תַּרְבֶּה לְעַשֵּׂר אֹמָדוֹת:"],
["Pirkei_Avot:1:17:0",0,1,17,"פרק א׳, משנה י״ז","שִׁמְעוֹן בְּנוֹ אוֹמֵר, כָּל יָמַי גָּדַלְתִּי בֵין הַחֲכָמִים, וְלֹא מָצָאתִי לַגּוּף טוֹב אֶלָּא שְׁתִיקָה. וְלֹא הַמִּדְרָשׁ הוּא הָעִקָּר, אֶלָּא הַמַּעֲשֶׂה. וְכָל הַמַּרְבֶּה דְבָרִים, מֵבִיא חֵטְא:"],
["Pirkei_Avot:1:18:0",0,1,18,"פרק א׳, משנה י״ח","רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר, עַל שְׁלשָׁה דְבָרִים הָעוֹלָם עוֹמֵד, עַל הַדִּין וְעַל הָאֱמֶת וְעַל הַשָּׁלוֹם, שֶׁנֶּאֱמַר (זכריה ח) אֱמֶת וּמִשְׁפַּט שָׁלוֹם שִׁפְטוּ בְּשַׁעֲרֵיכֶם:"],
["Pirkei_Avot:2:1:0",0,2,1,"פרק ב׳, משנה א׳","רַבִּי אוֹמֵר, אֵיזוֹהִי דֶרֶךְ יְשָׁרָה שֶׁיָּבֹר לוֹ הָאָדָם, כֹּל שֶׁהִיא תִפְאֶרֶת לְעוֹשֶׂיהָ וְתִפְאֶרֶת לוֹ מִן הָאָדָם. וֶהֱוֵי זָהִיר בְּמִצְוָה קַלָּה כְבַחֲמוּרָה, שֶׁאֵין אַתָּה יוֹדֵעַ מַתַּן שְׂכָרָן שֶׁל מִצְוֹת. וֶהֱוֵי מְחַשֵּׁב הֶפְסֵד מִצְוָה כְּנֶגֶד שְׂכָרָהּ, וּשְׂכַר עֲבֵרָה כְנֶגֶד הֶפְסֵדָהּ. וְהִסְתַּכֵּל בִּשְׁלשָׁה דְבָרִים וְאִי אַתָּה בָא לִידֵי עֲבֵרָה, דַּע מַה לְּמַעְלָה מִמְּךָ, עַיִן רוֹאָה וְאֹזֶן שׁוֹמַעַת, וְכָל מַעֲשֶׂיךָ בַסֵּפֶר נִכְתָּבִין:"],
["Pirkei_Avot:2:2:0",0,2,2,"פרק ב׳, משנה ב׳","רַבָּן גַּמְלִיאֵל בְּנוֹ שֶׁל רַבִּי יְהוּדָה הַנָּשִׂיא אוֹמֵר, יָפֶה תַלְמוּד תּוֹרָה עִם דֶּרֶךְ אֶרֶץ, שֶׁיְּגִיעַת שְׁנֵיהֶם מְשַׁכַּחַת עָוֹן. וְכָל תּוֹרָה שֶׁאֵין עִמָּהּ מְלָאכָה, סוֹפָהּ בְּטֵלָה וְגוֹרֶרֶת עָוֹן. וְכָל הָעֲמֵלִים עִם הַצִּבּוּר, יִהְיוּ עֲמֵלִים עִמָּהֶם לְשֵׁם שָׁמַיִם, שֶׁזְּכוּת אֲבוֹתָם מְסַיַּעְתָּן וְצִדְקָתָם עוֹמֶדֶת לָעַד. וְאַתֶּם, מַעֲלֶה אֲנִי עֲלֵיכֶם שָׂכָר הַרְבֵּה כְּאִלּוּ עֲשִׂיתֶם:"],
["Pirkei_Avot:2:3:0",0,2,3,"פרק ב׳, משנה ג׳","הֱווּ זְהִירִין בָּרָשׁוּת, שֶׁאֵין מְקָרְבִין לוֹ לָאָדָם אֶלָּא לְצֹרֶךְ עַצְמָן. נִרְאִין כְּאוֹהֲבִין בִּשְׁעַת הֲנָאָתָן, וְאֵין עוֹמְדִין לוֹ לָאָדָם בִּשְׁעַת דָּחְקוֹ:"],
["Pirkei_Avot:2:4:0",0,2,4,"פרק ב׳, משנה ד׳","הוּא הָיָה אוֹמֵר, עֲשֵׂה רְצוֹנוֹ כִרְצוֹנְךָ, כְּדֵי שֶׁיַּעֲשֶׂה רְצוֹנְךָ כִרְצוֹנוֹ. בַּטֵּל רְצוֹנְךָ מִפְּנֵי רְצוֹנוֹ, כְּדֵי שֶׁיְּבַטֵּל רְצוֹן אֲחֵרִים מִפְּנֵי רְצוֹנֶךָ. הִלֵּל אוֹמֵר, אַל תִּפְרֹשׁ מִן הַצִּבּוּר, וְאַל תַּאֲמִין בְּעַצְמְךָ עַד יוֹם מוֹתְךָ, וְאַל תָּדִין אֶת חֲבֵרְךָ עַד שֶׁתַּגִּיעַ לִמְקוֹמוֹ, וְאַל תֹּאמַר דָּבָר שֶׁאִי אֶפְשָׁר לִשְׁמֹעַ, שֶׁסּוֹפוֹ לְהִשָּׁמַע. וְאַל תֹּאמַר לִכְשֶׁאִפָּנֶה אֶשְׁנֶה, שֶׁמָּא לֹא תִפָּנֶה:"],
["Pirkei_Avot:2:5:0",0,2,5,"פרק ב׳, משנה ה׳","הוּא הָיָה אוֹמֵר, אֵין בּוּר יְרֵא חֵטְא, וְלֹא עַם הָאָרֶץ חָסִיד, וְלֹא הַבַּיְשָׁן לָמֵד, וְלֹא הַקַּפְּדָן מְלַמֵּד, וְלֹא כָל הַמַּרְבֶּה בִסְחוֹרָה מַחְכִּים. וּבְמָקוֹם שֶׁאֵין אֲנָשִׁים, הִשְׁתַּדֵּל לִהְיוֹת אִישׁ:"],
["Pirkei_Avot:2:6:0",0,2,6,"פרק ב׳, משנה ו׳","אַף הוּא רָאָה גֻלְגֹּלֶת אַחַת שֶׁצָּפָה עַל פְּנֵי הַמַּיִם. אָמַר לָהּ, עַל דַּאֲטֵפְתְּ, אַטְפוּךְ. וְסוֹף מְטִיפַיִךְ יְטוּפוּן:"],
["Pirkei_Avot:2:7:0",0,2,7,"פרק ב׳, משנה ז׳","הוּא הָיָה אוֹמֵר, מַרְבֶּה בָשָׂר, מַרְבֶּה רִמָּה. מַרְבֶּה נְכָסִים, מַרְבֶּה דְאָגָה. מַרְבֶּה נָשִׁים, מַרְבֶּה כְשָׁפִים. מַרְבֶּה שְׁפָחוֹת, מַרְבֶּה זִמָּה. מַרְבֶּה עֲבָדִים, מַרְבֶּה גָזֵל. מַרְבֶּה תוֹרָה, מַרְבֶּה חַיִּים. מַרְבֶּה יְשִׁיבָה, מַרְבֶּה חָכְמָה. מַרְבֶּה עֵצָה, מַרְבֶּה תְבוּנָה. מַרְבֶּה צְדָקָה, מַרְבֶּה שָׁלוֹם. קָנָה שֵׁם טוֹב, קָנָה לְעַצְמוֹ. קָנָה לוֹ דִבְרֵי תוֹרָה, קָנָה לוֹ חַיֵּי הָעוֹלָם הַבָּא:"],
["Pirkei_Avot:2:8:0",0,2,8,"פרק ב׳, משנה ח׳","רַבָּן יוֹחָנָן בֶּן זַכַּאי קִבֵּל מֵהִלֵּל וּמִשַּׁמָּאי. הוּא הָיָה אוֹמֵר, אִם לָמַדְתָּ תוֹרָה הַרְבֵּה, אַל תַּחֲזִיק טוֹבָה לְעַצְמְךָ, כִּי לְכָךְ נוֹצָרְתָּ. חֲמִשָּׁה תַלְמִידִים הָיוּ לוֹ לְרַבָּן יוֹחָנָן בֶּן זַכַּאי, וְאֵלּוּ הֵן, רַבִּי אֱלִיעֶזֶר בֶּן הוֹרְקְנוֹס, וְרַבִּי יְהוֹשֻׁעַ בֶּן חֲנַנְיָה, וְרַבִּי יוֹסֵי הַכֹּהֵן, וְרַבִּי שִׁמְעוֹן בֶּן נְתַנְאֵל, וְרַבִּי אֶלְעָזָר בֶּן עֲרָךְ. הוּא הָיָה מוֹנֶה שִׁבְחָן. רַבִּי אֱלִיעֶזֶר בֶּן הוֹרְקְנוֹס, בּוֹר סוּד שֶׁאֵינוֹ מְאַבֵּד טִפָּה. רַבִּי יְהוֹשֻׁעַ בֶּן חֲנַנְיָה, אַשְׁרֵי יוֹלַדְתּוֹ. רַבִּי יוֹסֵי הַכֹּהֵן, חָסִיד. רַבִּי שִׁמְעוֹן בֶּן נְתַנְאֵל, יְרֵא חֵטְא."],
["Pirkei_Avot:2:8:646",0,2,8,"פרק ב׳, משנה ח׳","וְרַבִּי אֶלְעָזָר בֶּן עֲרָךְ, מַעְיָן הַמִּתְגַּבֵּר. הוּא הָיָה אוֹמֵר, אִם יִהְיוּ כָל חַכְמֵי יִשְׂרָאֵל בְּכַף מֹאזְנַיִם, וֶאֱלִיעֶזֶר בֶּן הוֹרְקְנוֹס בְּכַף שְׁנִיָּה, מַכְרִיעַ אֶת כֻּלָּם. אַבָּא שָׁאוּל אוֹמֵר מִשְּׁמוֹ, אִם יִהְיוּ כָל חַכְמֵי יִשְׂרָאֵל בְּכַף מֹאזְנַיִם וְרַבִּי אֱלִיעֶזֶר בֶּן הוֹרְקְנוֹס אַף עִמָּהֶם, וְרַבִּי אֶלְעָזָר בֶּן עֲרָךְ בְּכַף שְׁנִיָּה, מַכְרִיעַ אֶת כֻּלָּם:"],
["Pirkei_Avot:2:9:0",0,2,9,"פרק ב׳, משנה ט׳","אָמַר לָהֶם, צְאוּ וּרְאוּ אֵיזוֹהִי דֶרֶךְ יְשָׁרָה שֶׁיִּדְבַּק בָּהּ הָאָדָם. רַבִּי אֱלִיעֶזֶר אוֹמֵר, עַיִן טוֹבָה. רַבִּי יְהוֹשֻׁעַ אוֹמֵר, חָבֵר טוֹב. רַבִּי יוֹסֵי אוֹמֵר, שָׁכֵן טוֹב. רַבִּי שִׁמְעוֹן אוֹמֵר, הָרוֹאֶה אֶת הַנּוֹלָד. רַבִּי אֶלְעָזָר אוֹמֵר, לֵב טוֹב. אָמַר לָהֶם, רוֹאֶה אֲנִי אֶת דִּבְרֵי אֶלְעָזָר בֶּן עֲרָךְ מִדִּבְרֵיכֶם, שֶׁבִּכְלָל דְּבָרָיו דִּבְרֵיכֶם. אָמַר לָהֶם צְאוּ וּרְאוּ אֵיזוֹהִי דֶרֶךְ רָעָה שֶׁיִּתְרַחֵק מִמֶּנָּה הָאָדָם. רַבִּי אֱלִיעֶזֶר אוֹמֵר, עַיִן רָעָה. רַבִּי יְהוֹשֻׁעַ אוֹמֵר, חָבֵר רָע. רַבִּי יוֹסֵי אוֹמֵר, שָׁכֵן רָע. רַבִּי שִׁמְעוֹן אוֹמֵר, הַלֹּוֶה וְאֵינוֹ מְשַׁלֵּם."],
["Pirkei_Avot:2:9:635",0,2,9,"פרק ב׳, משנה ט׳","אֶחָד הַלֹּוֶה מִן הָאָדָם, כְּלֹוֶה מִן הַמָּקוֹם בָּרוּךְ הוּא, שֶׁנֶּאֱמַר (תהלים לז) לֹוֶה רָשָׁע וְלֹא יְשַׁלֵּם, וְצַדִּיק חוֹנֵן וְנוֹתֵן. רַבִּי אֶלְעָזָר אוֹמֵר, לֵב רָע. אָמַר לָהֶם, רוֹאֶה אֲנִי אֶת דִּבְרֵי אֶלְעָזָר בֶּן עֲרָךְ מִדִּבְרֵיכֶם, שֶׁבִּכְלָל דְּבָרָיו דִּבְרֵיכֶם:"],
["Pirkei_Avot:2:10:0",0,2,10,"פרק ב׳, משנה י׳","הֵם אָמְרוּ שְׁלשָׁה דְבָרִים. רַבִּי אֱלִיעֶזֶר אוֹמֵר, יְהִי כְבוֹד חֲבֵרְךָ חָבִיב עָלֶיךָ כְּשֶׁלָּךְ, וְאַל תְּהִי נוֹחַ לִכְעֹס. וְשׁוּב יוֹם אֶחָד לִפְנֵי מִיתָתְךָ. וֶהֱוֵי מִתְחַמֵּם כְּנֶגֶד אוּרָן שֶׁל חֲכָמִים, וֶהֱוֵי זָהִיר בְּגַחַלְתָּן שֶׁלֹּא תִכָּוֶה, שֶׁנְּשִׁיכָתָן נְשִׁיכַת שׁוּעָל, וַעֲקִיצָתָן עֲקִיצַת עַקְרָב, וּלְחִישָׁתָן לְחִישַׁת שָׂרָף, וְכָל דִּבְרֵיהֶם כְּגַחֲלֵי אֵשׁ:"],
["Pirkei_Avot:2:11:0",0,2,11,"פרק ב׳, משנה י״א","רַבִּי יְהוֹשֻׁעַ אוֹמֵר, עַיִן הָרָע, וְיֵצֶר הָרָע, וְשִׂנְאַת הַבְּרִיּוֹת, מוֹצִיאִין אֶת הָאָדָם מִן הָעוֹלָם:"],
["Pirkei_Avot:2:12:0",0,2,12,"פרק ב׳, משנה י״ב","רַבִּי יוֹסֵי אוֹמֵר, יְהִי מָמוֹן חֲבֵרְךָ חָבִיב עָלֶיךָ כְּשֶׁלָּךְ, וְהַתְקֵן עַצְמְךָ לִלְמֹד תּוֹרָה, שֶׁאֵינָהּ יְרֻשָּׁה לָךְ. וְכָל מַעֲשֶׂיךָ יִהְיוּ לְשֵׁם שָׁמָיִם:"],
["Pirkei_Avot:2:13:0",0,2,13,"פרק ב׳, משנה י״ג","רַבִּי שִׁמְעוֹן אוֹמֵר, הֱוֵי זָהִיר בִּקְרִיאַת שְׁמַע וּבַתְּפִלָּה. וּכְשֶׁאַתָּה מִתְפַּלֵּל, אַל תַּעַשׂ תְּפִלָּתְךָ קֶבַע, אֶלָּא רַחֲמִים וְתַחֲנוּנִים לִפְנֵי הַמָּקוֹם בָּרוּךְ הוּא, שֶׁנֶּאֱמַר (יואל ב) כִּי חַנּוּן וְרַחוּם הוּא אֶרֶךְ אַפַּיִם וְרַב חֶסֶד וְנִחָם עַל הָרָעָה. וְאַל תְּהִי רָשָׁע בִּפְנֵי עַצְמְךָ:"],
["Pirkei_Avot:2:14:0",0,2,14,"פרק ב׳, משנה י״ד","רַבִּי אֶלְעָזָר אוֹמֵר, הֱוֵי שָׁקוּד לִלְמֹד תּוֹרָה, וְדַע מַה שֶּׁתָּשִׁיב לְאֶפִּיקוֹרוֹס. וְדַע לִפְנֵי מִי אַתָּה עָמֵל. וְנֶאֱמָן הוּא בַעַל מְלַאכְתְּךָ שֶׁיְּשַׁלֶּם לָךְ שְׂכַר פְּעֻלָּתֶךְ:"],
["Pirkei_Avot:2:15:0",0,2,15,"פרק ב׳, משנה ט״ו","רַבִּי טַרְפוֹן אוֹמֵר, הַיּוֹם קָצָר וְהַמְּלָאכָה מְרֻבָּה, וְהַפּוֹעֲלִים עֲצֵלִים, וְהַשָּׂכָר הַרְבֵּה, וּבַעַל הַבַּיִת דּוֹחֵק:"],
["Pirkei_Avot:2:16:0",0,2,16,"פרק ב׳, משנה ט״ז","הוּא הָיָה אוֹמֵר, לֹא עָלֶיךָ הַמְּלָאכָה לִגְמֹר, וְלֹא אַתָּה בֶן חוֹרִין לִבָּטֵל מִמֶּנָּה. אִם לָמַדְתָּ תוֹרָה הַרְבֵּה, נוֹתְנִים לְךָ שָׂכָר הַרְבֵּה. וְנֶאֱמָן הוּא בַעַל מְלַאכְתְּךָ שֶׁיְּשַׁלֵּם לְךָ שְׂכַר פְּעֻלָּתֶךָ. וְדַע מַתַּן שְׂכָרָן שֶׁל צַדִּיקִים לֶעָתִיד לָבֹא:"],
["Pirkei_Avot:3:1:0",0,3,1,"פרק ג׳, משנה א׳","עֲקַבְיָא בֶן מַהֲלַלְאֵל אוֹמֵר, הִסְתַּכֵּל בִּשְׁלשָׁה דְבָרִים וְאִי אַתָּה בָא לִידֵי עֲבֵרָה. דַּע מֵאַיִן בָּאתָ, וּלְאָן אַתָּה הוֹלֵךְ, וְלִפְנֵי מִי אַתָּה עָתִיד לִתֵּן דִּין וְחֶשְׁבּוֹן. מֵאַיִן בָּאתָ, מִטִּפָּה סְרוּחָה, וּלְאָן אַתָּה הוֹלֵךְ, לִמְקוֹם עָפָר רִמָּה וְתוֹלֵעָה. וְלִפְנֵי מִי אַתָּה עָתִיד לִתֵּן דִּין וְחֶשְׁבּוֹן, לִפְנֵי מֶלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדוֹשׁ בָּרוּךְ הוּא:"],
["Pirkei_Avot:3:2:0",0,3,2,"פרק ג׳, משנה ב׳","רַבִּי חֲנִינָא סְגַן הַכֹּהֲנִים אוֹמֵר, הֱוֵי מִתְפַּלֵּל בִּשְׁלוֹמָהּ שֶׁל מַלְכוּת, שֶׁאִלְמָלֵא מוֹרָאָהּ, אִישׁ אֶת רֵעֵהוּ חַיִּים בְּלָעוֹ. רַבִּי חֲנִינָא בֶן תְּרַדְיוֹן אוֹמֵר, שְׁנַיִם שֶׁיּוֹשְׁבִין וְאֵין בֵּינֵיהֶן דִּבְרֵי תוֹרָה, הֲרֵי זֶה מוֹשַׁב לֵצִים, שֶׁנֶּאֱמַר (תהלים א) וּבְמוֹשַׁב לֵצִים לֹא יָשָׁב. אֲבָל שְׁנַיִם שֶׁיּוֹשְׁבִין וְיֵשׁ בֵּינֵיהֶם דִּבְרֵי תוֹרָה, שְׁכִינָה שְׁרוּיָה בֵינֵיהֶם, שֶׁנֶּאֱמַר (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי יְיָ אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב יְיָ וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי יְיָ וּלְחֹשְׁבֵי שְׁמוֹ."],
["Pirkei_Avot:3:2:593",0,3,2,"פרק ג׳, משנה ב׳","אֵין לִי אֶלָּא שְׁנַיִם, מִנַּיִן שֶׁאֲפִלּוּ אֶחָד שֶׁיּוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹבֵעַ לוֹ שָׂכָר, שֶׁנֶּאֱמַר (איכה ג) יֵשֵׁב בָּדָד וְיִדֹּם כִּי נָטַל עָלָיו:"],
["Pirkei_Avot:3:3:0",0,3,3,"פרק ג׳, משנה ג׳","רַבִּי שִׁמְעוֹן אוֹמֵר, שְׁלשָׁה שֶׁאָכְלוּ עַל שֻׁלְחָן אֶחָד וְלֹא אָמְרוּ עָלָיו דִּבְרֵי תוֹרָה, כְּאִלּוּ אָכְלוּ מִזִּבְחֵי מֵתִים, שֶׁנֶּאֱמַר (ישעיה כח) כִּי כָּל שֻׁלְחָנוֹת מָלְאוּ קִיא צֹאָה בְּלִי מָקוֹם. אֲבָל שְׁלשָׁה שֶׁאָכְלוּ עַל שֻׁלְחָן אֶחָד וְאָמְרוּ עָלָיו דִּבְרֵי תוֹרָה, כְּאִלּוּ אָכְלוּ מִשֻּׁלְחָנוֹ שֶׁל מָקוֹם בָּרוּךְ הוּא, שֶׁנֶּאֱמַר (יחזקאל מא) וַיְדַבֵּר אֵלַי זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה':"],
["Pirkei_Avot:3:4:0",0,3,4,"פרק ג׳, משנה ד׳","רַבִּי חֲנִינָא בֶן חֲכִינַאי אוֹמֵר, הַנֵּעוֹר בַּלַּיְלָה וְהַמְהַלֵּךְ בַּדֶּרֶךְ יְחִידִי וְהַמְפַנֶּה לִבּוֹ לְבַטָּלָה, הֲרֵי זֶה מִתְחַיֵּב בְּנַפְשׁוֹ:"],
["Pirkei_Avot:3:5:0",0,3,5,"פרק ג׳, משנה ה׳","רַבִּי נְחוּנְיָא בֶּן הַקָּנָה אוֹמֵר, כָּל הַמְקַבֵּל עָלָיו עֹל תּוֹרָה, מַעֲבִירִין מִמֶּנּוּ עֹל מַלְכוּת וְעֹל דֶּרֶךְ אֶרֶץ. וְכָל הַפּוֹרֵק מִמֶּנּוּ עֹל תּוֹרָה, נוֹתְנִין עָלָיו עֹל מַלְכוּת וְעֹל דֶּרֶךְ אֶרֶץ:"],
["Pirkei_Avot:3:6:0",0,3,6,"פרק ג׳, משנה ו׳","רַבִּי חֲלַפְתָּא בֶן דּוֹסָא אִישׁ כְּפַר חֲנַנְיָה אוֹמֵר, עֲשָׂרָה שֶׁיּוֹשְׁבִין וְעוֹסְקִין בַּתּוֹרָה, שְׁכִינָה שְׁרוּיָה בֵינֵיהֶם, שֶׁנֶּאֱמַר (תהלים פב) אֱלֹהִים נִצָּב בַּעֲדַת אֵל. וּמִנַּיִן אֲפִלּוּ חֲמִשָּׁה, שֶׁנֶּאֱמַר (עמוס ט) וַאֲגֻדָּתוֹ עַל אֶרֶץ יְסָדָהּ. וּמִנַּיִן אֲפִלּוּ שְׁלשָׁה, שֶׁנֶּאֱמַר (תהלים פב) בְּקֶרֶב אֱלֹהִים יִשְׁפֹּט. וּמִנַּיִן אֲפִלּוּ שְׁנַיִם, שֶׁנֶּאֱמַר (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וְגוֹ'. וּמִנַּיִן אֲפִלּוּ אֶחָד, שֶׁנֶּאֱמַר (שמות כ) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי אָבֹא אֵלֶיךָ וּבֵרַכְתִּיךָ:"],
["Pirkei_Avot:3:7:0",0,3,7,"פרק ג׳, משנה ז׳","רַבִּי אֶלְעָזָר אִישׁ בַּרְתּוֹתָא אוֹמֵר, תֶּן לוֹ מִשֶּׁלּוֹ, שֶׁאַתָּה וְשֶׁלְּךָ שֶׁלּוֹ. וְכֵן בְּדָוִד הוּא אוֹמֵר (דברי הימים א כט) כִּי מִמְּךָ הַכֹּל וּמִיָּדְךָ נָתַנּוּ לָךְ. רַבִּי שִׁמְעוֹן אוֹמֵר, הַמְהַלֵּךְ בַּדֶּרֶךְ וְשׁוֹנֶה, וּמַפְסִיק מִמִּשְׁנָתוֹ וְאוֹמֵר, מַה נָּאֶה אִילָן זֶה וּמַה נָּאֶה נִיר זֶה, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ מִתְחַיֵּב בְּנַפְשׁוֹ:"],
["Pirkei_Avot:3:8:0",0,3,8,"פרק ג׳, משנה ח׳","רַבִּי דּוֹסְתַּאי בְּרַבִּי יַנַּאי מִשּׁוּם רַבִּי מֵאִיר אוֹמֵר, כָּל הַשּׁוֹכֵחַ דָּבָר אֶחָד מִמִּשְׁנָתוֹ, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ מִתְחַיֵּב בְּנַפְשׁוֹ, שֶׁנֶּאֱמַר (דברים ד) רַק הִשָּׁמֶר לְךָ וּשְׁמֹר נַפְשְׁךָ מְאֹד פֶּן תִּשְׁכַּח אֶת הַדְּבָרִים אֲשֶׁר רָאוּ עֵינֶיךָ. יָכוֹל אֲפִלּוּ תָקְפָה עָלָיו מִשְׁנָתוֹ, תַּלְמוּד לוֹמַר (שם) וּפֶן יָסוּרוּ מִלְּבָבְךָ כֹּל יְמֵי חַיֶּיךָ, הָא אֵינוֹ מִתְחַיֵּב בְּנַפְשׁוֹ עַד שֶׁיֵּשֵׁב וִיסִירֵם מִלִּבּוֹ:"],
["Pirkei_Avot:3:9:0",0,3,9,"פרק ג׳, משנה ט׳","רַבִּי חֲנִינָא בֶן דּוֹסָא אוֹמֵר, כָּל שֶׁיִּרְאַת חֶטְאוֹ קוֹדֶמֶת לְחָכְמָתוֹ, חָכְמָתוֹ מִתְקַיֶּמֶת. וְכָל שֶׁחָכְמָתוֹ קוֹדֶמֶת לְיִרְאַת חֶטְאוֹ, אֵין חָכְמָתוֹ מִתְקַיֶּמֶת. הוּא הָיָה אוֹמֵר, כָּל שֶׁמַּעֲשָׂיו מְרֻבִּין מֵחָכְמָתוֹ, חָכְמָתוֹ מִתְקַיֶּמֶת. וְכָל שֶׁחָכְמָתוֹ מְרֻבָּה מִמַּעֲשָׂיו, אֵין חָכְמָתוֹ מִתְקַיֶּמֶת:"],
["Pirkei_Avot:3:10:0",0,3,10,"פרק ג׳, משנה י׳","הוּא הָיָה אוֹמֵר, כָּל שֶׁרוּחַ הַבְּרִיּוֹת נוֹחָה הֵימֶנּוּ, רוּחַ הַמָּקוֹם נוֹחָה הֵימֶנּוּ. וְכָל שֶׁאֵין רוּחַ הַבְּרִיּוֹת נוֹחָה הֵימֶנּוּ, אֵין רוּחַ הַמָּקוֹם נוֹחָה הֵימֶנּוּ. רַבִּי דוֹסָא בֶן הַרְכִּינַס אוֹמֵר, שֵׁנָה שֶׁל שַׁחֲרִית, וְיַיִן שֶׁל צָהֳרַיִם, וְשִׂיחַת הַיְלָדִים, וִישִׁיבַת בָּתֵּי כְנֵסִיּוֹת שֶׁל עַמֵּי הָאָרֶץ, מוֹצִיאִין אֶת הָאָדָם מִן הָעוֹלָם:"],
["Pirkei_Avot:3:11:0",0,3,11,"פרק ג׳, משנה י״א","רַבִּי אֶלְעָזָר הַמּוֹדָעִי אוֹמֵר, הַמְחַלֵּל אֶת הַקָּדָשִׁים, וְהַמְבַזֶּה אֶת הַמּוֹעֲדוֹת, וְהַמַּלְבִּין פְּנֵי חֲבֵרוֹ בָרַבִּים, וְהַמֵּפֵר בְּרִיתוֹ שֶׁל אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם, וְהַמְגַלֶּה פָנִים בַּתּוֹרָה שֶׁלֹּא כַהֲלָכָה, אַף עַל פִּי שֶׁיֵּשׁ בְּיָדוֹ תוֹרָה וּמַעֲשִׂים טוֹבִים, אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא:"],
["Pirkei_Avot:3:12:0",0,3,12,"פרק ג׳, משנה י״ב","רַבִּי יִשְׁמָעֵאל אוֹמֵר, הֱוֵי קַל לְרֹאשׁ, וְנוֹחַ לְתִשְׁחֹרֶת, וֶהֱוֵי מְקַבֵּל אֶת כָּל הָאָדָם בְּשִׂמְחָה:"],
["Pirkei_Avot:3:13:0",0,3,13,"פרק ג׳, משנה י״ג","רַבִּי עֲקִיבָא אוֹמֵר, שְׂחוֹק וְקַלּוּת רֹאשׁ, מַרְגִּילִין לְעֶרְוָה. מָסֹרֶת, סְיָג לַתּוֹרָה. מַעַשְׂרוֹת, סְיָג לָעשֶׁר. נְדָרִים, סְיָג לַפְּרִישׁוּת. סְיָג לַחָכְמָה, שְׁתִיקָה:"],
["Pirkei_Avot:3:14:0",0,3,14,"פרק ג׳, משנה י״ד","הוּא הָיָה אוֹמֵר, חָבִיב אָדָם שֶׁנִּבְרָא בְצֶלֶם. חִבָּה יְתֵרָה נוֹדַעַת לוֹ שֶׁנִּבְרָא בְצֶלֶם, שֶׁנֶּאֱמַר (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. חֲבִיבִין יִשְׂרָאֵל שֶׁנִּקְרְאוּ בָנִים לַמָּקוֹם. חִבָּה יְתֵרָה נוֹדַעַת לָהֶם שֶׁנִּקְרְאוּ בָנִים לַמָּקוֹם, שֶׁנֶּאֱמַר (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. חֲבִיבִין יִשְׂרָאֵל שֶׁנִּתַּן לָהֶם כְּלִי חֶמְדָּה. חִבָּה יְתֵרָה נוֹדַעַת לָהֶם שֶׁנִּתַּן לָהֶם כְּלִי חֶמְדָּה שֶׁבּוֹ נִבְרָא הָעוֹלָם, שֶׁנֶּאֱמַר (משלי ד) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם, תּוֹרָתִי אַל תַּעֲזֹבוּ:"],
["Pirkei_Avot:3:15:0",0,3,15,"פרק ג׳, משנה ט״ו","הַכֹּל צָפוּי, וְהָרְשׁוּת נְתוּנָה, וּבְטוֹב הָעוֹלָם נִדּוֹן. וְהַכֹּל לְפִי רֹב הַמַּעֲשֶׂה:"],
["Pirkei_Avot:3:16:0",0,3,16,"פרק ג׳, משנה ט״ז","הוּא הָיָה אוֹמֵר, הַכֹּל נָתוּן בְּעֵרָבוֹן, וּמְצוּדָה פְרוּסָה עַל כָּל הַחַיִּים. הַחֲנוּת פְּתוּחָה, וְהַחֶנְוָנִי מֵקִיף, וְהַפִּנְקָס פָּתוּחַ, וְהַיָּד כּוֹתֶבֶת, וְכָל הָרוֹצֶה לִלְווֹת יָבֹא וְיִלְוֶה, וְהַגַּבָּאִים מַחֲזִירִים תָּדִיר בְּכָל יוֹם, וְנִפְרָעִין מִן הָאָדָם מִדַּעְתּוֹ וְשֶׁלֹּא מִדַּעְתּוֹ, וְיֵשׁ לָהֶם עַל מַה שֶּׁיִּסְמֹכוּ, וְהַדִּין דִּין אֱמֶת, וְהַכֹּל מְתֻקָּן לַסְּעוּדָה:"],
["Pirkei_Avot:3:17:0",0,3,17,"פרק ג׳, משנה י״ז","רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר, אִם אֵין תּוֹרָה, אֵין דֶּרֶךְ אֶרֶץ. אִם אֵין דֶּרֶךְ אֶרֶץ, אֵין תּוֹרָה. אִם אֵין חָכְמָה, אֵין יִרְאָה. אִם אֵין יִרְאָה, אֵין חָכְמָה. אִם אֵין בִּינָה, אֵין דַּעַת. אִם אֵין דַּעַת, אֵין בִּינָה. אִם אֵין קֶמַח, אֵין תּוֹרָה. אִם אֵין תּוֹרָה, אֵין קֶמַח. הוּא הָיָה אוֹמֵר, כָּל שֶׁחָכְמָתוֹ מְרֻבָּה מִמַּעֲשָׂיו, לְמַה הוּא דוֹמֶה, לְאִילָן שֶׁעֲנָפָיו מְרֻבִּין וְשָׁרָשָׁיו מֻעָטִין, וְהָרוּחַ בָּאָה וְעוֹקַרְתּוֹ וְהוֹפַכְתּוֹ עַל פָּנָיו, שֶׁנֶּאֱמַר (ירמיה יז) וְהָיָה כְּעַרְעָר בָּעֲרָבָה וְלֹא יִרְאֶה כִּי יָבוֹא טוֹב וְשָׁכַן חֲרֵרִים בַּמִּדְבָּר אֶרֶץ מְלֵחָה וְלֹא תֵשֵׁב."],
["Pirkei_Avot:3:17:636",0,3,17,"פרק ג׳, משנה י״ז","אֲבָל כָּל שֶׁמַּעֲשָׂיו מְרֻבִּין מֵחָכְמָתוֹ, לְמַה הוּא דוֹמֶה, לְאִילָן שֶׁעֲנָפָיו מֻעָטִין וְשָׁרָשָׁיו מְרֻבִּין, שֶׁאֲפִלּוּ כָל הָרוּחוֹת שֶׁבָּעוֹלָם בָּאוֹת וְנוֹשְׁבוֹת בּוֹ אֵין מְזִיזִין אוֹתוֹ מִמְּקוֹמוֹ, שֶׁנֶּאֱמַר (שם) וְהָיָה כְּעֵץ שָׁתוּל עַל מַיִם וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו וְלֹא יִרְאֶה כִּי יָבֹא חֹם, וְהָיָה עָלֵהוּ רַעֲנָן, וּבִשְׁנַת בַּצֹּרֶת לֹא יִדְאָג, וְלֹא יָמִישׁ מֵעֲשׂוֹת פֶּרִי:"],
["Pirkei_Avot:3:18:0",0,3,18,"פרק ג׳, משנה י״ח","רַבִּי אֱלִיעֶזֶר בֶּן חִסְמָא אוֹמֵר, קִנִּין וּפִתְחֵי נִדָּה, הֵן הֵן גּוּפֵי הֲלָכוֹת. תְּקוּפוֹת וְגִימַטְרִיאוֹת, פַּרְפְּרָאוֹת לַחָכְמָה:"],
["Pirkei_Avot:4:1:0",0,4,1,"פרק ד׳, משנה א׳","בֶּן זוֹמָא אוֹמֵר, אֵיזֶהוּ חָכָם, הַלּוֹמֵד מִכָּל אָדָם, שֶׁנֶּאֱמַר (תהלים קיט) מִכָּל מְלַמְּדַי הִשְׂכַּלְתִּי כִּי עֵדְוֹתֶיךָ שִׂיחָה לִּי. אֵיזֶהוּ גִבּוֹר, הַכּוֹבֵשׁ אֶת יִצְרוֹ, שֶׁנֶּאֱמַר (משלי טז) טוֹב אֶרֶךְ אַפַּיִם מִגִּבּוֹר וּמשֵׁל בְּרוּחוֹ מִלֹּכֵד עִיר. אֵיזֶהוּ עָשִׁיר, הַשָּׂמֵחַ בְּחֶלְקוֹ, שֶׁנֶּאֱמַר (תהלים קכח) יְגִיעַ כַּפֶּיךָ כִּי תֹאכֵל אַשְׁרֶיךָ וְטוֹב לָךְ. אַשְׁרֶיךָ, בָּעוֹלָם הַזֶּה. וְטוֹב לָךְ, לָעוֹלָם הַבָּא. אֵיזֶהוּ מְכֻבָּד, הַמְכַבֵּד אֶת הַבְּרִיּוֹת, שֶׁנֶּאֱמַר (שמואל א ב) כִּי מְכַבְּדַי אֲכַבֵּד וּבֹזַי יֵקָלּוּ:"],
["Pirkei_Avot:4:2:0",0,4,2,"פרק ד׳, משנה ב׳","בֶּן עַזַּאי אוֹמֵר, הֱוֵי רָץ לְמִצְוָה קַלָּה כְבַחֲמוּרָה, וּבוֹרֵחַ מִן הָעֲבֵרָה. שֶׁמִּצְוָה גּוֹרֶרֶת מִצְוָה, וַעֲבֵרָה גוֹרֶרֶת עֲבֵרָה. שֶׁשְּׂכַר מִצְוָה, מִצְוָה. וּשְׂכַר עֲבֵרָה, עֲבֵרָה:"],
["Pirkei_Avot:4:3:0",0,4,3,"פרק ד׳, משנה ג׳","הוּא הָיָה אוֹמֵר, אַל תְּהִי בָז לְכָל אָדָם, וְאַל תְּהִי מַפְלִיג לְכָל דָּבָר, שֶׁאֵין לְךָ אָדָם שֶׁאֵין לוֹ שָׁעָה וְאֵין לְךָ דָבָר שֶׁאֵין לוֹ מָקוֹם:"],
["Pirkei_Avot:4:4:0",0,4,4,"פרק ד׳, משנה ד׳","רַבִּי לְוִיטָס אִישׁ יַבְנֶה אוֹמֵר, מְאֹד מְאֹד הֱוֵי שְׁפַל רוּחַ, שֶׁתִּקְוַת אֱנוֹשׁ רִמָּה. רַבִּי יוֹחָנָן בֶּן בְּרוֹקָא אוֹמֵר, כָּל הַמְחַלֵּל שֵׁם שָׁמַיִם בַּסֵּתֶר, נִפְרָעִין מִמֶּנּוּ בְגָלוּי. אֶחָד שׁוֹגֵג וְאֶחָד מֵזִיד בְּחִלּוּל הַשֵּׁם:"],
["Pirkei_Avot:4:5:0",0,4,5,"פרק ד׳, משנה ה׳","רַבִּי יִשְׁמָעֵאל בְּנוֹ אוֹמֵר, הַלּוֹמֵד תּוֹרָה עַל מְנָת לְלַמֵּד, מַסְפִּיקִין בְּיָדוֹ לִלְמֹד וּלְלַמֵּד. וְהַלּוֹמֵד עַל מְנָת לַעֲשׂוֹת, מַסְפִּיקִין בְּיָדוֹ לִלְמֹד וּלְלַמֵּד לִשְׁמֹר וְלַעֲשׂוֹת. רַבִּי צָדוֹק אוֹמֵר, אַל תַּעֲשֵׂם עֲטָרָה לְהִתְגַּדֵּל בָּהֶם, וְלֹא קַרְדֹּם לַחְפֹּר בָּהֶם. וְכָךְ הָיָה הִלֵּל אוֹמֵר, וּדְאִשְׁתַּמֵּשׁ בְּתָגָא, חָלָף. הָא לָמַדְתָּ, כָּל הַנֶּהֱנֶה מִדִּבְרֵי תוֹרָה, נוֹטֵל חַיָּיו מִן הָעוֹלָם:"],
["Pirkei_Avot:4:6:0",0,4,6,"פרק ד׳, משנה ו׳","רַבִּי יוֹסֵי אוֹמֵר, כָּל הַמְכַבֵּד אֶת הַתּוֹרָה, גּוּפוֹ מְכֻבָּד עַל הַבְּרִיּוֹת. וְכָל הַמְחַלֵּל אֶת הַתּוֹרָה, גּוּפוֹ מְחֻלָּל עַל הַבְּרִיּוֹת:"],
["Pirkei_Avot:4:7:0",0,4,7,"פרק ד׳, משנה ז׳","רַבִּי יִשְׁמָעֵאל בְּנוֹ אוֹמֵר, הַחוֹשֵׂךְ עַצְמוֹ מִן הַדִּין, פּוֹרֵק מִמֶּנּוּ אֵיבָה וְגָזֵל וּשְׁבוּעַת שָׁוְא. וְהַגַּס לִבּוֹ בַהוֹרָאָה, שׁוֹטֶה רָשָׁע וְגַס רוּחַ:"],
["Pirkei_Avot:4:8:0",0,4,8,"פרק ד׳, משנה ח׳","הוּא הָיָה אוֹמֵר, אַל תְּהִי דָן יְחִידִי, שֶׁאֵין דָּן יְחִידִי אֶלָּא אֶחָד. וְאַל תֹּאמַר קַבְּלוּ דַעְתִּי, שֶׁהֵן רַשָּׁאִין וְלֹא אָתָּה:"],
["Pirkei_Avot:4:9:0",0,4,9,"פרק ד׳, משנה ט׳","רַבִּי יוֹנָתָן אוֹמֵר, כָּל הַמְקַיֵּם אֶת הַתּוֹרָה מֵעֹנִי, סוֹפוֹ לְקַיְּמָהּ מֵעשֶׁר. וְכָל הַמְבַטֵּל אֶת הַתּוֹרָה מֵעשֶׁר, סוֹפוֹ לְבַטְּלָהּ מֵעֹנִי:"],
["Pirkei_Avot:4:10:0",0,4,10,"פרק ד׳, משנה י׳","רַבִּי מֵאִיר אוֹמֵר, הֱוֵי מְמַעֵט בְּעֵסֶק, וַעֲסֹק בַּתּוֹרָה. וֶהֱוֵי שְׁפַל רוּחַ בִּפְנֵי כָל אָדָם. וְאִם בָּטַלְתָּ מִן הַתּוֹרָה, יֶשׁ לְךָ בְטֵלִים הַרְבֵּה כְנֶגְדָּךְ. וְאִם עָמַלְתָּ בַתּוֹרָה, יֶשׁ לוֹ שָׂכָר הַרְבֵּה לִתֶּן לָךְ:"],
["Pirkei_Avot:4:11:0",0,4,11,"פרק ד׳, משנה י״א","רַבִּי אֱלִיעֶזֶר בֶּן יַעֲקֹב אוֹמֵר, הָעוֹשֶׂה מִצְוָה אַחַת, קוֹנֶה לוֹ פְרַקְלִיט אֶחָד. וְהָעוֹבֵר עֲבֵרָה אַחַת, קוֹנֶה לוֹ קַטֵּגוֹר אֶחָד. תְּשׁוּבָה וּמַעֲשִׂים טוֹבִים, כִּתְרִיס בִּפְנֵי הַפֻּרְעָנוּת. רַבִּי יוֹחָנָן הַסַּנְדְּלָר אוֹמֵר, כָּל כְּנֵסִיָּה שֶׁהִיא לְשֵׁם שָׁמַיִם, סוֹפָהּ לְהִתְקַיֵּם. וְשֶׁאֵינָהּ לְשֵׁם שָׁמַיִם, אֵין סוֹפָהּ לְהִתְקַיֵּם:"],
["Pirkei_Avot:4:12:0",0,4,12,"פרק ד׳, משנה י״ב","רַבִּי אֶלְעָזָר בֶּן שַׁמּוּעַ אוֹמֵר, יְהִי כְבוֹד תַּלְמִידְךָ חָבִיב עָלֶיךָ כְּשֶׁלְּךָ, וּכְבוֹד חֲבֵרְךָ כְּמוֹרָא רַבְּךָ, וּמוֹרָא רַבְּךָ כְּמוֹרָא שָׁמָיִם:"],
["Pirkei_Avot:4:13:0",0,4,13,"פרק ד׳, משנה י״ג","רַבִּי יְהוּדָה אוֹמֵר, הֱוֵי זָהִיר בַּתַּלְמוּד, שֶׁשִּׁגְגַת תַּלְמוּד עוֹלָה זָדוֹן. רַבִּי שִׁמְעוֹן אוֹמֵר, שְׁלשָׁה כְתָרִים הֵם, כֶּתֶר תּוֹרָה וְכֶתֶר כְּהֻנָּה וְכֶתֶר מַלְכוּת, וְכֶתֶר שֵׁם טוֹב עוֹלֶה עַל גַּבֵּיהֶן:"],
["Pirkei_Avot:4:14:0",0,4,14,"פרק ד׳, משנה י״ד","רַבִּי נְהוֹרַאי אוֹמֵר, הֱוֵי גוֹלֶה לִמְקוֹם תּוֹרָה, וְאַל תֹּאמַר שֶׁהִיא תָבֹא אַחֲרֶיךָ, שֶׁחֲבֵרֶיךָ יְקַיְּמוּהָ בְיָדֶךָ. וְאֶל בִּינָתְךָ אַל תִּשָּׁעֵן (משלי ג):"],
["Pirkei_Avot:4:15:0",0,4,15,"פרק ד׳, משנה ט״ו","רַבִּי יַנַּאי אוֹמֵר, אֵין בְּיָדֵינוּ לֹא מִשַּׁלְוַת הָרְשָׁעִים וְאַף לֹא מִיִּסּוּרֵי הַצַּדִּיקִים. רַבִּי מַתְיָא בֶן חָרָשׁ אוֹמֵר, הֱוֵי מַקְדִּים בִּשְׁלוֹם כָּל אָדָם. וֶהֱוֵי זָנָב לָאֲרָיוֹת, וְאַל תְּהִי רֹאשׁ לַשּׁוּעָלִים:"],
["Pirkei_Avot:4:16:0",0,4,16,"פרק ד׳, משנה ט״ז","רַבִּי יַעֲקֹב אוֹמֵר, הָעוֹלָם הַזֶּה דּוֹמֶה לִפְרוֹזְדוֹר בִּפְנֵי הָעוֹלָם הַבָּא. הַתְקֵן עַצְמְךָ בַפְּרוֹזְדוֹר, כְּדֵי שֶׁתִּכָּנֵס לַטְּרַקְלִין:"],
["Pirkei_Avot:4:17:0",0,4,17,"פרק ד׳, משנה י״ז","הוּא הָיָה אוֹמֵר, יָפָה שָׁעָה אַחַת בִּתְשׁוּבָה וּמַעֲשִׂים טוֹבִים בָּעוֹלָם הַזֶּה, מִכָּל חַיֵּי הָעוֹלָם הַבָּא. וְיָפָה שָׁעָה אַחַת שֶׁל קוֹרַת רוּחַ בָּעוֹלָם הַבָּא, מִכָּל חַיֵּי הָעוֹלָם הַזֶּה:"],
["Pirkei_Avot:4:18:0",0,4,18,"פרק ד׳, משנה י״ח","רַבִּי שִׁמְעוֹן בֶּן אֶלְעָזָר אוֹמֵר, אַל תְּרַצֶּה אֶת חֲבֵרְךָ בִשְׁעַת כַּעֲסוֹ, וְאַל תְּנַחֲמֶנּוּ בְּשָׁעָה שֶׁמֵּתוֹ מֻטָּל לְפָנָיו, וְאַל תִּשְׁאַל לוֹ בִשְׁעַת נִדְרוֹ, וְאַל תִּשְׁתַּדֵּל לִרְאוֹתוֹ בִשְׁעַת קַלְקָלָתוֹ:"],
["Pirkei_Avot:4:19:0",0,4,19,"פרק ד׳, משנה י״ט","שְׁמוּאֵל הַקָּטָן אוֹמֵר, (משלי כד) בִּנְפֹל אוֹיִבְךָ אַל תִּשְׂמָח וּבִכָּשְׁלוֹ אַל יָגֵל לִבֶּךָ, פֶּן יִרְאֶה ה' וְרַע בְּעֵינָיו וְהֵשִׁיב מֵעָלָיו אַפּוֹ:"],
["Pirkei_Avot:4:20:0",0,4,20,"פרק ד׳, משנה כ׳","אֱלִישָׁע בֶּן אֲבוּיָה אוֹמֵר, הַלּוֹמֵד יֶלֶד לְמַה הוּא דוֹמֶה, לִדְיוֹ כְתוּבָה עַל נְיָר חָדָשׁ. וְהַלּוֹמֵד זָקֵן לְמַה הוּא דוֹמֶה, לִדְיוֹ כְתוּבָה עַל נְיָר מָחוּק. רַבִּי יוֹסֵי בַר יְהוּדָה אִישׁ כְּפַר הַבַּבְלִי אוֹמֵר, הַלּוֹמֵד מִן הַקְּטַנִּים לְמַה הוּא דוֹמֶה, לְאֹכֵל עֲנָבִים קֵהוֹת וְשׁוֹתֶה יַיִן מִגִּתּוֹ. וְהַלּוֹמֵד מִן הַזְּקֵנִים לְמַה הוּא דוֹמֶה, לְאֹכֵל עֲנָבִים בְּשֵׁלוֹת וְשׁוֹתֶה יַיִן יָשָׁן. רַבִּי אוֹמֵר, אַל תִּסְתַּכֵּל בַּקַּנְקַן, אֶלָּא בְמַה שֶּׁיֶּשׁ בּוֹ. יֵשׁ קַנְקַן חָדָשׁ מָלֵא יָשָׁן, וְיָשָׁן שֶׁאֲפִלּוּ חָדָשׁ אֵין בּוֹ:"],
["Pirkei_Avot:4:21:0",0,4,21,"פרק ד׳, משנה כ״א","רַבִּי אֶלְעָזָר הַקַּפָּר אוֹמֵר, הַקִּנְאָה וְהַתַּאֲוָה וְהַכָּבוֹד, מוֹצִיאִין אֶת הָאָדָם מִן הָעוֹלָם:"],
["Pirkei_Avot:4:22:0",0,4,22,"פרק ד׳, משנה כ״ב","הוּא הָיָה אוֹמֵר, הַיִּלּוֹדִים לָמוּת, וְהַמֵּתִים לְהֵחָיוֹת, וְהַחַיִּים לִדּוֹן. לֵידַע לְהוֹדִיעַ וּלְהִוָּדַע שֶׁהוּא אֵל, הוּא הַיּוֹצֵר, הוּא הַבּוֹרֵא, הוּא הַמֵּבִין, הוּא הַדַּיָּן, הוּא עֵד, הוּא בַעַל דִּין, וְהוּא עָתִיד לָדוּן. בָּרוּךְ הוּא, שֶׁאֵין לְפָנָיו לֹא עַוְלָה, וְלֹא שִׁכְחָה, וְלֹא מַשּׂוֹא פָנִים, וְלֹא מִקַּח שֹׁחַד, שֶׁהַכֹּל שֶׁלּוֹ. וְדַע שֶׁהַכֹּל לְפִי הַחֶשְׁבּוֹן."],
["Pirkei_Avot:4:22:404",0,4,22,"פרק ד׳, משנה כ״ב","וְאַל יַבְטִיחֲךָ יִצְרְךָ שֶׁהַשְּׁאוֹל בֵּית מָנוֹס לְךָ, שֶׁעַל כָּרְחֲךָ אַתָּה נוֹצָר, וְעַל כָּרְחֲךָ אַתָּה נוֹלָד, וְעַל כָּרְחֲךָ אַתָּה חַי, וְעַל כָּרְחֲךָ אַתָּה מֵת, וְעַל כָּרְחֲךָ אַתָּה עָתִיד לִתֵּן דִּין וְחֶשְׁבּוֹן לִפְנֵי מֶלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדוֹשׁ בָּרוּךְ הוּא:"],
["Pirkei_Avot:5:1:0",0,5,1,"פרק ה׳, משנה א׳","בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם. וּמַה תַּלְמוּד לוֹמַר, וַהֲלֹא בְמַאֲמָר אֶחָד יָכוֹל לְהִבָּרְאוֹת, אֶלָּא לְהִפָּרַע מִן הָרְשָׁעִים שֶׁמְּאַבְּדִין אֶת הָעוֹלָם שֶׁנִּבְרָא בַעֲשָׂרָה מַאֲמָרוֹת, וְלִתֵּן שָׂכָר טוֹב לַצַּדִּיקִים שֶׁמְּקַיְּמִין אֶת הָעוֹלָם שֶׁנִּבְרָא בַעֲשָׂרָה מַאֲמָרוֹת:"],
["Pirkei_Avot:5:2:0",0,5,2,"פרק ה׳, משנה ב׳","עֲשָׂרָה דוֹרוֹת מֵאָדָם וְעַד נֹחַ, לְהוֹדִיעַ כַּמָּה אֶרֶךְ אַפַּיִם לְפָנָיו, שֶׁכָּל הַדּוֹרוֹת הָיוּ מַכְעִיסִין וּבָאִין עַד שֶׁהֵבִיא עֲלֵיהֶם אֶת מֵי הַמַּבּוּל. עֲשָׂרָה דוֹרוֹת מִנֹּחַ וְעַד אַבְרָהָם, לְהוֹדִיעַ כַּמָּה אֶרֶךְ אַפַּיִם לְפָנָיו, שֶׁכָּל הַדּוֹרוֹת הָיוּ מַכְעִיסִין וּבָאִין, עַד שֶׁבָּא אַבְרָהָם וְקִבֵּל עָלָיו שְׂכַר כֻּלָּם:"],
["Pirkei_Avot:5:3:0",0,5,3,"פרק ה׳, משנה ג׳","עֲשָׂרָה נִסְיוֹנוֹת נִתְנַסָּה אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם וְעָמַד בְּכֻלָּם, לְהוֹדִיעַ כַּמָּה חִבָּתוֹ שֶׁל אַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם:"],
["Pirkei_Avot:5:4:0",0,5,4,"פרק ה׳, משנה ד׳","עֲשָׂרָה נִסִּים נַעֲשׂוּ לַאֲבוֹתֵינוּ בְמִצְרַיִם וַעֲשָׂרָה עַל הַיָּם. עֶשֶׂר מַכּוֹת הֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הַמִּצְרִיִּים בְּמִצְרַיִם וְעֶשֶׂר עַל הַיָּם. עֲשָׂרָה נִסְיוֹנוֹת נִסּוּ אֲבוֹתֵינוּ אֶת הַמָּקוֹם בָּרוּךְ הוּא בַמִּדְבָּר, שֶׁנֶּאֱמַר (במדבר יד) וַיְנַסּוּ אֹתִי זֶה עֶשֶׂר פְּעָמִים וְלֹא שָׁמְעוּ בְּקוֹלִי:"],
["Pirkei_Avot:5:5:0",0,5,5,"פרק ה׳, משנה ה׳","עֲשָׂרָה נִסִּים נַעֲשׂוּ לַאֲבוֹתֵינוּ בְּבֵית הַמִּקְדָּשׁ. לֹא הִפִּילָה אִשָּׁה מֵרֵיחַ בְּשַׂר הַקֹּדֶשׁ, וְלֹא הִסְרִיחַ בְּשַׂר הַקֹּדֶשׁ מֵעוֹלָם, וְלֹא נִרְאָה זְבוּב בְּבֵית הַמִּטְבָּחַיִם, וְלֹא אֵרַע קֶרִי לְכֹהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים, וְלֹא כִבּוּ גְשָׁמִים אֵשׁ שֶׁל עֲצֵי הַמַּעֲרָכָה, וְלֹא נָצְחָה הָרוּחַ אֶת עַמּוּד הֶעָשָׁן, וְלֹא נִמְצָא פְסוּל בָּעֹמֶר וּבִשְׁתֵּי הַלֶּחֶם וּבְלֶחֶם הַפָּנִים, עוֹמְדִים צְפוּפִים וּמִשְׁתַּחֲוִים רְוָחִים, וְלֹא הִזִּיק נָחָשׁ וְעַקְרָב בִּירוּשָׁלַיִם מֵעוֹלָם, וְלֹא אָמַר אָדָם לַחֲבֵרוֹ צַר לִי הַמָּקוֹם שֶׁאָלִין בִּירוּשָׁלַיִם:"],
["Pirkei_Avot:5:6:0",0,5,6,"פרק ה׳, משנה ו׳","עֲשָׂרָה דְבָרִים נִבְרְאוּ בְּעֶרֶב שַׁבָּת בֵּין הַשְּׁמָשׁוֹת, וְאֵלּוּ הֵן, פִּי הָאָרֶץ, וּפִי הַבְּאֵר, וּפִי הָאָתוֹן, וְהַקֶּשֶׁת, וְהַמָּן, וְהַמַּטֶּה, וְהַשָּׁמִיר, וְהַכְּתָב, וְהַמִּכְתָּב, וְהַלּוּחוֹת. וְיֵשׁ אוֹמְרִים, אַף הַמַּזִּיקִין, וּקְבוּרָתוֹ שֶׁל משֶׁה, וְאֵילוֹ שֶׁל אַבְרָהָם אָבִינוּ. וְיֵשׁ אוֹמְרִים, אַף צְבָת בִּצְבָת עֲשׂוּיָה:"],
["Pirkei_Avot:5:7:0",0,5,7,"פרק ה׳, משנה ז׳","שִׁבְעָה דְבָרִים בַּגֹּלֶם וְשִׁבְעָה בֶחָכָם. חָכָם אֵינוֹ מְדַבֵּר בִּפְנֵי מִי שֶׁהוּא גָדוֹל מִמֶּנּוּ בְחָכְמָה וּבְמִנְיָן, וְאֵינוֹ נִכְנָס לְתוֹךְ דִּבְרֵי חֲבֵרוֹ, וְאֵינוֹ נִבְהָל לְהָשִׁיב, שׁוֹאֵל כָּעִנְיָן וּמֵשִׁיב כַּהֲלָכָה, וְאוֹמֵר עַל רִאשׁוֹן רִאשׁוֹן וְעַל אַחֲרוֹן אַחֲרוֹן, וְעַל מַה שֶּׁלֹּא שָׁמַע, אוֹמֵר לֹא שָׁמָעְתִּי, וּמוֹדֶה עַל הָאֱמֶת. וְחִלּוּפֵיהֶן בַּגֹּלֶם:"],
["Pirkei_Avot:5:8:0",0,5,8,"פרק ה׳, משנה ח׳","שִׁבְעָה מִינֵי פֻרְעָנֻיּוֹת בָּאִין לָעוֹלָם עַל שִׁבְעָה גוּפֵי עֲבֵרָה. מִקְצָתָן מְעַשְּׂרִין וּמִקְצָתָן אֵינָן מְעַשְּׂרִין, רָעָב שֶׁל בַּצֹּרֶת בָּאָה, מִקְצָתָן רְעֵבִים וּמִקְצָתָן שְׂבֵעִים. גָּמְרוּ שֶׁלֹּא לְעַשֵּׂר, רָעָב שֶׁל מְהוּמָה וְשֶׁל בַּצֹּרֶת בָּאָה. וְשֶׁלֹּא לִטֹּל אֶת הַחַלָּה, רָעָב שֶׁל כְּלָיָה בָאָה. דֶּבֶר בָּא לָעוֹלָם עַל מִיתוֹת הָאֲמוּרוֹת בַּתּוֹרָה שֶׁלֹּא נִמְסְרוּ לְבֵית דִּין, וְעַל פֵּרוֹת שְׁבִיעִית. חֶרֶב בָּאָה לָעוֹלָם עַל עִנּוּי הַדִּין, וְעַל עִוּוּת הַדִּין, וְעַל הַמּוֹרִים בַּתּוֹרָה שֶׁלֹּא כַהֲלָכָה:"],
["Pirkei_Avot:5:9:0",0,5,9,"פרק ה׳, משנה ט׳","חַיָּה רָעָה בָאָה לָעוֹלָם עַל שְׁבוּעַת שָׁוְא, וְעַל חִלּוּל הַשֵּׁם. גָּלוּת בָּאָה לָעוֹלָם עַל עוֹבְדֵי עֲבוֹדָה זָרָה, וְעַל גִלּוּי עֲרָיוֹת, וְעַל שְׁפִיכוּת דָּמִים, וְעַל הַשְׁמָטַת הָאָרֶץ. בְּאַרְבָּעָה פְרָקִים הַדֶּבֶר מִתְרַבֶּה, בָּרְבִיעִית, וּבַשְּׁבִיעִית, וּבְמוֹצָאֵי שְׁבִיעִית, וּבְמוֹצָאֵי הֶחָג שֶׁבְּכָל שָׁנָה וְשָׁנָה. בָּרְבִיעִית, מִפְּנֵי מַעְשַׂר עָנִי שֶׁבַּשְּׁלִישִׁית. בַּשְּׁבִיעִית, מִפְּנֵי מַעְשַׂר עָנִי שֶׁבַּשִּׁשִּׁית. וּבְמוֹצָאֵי שְׁבִיעִית, מִפְּנֵי פֵרוֹת שְׁבִיעִית. וּבְמוֹצָאֵי הֶחָג שֶׁבְּכָל שָׁנָה וְשָׁנָה, מִפְּנֵי גֶזֶל מַתְּנוֹת עֲנִיִּים:"],
["Pirkei_Avot:5:10:0",0,5,10,"פרק ה׳, משנה י׳","אַרְבַּע מִדּוֹת בָּאָדָם. הָאוֹמֵר שֶׁלִּי שֶׁלִּי וְשֶׁלְּךָ שֶׁלָּךְ, זוֹ מִדָּה בֵינוֹנִית. וְיֵשׁ אוֹמְרִים, זוֹ מִדַּת סְדוֹם. שֶׁלִּי שֶׁלְּךָ וְשֶׁלְּךָ שֶׁלִּי, עַם הָאָרֶץ. שֶׁלִּי שֶׁלְּךָ וְשֶׁלְּךָ שֶׁלָּךְ, חָסִיד. שֶׁלִּי שֶׁלִּי וְשֶׁלְּךָ שֶׁלִּי, רָשָׁע:"],
["Pirkei_Avot:5:11:0",0,5,11,"פרק ה׳, משנה י״א","אַרְבַּע מִדּוֹת בַּדֵּעוֹת. נוֹחַ לִכְעֹס וְנוֹחַ לִרְצוֹת, יָצָא שְׂכָרוֹ בְהֶפְסֵדוֹ. קָשֶׁה לִכְעֹס וְקָשֶׁה לִרְצוֹת, יָצָא הֶפְסֵדוֹ בִשְׂכָרוֹ. קָשֶׁה לִכְעֹס וְנוֹחַ לִרְצוֹת, חָסִיד. נוֹחַ לִכְעֹס וְקָשֶׁה לִרְצוֹת, רָשָׁע:"],
["Pirkei_Avot:5:12:0",0,5,12,"פרק ה׳, משנה י״ב","אַרְבַּע מִדּוֹת בַּתַּלְמִידִים. מַהֵר לִשְׁמֹעַ וּמַהֵר לְאַבֵּד, יָצָא שְׂכָרוֹ בְהֶפְסֵדוֹ. קָשֶׁה לִשְׁמֹעַ וְקָשֶׁה לְאַבֵּד, יָצָא הֶפְסֵדוֹ בִשְׂכָרוֹ. מַהֵר לִשְׁמֹעַ וְקָשֶׁה לְאַבֵּד, חָכָם. קָשֶׁה לִשְׁמֹעַ וּמַהֵר לְאַבֵּד, זֶה חֵלֶק רָע:"],
["Pirkei_Avot:5:13:0",0,5,13,"פרק ה׳, משנה י״ג","אַרְבַּע מִדּוֹת בְּנוֹתְנֵי צְדָקָה. הָרוֹצֶה שֶׁיִּתֵּן וְלֹא יִתְּנוּ אֲחֵרִים, עֵינוֹ רָעָה בְּשֶׁל אֲחֵרִים. יִתְּנוּ אֲחֵרִים וְהוּא לֹא יִתֵּן, עֵינוֹ רָעָה בְשֶׁלּוֹ. יִתֵּן וְיִתְּנוּ אֲחֵרִים, חָסִיד. לֹא יִתֵּן וְלֹא יִתְּנוּ אֲחֵרִים, רָשָׁע:"],
["Pirkei_Avot:5:14:0",0,5,14,"פרק ה׳, משנה י״ד","אַרְבַּע מִדּוֹת בְּהוֹלְכֵי לְבֵית הַמִּדְרָשׁ. הוֹלֵךְ וְאֵינוֹ עוֹשֶׂה, שְׂכַר הֲלִיכָה בְיָדוֹ. עוֹשֶׂה וְאֵינוֹ הוֹלֵךְ, שְׂכַר מַעֲשֶׂה בְיָדוֹ. הוֹלֵךְ וְעוֹשֶׂה, חָסִיד. לֹא הוֹלֵךְ וְלֹא עוֹשֶׂה, רָשָׁע:"],
["Pirkei_Avot:5:15:0",0,5,15,"פרק ה׳, משנה ט״ו","אַרְבַּע מִדּוֹת בְּיוֹשְׁבִים לִפְנֵי חֲכָמִים. סְפוֹג, וּמַשְׁפֵּךְ, מְשַׁמֶּרֶת, וְנָפָה. סְפוֹג, שֶׁהוּא סוֹפֵג אֶת הַכֹּל. מַשְׁפֵּךְ, שֶׁמַּכְנִיס בְּזוֹ וּמוֹצִיא בְזוֹ. מְשַׁמֶּרֶת, שֶׁמּוֹצִיאָה אֶת הַיַּיִן וְקוֹלֶטֶת אֶת הַשְּׁמָרִים. וְנָפָה, שֶׁמּוֹצִיאָה אֶת הַקֶּמַח וְקוֹלֶטֶת אֶת הַסֹּלֶת:"],
["Pirkei_Avot:5:16:0",0,5,16,"פרק ה׳, משנה ט״ז","כָּל אַהֲבָה שֶׁהִיא תְלוּיָה בְדָבָר, בָּטֵל דָּבָר, בְּטֵלָה אַהֲבָה. וְשֶׁאֵינָהּ תְּלוּיָה בְדָבָר, אֵינָהּ בְּטֵלָה לְעוֹלָם. אֵיזוֹ הִיא אַהֲבָה הַתְּלוּיָה בְדָבָר, זוֹ אַהֲבַת אַמְנוֹן וְתָמָר. וְשֶׁאֵינָהּ תְּלוּיָה בְדָבָר, זוֹ אַהֲבַת דָּוִד וִיהוֹנָתָן:"],
["Pirkei_Avot:5:17:0",0,5,17,"פרק ה׳, משנה י״ז","כָּל מַחֲלֹקֶת שֶׁהִיא לְשֵׁם שָׁמַיִם, סוֹפָהּ לְהִתְקַיֵּם. וְשֶׁאֵינָהּ לְשֵׁם שָׁמַיִם, אֵין סוֹפָהּ לְהִתְקַיֵּם. אֵיזוֹ הִיא מַחֲלֹקֶת שֶׁהִיא לְשֵׁם שָׁמַיִם, זוֹ מַחֲלֹקֶת הִלֵּל וְשַׁמַּאי. וְשֶׁאֵינָהּ לְשֵׁם שָׁמַיִם, זוֹ מַחֲלֹקֶת קֹרַח וְכָל עֲדָתוֹ:"],
["Pirkei_Avot:5:18:0",0,5,18,"פרק ה׳, משנה י״ח","כָּל הַמְזַכֶּה אֶת הָרַבִּים, אֵין חֵטְא בָּא עַל יָדוֹ. וְכָל הַמַּחֲטִיא אֶת הָרַבִּים, אֵין מַסְפִּיקִין בְּיָדוֹ לַעֲשׂוֹת תְּשׁוּבָה. משֶׁה זָכָה וְזִכָּה אֶת הָרַבִּים, זְכוּת הָרַבִּים תָּלוּי בּוֹ, שֶׁנֶּאֱמַר (דברים לג) צִדְקַת ה' עָשָׂה וּמִשְׁפָּטָיו עִם יִשְׂרָאֵל. יָרָבְעָם חָטָא וְהֶחֱטִיא אֶת הָרַבִּים, חֵטְא הָרַבִּים תָּלוּי בּוֹ, שֶׁנֶּאֱמַר (מלכים א טו) עַל חַטֹּאות יָרָבְעָם (בֶּן נְבָט) אֲשֶׁר חָטָא וַאֲשֶׁר הֶחֱטִיא אֶת יִשְׂרָאֵל:"],
["Pirkei_Avot:5:19:0",0,5,19,"פרק ה׳, משנה י״ט","כָּל מִי שֶׁיֵּשׁ בְּיָדוֹ שְׁלשָׁה דְבָרִים הַלָּלוּ, מִתַּלְמִידָיו שֶׁל אַבְרָהָם אָבִינוּ. וּשְׁלשָׁה דְבָרִים אֲחֵרִים, מִתַּלְמִידָיו שֶׁל בִּלְעָם הָרָשָׁע. עַיִן טוֹבָה, וְרוּחַ נְמוּכָה, וְנֶפֶשׁ שְׁפָלָה, מִתַּלְמִידָיו שֶׁל אַבְרָהָם אָבִינוּ. עַיִן רָעָה, וְרוּחַ גְּבוֹהָה, וְנֶפֶשׁ רְחָבָה, מִתַּלְמִידָיו שֶׁל בִּלְעָם הָרָשָׁע. מַה בֵּין תַּלְמִידָיו שֶׁל אַבְרָהָם אָבִינוּ לְתַלְמִידָיו שֶׁל בִּלְעָם הָרָשָׁע. תַּלְמִידָיו שֶׁל אַבְרָהָם אָבִינוּ, אוֹכְלִין בָּעוֹלָם הַזֶּה וְנוֹחֲלִין בָּעוֹלָם הַבָּא, שֶׁנֶּאֱמַר (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ, וְאֹצְרֹתֵיהֶם אֲמַלֵּא."],
["Pirkei_Avot:5:19:595",0,5,19,"פרק ה׳, משנה י״ט","אֲבָל תַּלְמִידָיו שֶׁל בִּלְעָם הָרָשָׁע יוֹרְשִׁין גֵּיהִנֹּם וְיוֹרְדִין לִבְאֵר שַׁחַת, שֶׁנֶּאֱמַר (תהלים נה) וְאַתָּה אֱלֹהִים תּוֹרִידֵם לִבְאֵר שַׁחַת, אַנְשֵׁי דָמִים וּמִרְמָה לֹא יֶחֱצוּ יְמֵיהֶם, וַאֲנִי אֶבְטַח בָּךְ:"],
["Pirkei_Avot:5:20:0",0,5,20,"פרק ה׳, משנה כ׳","יְהוּדָה בֶן תֵּימָא אוֹמֵר, הֱוֵי עַז כַּנָּמֵר, וְקַל כַּנֶּשֶׁר, וְרָץ כַּצְּבִי, וְגִבּוֹר כָּאֲרִי, לַעֲשׂוֹת רְצוֹן אָבִיךָ שֶׁבַּשָּׁמָיִם. הוּא הָיָה אוֹמֵר, עַז פָּנִים לְגֵיהִנֹּם, וּבֹשֶׁת פָּנִים לְגַן עֵדֶן. יְהִי רָצוֹן מִלְּפָנֶיךָ יְיָ אֱלֹהֵינוּ שֶׁתִּבְנֶה עִירְךָ בִּמְהֵרָה בְיָמֵינוּ וְתֵן חֶלְקֵנוּ בְתוֹרָתֶךָ:"],
["Pirkei_Avot:5:21:0",0,5,21,"פרק ה׳, משנה כ״א","הוּא הָיָה אוֹמֵר, בֶּן חָמֵשׁ שָׁנִים לַמִּקְרָא, בֶּן עֶשֶׂר לַמִּשְׁנָה, בֶּן שְׁלשׁ עֶשְׂרֵה לַמִּצְוֹת, בֶּן חֲמֵשׁ עֶשְׂרֵה לַתַּלְמוּד, בֶּן שְׁמֹנֶה עֶשְׂרֵה לַחֻפָּה, בֶּן עֶשְׂרִים לִרְדֹּף, בֶּן שְׁלשִׁים לַכֹּחַ, בֶּן אַרְבָּעִים לַבִּינָה, בֶּן חֲמִשִּׁים לָעֵצָה, בֶּן שִׁשִּׁים לַזִּקְנָה, בֶּן שִׁבְעִים לַשֵּׂיבָה, בֶּן שְׁמֹנִים לַגְּבוּרָה, בֶּן תִּשְׁעִים לָשׁוּחַ, בֶּן מֵאָה כְּאִלּוּ מֵת וְעָבַר וּבָטֵל מִן הָעוֹלָם:"],
["Pirkei_Avot:5:22:0",0,5,22,"פרק ה׳, משנה כ״ב","בֶּן בַּג בַּג אוֹמֵר, הֲפֹךְ בָּהּ וַהֲפֹךְ בָּהּ, דְּכֹלָּא בָהּ. וּבָהּ תֶּחֱזֵי, וְסִיב וּבְלֵה בָהּ, וּמִנַּהּ לֹא תָזוּעַ, שֶׁאֵין לְךָ מִדָּה טוֹבָה הֵימֶנָּה:"],
["Pirkei_Avot:5:23:0",0,5,23,"פרק ה׳, משנה כ״ג","בֶּן הֵא הֵא אוֹמֵר, לְפוּם צַעֲרָא אַגְרָא:"],
["Pirkei_Avot:6:1:0",0,6,1,"פרק ו׳, משנה א׳","שָׁנוּ חֲכָמִים בִּלְשׁוֹן הַמִּשְׁנָה, בָּרוּךְ שֶׁבָּחַר בָּהֶם וּבְמִשְׁנָתָם: רַבִּי מֵאִיר אוֹמֵר כָּל הָעוֹסֵק בַּתּוֹרָה לִשְׁמָהּ, זוֹכֶה לִדְבָרִים הַרְבֵּה. וְלֹא עוֹד אֶלָּא שֶׁכָּל הָעוֹלָם כֻּלּוֹ כְדַי הוּא לוֹ. נִקְרָא רֵעַ, אָהוּב, אוֹהֵב אֶת הַמָּקוֹם, אוֹהֵב אֶת הַבְּרִיּוֹת, מְשַׂמֵּחַ אֶת הַמָּקוֹם, מְשַׂמֵּחַ אֶת הַבְּרִיּוֹת. וּמַלְבַּשְׁתּוֹ עֲנָוָה וְיִרְאָה, וּמַכְשַׁרְתּוֹ לִהְיוֹת צַדִּיק וְחָסִיד וְיָשָׁר וְנֶאֱמָן, וּמְרַחַקְתּוֹ מִן הַחֵטְא, וּמְקָרַבְתּוֹ לִידֵי זְכוּת, וְנֶהֱנִין מִמֶּנּוּ עֵצָה וְתוּשִׁיָּה בִּינָה וּגְבוּרָה, שֶׁנֶּאֱמַר (משלי ח) לִי עֵצָה וְתוּשִׁיָּה אֲנִי בִינָה לִי גְבוּרָה."],
["Pirkei_Avot:6:1:637",0,6,1,"פרק ו׳, משנה א׳","וְנוֹתֶנֶת לוֹ מַלְכוּת וּמֶמְשָׁלָה וְחִקּוּר דִּין, וּמְגַלִּין לוֹ רָזֵי תוֹרָה, וְנַעֲשֶׂה כְמַעְיָן הַמִּתְגַּבֵּר וּכְנָהָר שֶׁאֵינוֹ פוֹסֵק, וֶהֱוֵי צָנוּעַ וְאֶרֶךְ רוּחַ, וּמוֹחֵל עַל עֶלְבּוֹנוֹ, וּמְגַדַּלְתּוֹ וּמְרוֹמַמְתּוֹ עַל כָּל הַמַּעֲשִׂים:"],
["Pirkei_Avot:6:2:0",0,6,2,"פרק ו׳, משנה ב׳","אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי, בְּכָל יוֹם וָיוֹם בַּת קוֹל יוֹצֵאת מֵהַר חוֹרֵב וּמַכְרֶזֶת וְאוֹמֶרֶת, אוֹי לָהֶם לַבְּרִיּוֹת מֵעֶלְבּוֹנָהּ שֶׁל תּוֹרָה. שֶׁכָּל מִי שֶׁאֵינוֹ עוֹסֵק בַּתּוֹרָה נִקְרָא נָזוּף, שֶׁנֶּאֱמַר (משלי יא) נֶזֶם זָהָב בְּאַף חֲזִיר אִשָּׁה יָפָה וְסָרַת טָעַם. וְאוֹמֵר (שמות לב) וְהַלֻּחֹת מַעֲשֵׂה אֱלֹהִים הֵמָּה וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא חָרוּת עַל הַלֻּחֹת, אַל תִּקְרָא חָרוּת אֶלָּא חֵרוּת, שֶׁאֵין לְךָ בֶן חוֹרִין אֶלָּא מִי שֶׁעוֹסֵק בְּתַלְמוּד תּוֹרָה. וְכָל מִי שֶׁעוֹסֵק בְּתַלְמוּד תּוֹרָה הֲרֵי זֶה מִתְעַלֶּה, שֶׁנֶּאֱמַר (במדבר כא) וּמִמַּתָּנָה נַחֲלִיאֵל וּמִנַּחֲלִיאֵל בָּמוֹת:"],
["Pirkei_Avot:6:3:0",0,6,3,"פרק ו׳, משנה ג׳","הַלּוֹמֵד מֵחֲבֵרוֹ פֶּרֶק אֶחָד אוֹ הֲלָכָה אַחַת אוֹ פָסוּק אֶחָד אוֹ דִבּוּר אֶחָד אוֹ אֲפִלּוּ אוֹת אַחַת, צָרִיךְ לִנְהוֹג בּוֹ כָבוֹד, שֶׁכֵּן מָצִינוּ בְדָוִד מֶלֶךְ יִשְׂרָאֵל, שֶׁלֹּא לָמַד מֵאֲחִיתֹפֶל אֶלָּא שְׁנֵי דְבָרִים בִּלְבָד, קְרָאוֹ רַבּוֹ אַלּוּפוֹ וּמְיֻדָּעוֹ, שֶׁנֶּאֱמַר (תהלים נה) וְאַתָּה אֱנוֹשׁ כְּעֶרְכִּי אַלּוּפִי וּמְיֻדָּעִי."],
["Pirkei_Avot:6:3:360",0,6,3,"פרק ו׳, משנה ג׳","וַהֲלֹא דְבָרִים קַל וָחֹמֶר, וּמַה דָּוִד מֶלֶךְ יִשְׂרָאֵל, שֶׁלֹּא לָמַד מֵאֲחִיתֹפֶל אֶלָּא שְׁנֵי דְבָרִים בִּלְבַד קְרָאוֹ רַבּוֹ אַלּוּפוֹ וּמְיֻדָּעוֹ, הַלּוֹמֵד מֵחֲבֵרוֹ פֶּרֶק אֶחָד אוֹ הֲלָכָה אַחַת אוֹ פָסוּק אֶחָד אוֹ דִבּוּר אֶחָד אוֹ אֲפִלּוּ אוֹת אַחַת, עַל אַחַת כַּמָּה וְכַמָּה שֶׁצָּרִיךְ לִנְהוֹג בּוֹ כָבוֹד. וְאֵין כָּבוֹד אֶלָּא תוֹרָה, שֶׁנֶּאֱמַר (משלי ג) כָּבוֹד חֲכָמִים יִנְחָלוּ, (משלי כח) וּתְמִימִים יִנְחֲלוּ טוֹב, וְאֵין טוֹב אֶלָּא תוֹרָה, שֶׁנֶּאֱמַר (משלי ד) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִי אַל תַּעֲזֹבוּ:"],
["Pirkei_Avot:6:4:0",0,6,4,"פרק ו׳, משנה ד׳","כַּךְ הִיא דַּרְכָּהּ שֶׁל תּוֹרָה, פַּת בְּמֶלַח תֹּאכַל, וּמַיִם בִּמְשׂוּרָה תִשְׁתֶּה, וְעַל הָאָרֶץ תִּישַׁן, וְחַיֵּי צַעַר תִּחְיֶה, וּבַתּוֹרָה אַתָּה עָמֵל, אִם אַתָּה עֹשֶׂה כֵן, (תהלים קכח) אַשְׁרֶיךָ וְטוֹב לָךְ. אַשְׁרֶיךָ בָּעוֹלָם הַזֶּה וְטוֹב לָךְ לָעוֹלָם הַבָּא:"],
["Pirkei_Avot:6:5:0",0,6,5,"פרק ו׳, משנה ה׳","אַל תְּבַקֵּשׁ גְּדֻלָּה לְעַצְמְךָ, וְאַל תַּחְמֹד כָּבוֹד, יוֹתֵר מִלִּמּוּדְךָ עֲשֵׂה, וְאַל תִּתְאַוֶּה לְשֻׁלְחָנָם שֶׁל מְלָכִים, שֶׁשֻּׁלְחָנְךָ גָדוֹל מִשֻּׁלְחָנָם, וְכִתְרְךָ גָדוֹל מִכִּתְרָם, וְנֶאֱמָן הוּא בַּעַל מְלַאכְתְּךָ שֶׁיְּשַׁלֵּם לְךָ שְׂכַר פְּעֻלָּתֶךָ:"],
["Pirkei_Avot:6:6:0",0,6,6,"פרק ו׳, משנה ו׳","גְּדוֹלָה תוֹרָה יוֹתֵר מִן הַכְּהֻנָּה וּמִן הַמַּלְכוּת, שֶׁהַמַּלְכוּת נִקְנֵית בִּשְׁלֹשִׁים מַעֲלוֹת, וְהַכְּהֻנָּה בְּעֶשְׂרִים וְאַרְבַּע, וְהַתּוֹרָה נִקְנֵית בְּאַרְבָּעִים וּשְׁמֹנָה דְבָרִים."],
["Pirkei_Avot:6:6:203",0,6,6,"פרק ו׳, משנה ו׳","וְאֵלוּ הֵן, בְּתַלְמוּד, בִּשְׁמִיעַת הָאֹזֶן, בַּעֲרִיכַת שְׂפָתַיִם, בְּבִינַת הַלֵּב, בְּשִׂכְלוּת הַלֵּב, בְּאֵימָה, בְּיִרְאָה, בַּעֲנָוָה, בְּשִׂמְחָה, בְּטָהֳרָה, בְּשִׁמּוּשׁ חֲכָמִים, בְּדִקְדּוּק חֲבֵרִים, וּבְפִלְפּוּל הַתַּלְמִידִים, בְּיִשּׁוּב, בַּמִּקְרָא, בַּמִּשְׁנָה, בְּמִעוּט סְחוֹרָה, בְּמִעוּט דֶּרֶךְ אֶרֶץ, בְּמִעוּט תַּעֲנוּג, בְּמִעוּט שֵׁינָה, בְּמִעוּט שִׂיחָה, בְּמִעוּט שְׂחוֹק, בְּאֶרֶךְ אַפַּיִם, בְּלֵב טוֹב, בֶּאֱמוּנַת חֲכָמִים, וּבְקַבָּלַת הַיִּסּוּרִין, הַמַּכִּיר אֶת מְקוֹמוֹ, וְהַשָּׂמֵחַ בְּחֶלְקוֹ, וְהָעוֹשֶׂה סְיָג לִדְבָרָיו, וְאֵינוֹ מַחֲזִיק טוֹבָה לְעַצְמוֹ, אָהוּב, אוֹהֵב אֶת הַמָּקוֹם, אוֹהֵב אֶת הַבְּרִיּוֹת, אוֹהֵב אֶת הַצְּדָקוֹת, אוֹהֵב אֶת הַמֵּישָׁרִים, אוֹהֵב אֶת הַתּוֹכָחוֹת, מִתְרַחֵק מִן הַכָּבוֹד, וְלֹא מֵגִיס לִבּוֹ בְתַלְמוּדוֹ, וְאֵינוֹ שָׂמֵחַ בְּהוֹרָאָה, נוֹשֵׂא בְעֹל עִם חֲבֵרוֹ, מַכְרִיעוֹ לְכַף זְכוּת, מַעֲמִידוֹ עַל הָאֱמֶת, וּמַעֲמִידוֹ עַל הַשָּׁלוֹם, מִתְיַשֵּׁב לִבּוֹ בְתַלְמוּדוֹ, שׁוֹאֵל וּמֵשִׁיב, שׁוֹמֵעַ וּמוֹסִיף, הַלּוֹמֵד עַל מְנָת לְלַמֵּד וְהַלּוֹמֵד עַל מְנָת לַעֲשׂוֹת, הַמַּחְכִּים אֶת רַבּוֹ, וְהַמְכַוֵּן אֶת שְׁמוּעָתוֹ, וְהָאוֹמֵר דָּבָר בְּשֵׁם אוֹמְרוֹ, הָא לָמַדְתָּ שֶׁכָּל הָאוֹמֵר דָּבָר בְּשֵׁם אוֹמְרוֹ מֵבִיא גְאֻלָּה לָעוֹלָם, שֶׁנֶּאֱמַר (אסתר ב) וַתֹּאמֶר אֶסְתֵּר לַמֶּלֶךְ בְּשֵׁם מָרְדֳּכָי:"],
["Pirkei_Avot:6:7:0",0,6,7,"פרק ו׳, משנה ז׳","גְּדוֹלָה תוֹרָה שֶׁהִיא נוֹתֶנֶת חַיִּים לְעֹשֶׂיהָ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁנֶּאֱמַר (משלי ד) כִּי חַיִּים הֵם לְמֹצְאֵיהֶם וּלְכָל בְּשָׂרוֹ מַרְפֵּא. וְאוֹמֵר (שם ג) רִפְאוּת תְּהִי לְשָׁרֶךָ וְשִׁקּוּי לְעַצְמוֹתֶיךָ. וְאוֹמֵר (שם ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ וְתֹמְכֶיהָ מְאֻשָּׁר. וְאוֹמֵר (שם א) כִּי לִוְיַת חֵן הֵם לְרֹאשֶׁךָ וַעֲנָקִים לְגַרְגְּרֹתֶיךָ. וְאוֹמֵר (שם ד) תִּתֵּן לְרֹאשְׁךָ לִוְיַת חֵן עֲטֶרֶת תִּפְאֶרֶת תְּמַגְּנֶךָּ. וְאוֹמֵר (שם ט) כִּי בִי יִרְבּוּ יָמֶיךָ וְיוֹסִיפוּ לְךָ שְׁנוֹת חַיִּים. וְאוֹמֵר (שם ג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאולָהּ עֹשֶׁר וְכָבוֹד."],
["Pirkei_Avot:6:7:622",0,6,7,"פרק ו׳, משנה ז׳","וְאוֹמֵר (שם) כִּי אֹרֶךְ יָמִים וּשְׁנוֹת חַיִּים וְשָׁלוֹם יוֹסִיפוּ לָךְ. וְאוֹמֵר (שם) דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם:"],
["Pirkei_Avot:6:8:0",0,6,8,"פרק ו׳, משנה ח׳","רַבִּי שִׁמְעוֹן בֶּן יְהוּדָה מִשּׁוּם רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי אוֹמֵר, הַנּוֹי וְהַכֹּחַ וְהָעֹשֶׁר וְהַכָּבוֹד וְהַחָכְמָה וְהַזִּקְנָה וְהַשֵּׂיבָה וְהַבָּנִים, נָאֶה לַצַּדִּיקִים וְנָאֶה לָעוֹלָם, שֶׁנֶּאֱמַר (שם טז) עֲטֶרֶת תִּפְאֶרֶת שֵׂיבָה בְּדֶרֶךְ צְדָקָה תִּמָּצֵא. וְאוֹמֵר (שם כ) תִּפְאֶרֶת בַּחוּרִים כֹּחָם וַהֲדַר זְקֵנִים שֵׂיבָה. וְאוֹמֵר (שם יד) עֲטֶרֶת חֲכָמִים עָשְׁרָם. וְאוֹמֵר (שם יז) עֲטֶרֶת זְקֵנִים בְּנֵי בָנִים וְתִפְאֶרֶת בָּנִים אֲבוֹתָם. וְאוֹמֵר (ישעיה כד) וְחָפְרָה הַלְּבָנָה וּבוֹשָׁה הַחַמָּה, כִּי מָלַךְ ה' צְבָאוֹת בְּהַר צִיּוֹן וּבִירוּשָׁלַיִם וְנֶגֶד זְקֵנָיו כָּבוֹד."],
["Pirkei_Avot:6:8:620",0,6,8,"פרק ו׳, משנה ח׳","רַבִּי שִׁמְעוֹן בֶּן מְנַסְיָא אוֹמֵר, אֵלּוּ שֶׁבַע מִדּוֹת שֶׁמָּנוּ חֲכָמִים לַצַּדִּיקִים, כֻּלָּם נִתְקַיְּמוּ בְרַבִּי וּבְבָנָיו:"],
["Pirkei_Avot:6:9:0",0,6,9,"פרק ו׳, משנה ט׳","אָמַר רַבִּי יוֹסֵי בֶן קִסְמָא, פַּעַם אַחַת הָיִיתִי מְהַלֵּךְ בַּדֶּרֶךְ וּפָגַע בִּי אָדָם אֶחָד, וְנָתַן לִי שָׁלוֹם, וְהֶחֱזַרְתִּי לוֹ שָׁלוֹם. אָמַר לִי, רַבִּי, מֵאֵיזֶה מָקוֹם אַתָּה. אָמַרְתִּי לוֹ, מֵעִיר גְּדוֹלָה שֶׁל חֲכָמִים וְשֶׁל סוֹפְרִים אָנִי. אָמַר לִי, רַבִּי, רְצוֹנְךָ שֶׁתָּדוּר עִמָּנוּ בִמְקוֹמֵנוּ, וַאֲנִי אֶתֵּן לְךָ אֶלֶף אֲלָפִים דִּינְרֵי זָהָב וַאֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת. אָמַרְתִּי לוֹ, בְּנִי, אִם אַתָּה נוֹתֵן לִי כָל כֶּסֶף וְזָהָב וַאֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת שֶׁבָּעוֹלָם, אֵינִי דָר אֶלָּא בִמְקוֹם תּוֹרָה."],
["Pirkei_Avot:6:9:567",0,6,9,"פרק ו׳, משנה ט׳","וְלֹא עוֹד, אֶלָּא שֶׁבִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם אֵין מְלַוִּין לוֹ לָאָדָם לֹא כֶסֶף וְלֹא זָהָב וְלֹא אֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת, אֶלָּא תוֹרָה וּמַעֲשִׂים טוֹבִים בִּלְבַד, שֶׁנֶּאֱמַר (משלי ו) בְּהִתְהַלֶּכְךָ תַּנְחֶה אֹתָךְ, בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ, וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. בְּהִתְהַלֶּכְךָ תַּנְחֶה אֹתָךְ, בָּעוֹלָם הַזֶּה, בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ, בַּקֶּבֶר, וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ, לָעוֹלָם הַבָּא. וְכֵן כָּתוּב בְּסֵפֶר תְּהִלִּים עַל יְדֵי דָוִד מֶלֶךְ יִשְׂרָאֵל (תהלים קיט), טוֹב לִי תוֹרַת פִּיךָ מֵאַלְפֵי זָהָב וָכָסֶף. וְאוֹמֵר (חגי ב) לִי הַכֶּסֶף וְלִי הַזָּהָב אָמַר ה' צְבָאוֹת:"],
["Pirkei_Avot:6:10:0",0,6,10,"פרק ו׳, משנה י׳","חֲמִשָּׁה קִנְיָנִים קָנָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְעוֹלָמוֹ, וְאֵלּוּ הֵן, תּוֹרָה קִנְיָן אֶחָד, שָׁמַיִם וָאָרֶץ קִנְיָן אֶחָד, אַבְרָהָם קִנְיָן אֶחָד, יִשְׂרָאֵל קִנְיָן אֶחָד, בֵּית הַמִּקְדָּשׁ קִנְיָן אֶחָד. תּוֹרָה מִנַּיִן, דִּכְתִיב (משלי ח), ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ קֶדֶם מִפְעָלָיו מֵאָז. שָׁמַיִם וָאָרֶץ קִנְיָן אֶחָד מִנַּיִן, דִּכְתִיב (ישעיה סו), כֹּה אָמַר ה' הַשָּׁמַיִם כִּסְאִי וְהָאָרֶץ הֲדֹם רַגְלָי אֵי זֶה בַיִת אֲשֶׁר תִּבְנוּ לִי וְאֵי זֶה מָקוֹם מְנוּחָתִי, וְאוֹמֵר (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךָ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךָ."],
["Pirkei_Avot:6:10:600",0,6,10,"פרק ו׳, משנה י׳","אַבְרָהָם קִנְיָן אֶחָד מִנַּיִן, דִּכְתִיב (בראשית יד), וַיְבָרְכֵהוּ וַיֹּאמַר בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קֹנֵה שָׁמַיִם וָאָרֶץ. יִשְׂרָאֵל קִנְיָן אֶחָד מִנַּיִן, דִּכְתִיב (שמות טו), עַד יַעֲבֹר עַמְּךָ ה' עַד יַעֲבֹר עַם זוּ קָנִיתָ, וְאוֹמֵר (תהלים טז) לִקְדוֹשִׁים אֲשֶׁר בָּאָרֶץ הֵמָּה וְאַדִּירֵי כָּל חֶפְצִי בָם. בֵּית הַמִּקְדָּשׁ קִנְיָן אֶחָד מִנַּיִן, דִּכְתִיב (שמות טו), מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ ה' מִקְּדָשׁ ה' כּוֹנְנוּ יָדֶיךָ. וְאוֹמֵר (תהלים עח) וַיְבִיאֵם אֶל גְּבוּל קָדְשׁוֹ הַר זֶה קָנְתָה יְמִינוֹ:"],
["Pirkei_Avot:6:11:0",0,6,11,"פרק ו׳, משנה י״א","כָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ, לֹא בְרָאוֹ אֶלָּא לִכְבוֹדוֹ, שֶׁנֶּאֱמַר (ישעיה מג), כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַרְתִּיו אַף עֲשִׂיתִיו, וְאוֹמֵר (שמות טו), יְהֹוָה יִמְלֹךְ לְעֹלָם וָעֶד. רַבִּי חֲנַנְיָא בֶּן עֲקַשְׁיָא אוֹמֵר, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְזַכּוֹת אֶת יִשְׂרָאֵל, לְפִיכָךְ הִרְבָּה לָהֶם תּוֹרָה וּמִצְוֹת, שֶׁנֶּאֱמַר (ישעיה מב) ה' חָפֵץ לְמַעַן צִדְקוֹ יַגְדִּיל תּוֹרָה וְיַאְדִּיר:"],
["Avot_DeRabbi_Natan:11:1:0",1,11,1,"פרק י״א, הלכה א׳","שמעיה ואבטליון קבלו מהם שמעיה אומר אהוב את המלאכה ושנא את הרבנות ואל תתוודע לרשות."],
["Avot_DeRabbi_Natan:12:5:755",1,12,5,"פרק י״ב, הלכה ה׳","לא נשמתו של משה בלבד גנוזה תחת כסא הכבוד אלא נשמתן של צדיקים גנוזות תחת כסא הכבוד שנאמר והיתה נפש אדוני צרורה בצרור החיים."],
["Avot_DeRabbi_Natan:13:1:0",1,13,1,"פרק י״ג, הלכה א׳","שמאי אומר עשה תורתך קבע אמור מעט ועשה הרבה והוי מקבל את כל האדם בסבר פנים יפות:"],
["Avot_DeRabbi_Natan:15:1:109",1,15,1,"פרק ט״ו, הלכה א׳","יהי כבוד חבירך חביב עליך כשלך כיצד מלמד שכשם שרואה את כבודו כך יהא אדם רואה את כבוד חבירו וכשם שאין אדם רוצה שיהא שם רע על כבודו כך יהא אדם רוצה שלא להוציא שם רע על כבודו של חברו."],
["Avot_DeRabbi_Natan:16:1:0",1,16,1,"פרק ט״ז, הלכה א׳","רבי יהושע אומר עין הרע ויצר הרע ושנאת הבריות מוציאין את האדם מן העולם. עין הרע כיצד מלמד שכשם שאדם רואה את ביתו של עצמו כך יהא רואה ביתו של חבירו."],
["Avot_DeRabbi_Natan:16:4:402",1,16,4,"פרק ט״ז, הלכה ד׳","ר׳ שמעון בן אלעזר אומר בשעה של גדולה נאמר דבר זה ואהבת לרעך כמוך אני ה' בראתיו אם אתה אוהבו אני נאמן לשלם לך שכר טוב ואם לאו אני דיין לפרוע:"],
["Avot_DeRabbi_Natan:22:1:825",1,22,1,"פרק כ״ב, הלכה א׳","רבן גמליאל אומר עשה לך רב וקנה לך חבר. רב לחכמה וחבר ללמוד והסתלק מן הספיקות ואל תרבה לעשר אומדות:"],
["Avot_DeRabbi_Natan:22:2:0",1,22,2,"פרק כ״ב, הלכה ב׳","שמעון בנו אומר כל ימי גדלתי בין החכמים ולא מצאתי לגוף טוב משתיקה."],
["Avot_DeRabbi_Natan:23:3:0",1,23,3,"פרק כ״ג, הלכה ג׳","ר׳ אליעזר בן יעקב אומר הלומד תורה בילדותו דומה לכתב שנכתב על נייר חדש והלומד תורה בזקנותו דומה לכתב שנכתב על נייר ישן:"],
["Avot_DeRabbi_Natan:24:1:0",1,24,1,"פרק כ״ד, הלכה א׳","אלישע בן אבויה אומר אדם שיש בו מעשים טובים ולמד תורה הרבה למה הוא דומה לאדם שבונה אבנים מלמטה ואחר כך לבנים אפילו באים מים הרבה ועומדין בצידן אין מחין אותן ממקומן:"],
["Avot_DeRabbi_Natan:25:4:0",1,25,4,"פרק כ״ה, הלכה ד׳","בן עזאי אומר הוי רץ למצוה קלה. הוא היה אומר אם עשית מצוה אחת ואין אתה דואג ממנה מאותה מצוה סוף שהיא גוררת מצות הרבה."],
["Avot_DeRabbi_Natan:26:1:0",1,26,1,"פרק כ״ו, הלכה א׳","רבי עקיבא אומר סייג לכבוד שחוק. סייג לחכמה שתיקה. סייג לנדרים פרישות."],
["Avot_DeRabbi_Natan:27:4:0",1,27,4,"פרק כ״ז, הלכה ד׳","ר״א בן שמוע אומר יהי כבוד תלמידך חביב עליך כשלך וכבוד חבירך כמורא רבך ומורא רבך כמורא שמים."],
["Avot_DeRabbi_Natan:28:1:0",1,28,1,"פרק כ״ח, הלכה א׳","רבי נתן אומר אין לך אהבה כאהבה של תורה. ואין לך חכמה כחכמה של דרך ארץ ואין לך יופי כיופי של ירושלים."],
["Avot_DeRabbi_Natan:28:3:0",1,28,3,"פרק כ״ח, הלכה ג׳","רשב״ג אומר כל המשים שלום בתוך ביתו מעלה עליו הכתוב כאילו משים שלום בישראל על כל אחד ואחד."],
["Avot_DeRabbi_Natan:29:3:676",1,29,3,"פרק כ״ט, הלכה ג׳","רבי חנניא בן יעקב אומר הניעור בלילה מתוך דברי תורה סימן יפה לו."],
["Avot_DeRabbi_Natan:29:7:205",1,29,7,"פרק כ״ט, הלכה ז׳","כל שיש בידו הלכות ואין בידו מדרש חלש וזיין בידו. יש בידו זה וזה גבור ומזויין. הוא היה אומר הוי זהיר בשאילת שלום בין אדם לחבירו ואל תבוא לבין המחלוקת ואל תשתדל לראותו."],
["Avot_DeRabbi_Natan:30:1:0",1,30,1,"פרק ל׳, הלכה א׳","רבי נתן בן יוסף אומר כל המבטל דברי תורה מעושר סופו לבטלה מעוני וכל המקיים ד״ת מעוני סופה לקיימה מעושר. הוא היה אומר תנחומי אבלים וביקור חולים וגמ״ח מביאין טובה לעולם:"],
["Avot_DeRabbi_Natan:41:10:0",1,41,10,"פרק מ״א, הלכה י׳","רבי יהודה בן תימא אומר הוי עז כנמר וקל כנשר ורץ כצבי וגבור כארי לעשות רצון אביך שבשמים:"],
["Tractate_Derekh_Eretz_Zuta:1:1:0",2,1,1,"פרק א׳, הלכה א׳","דרכן של תלמידי חכמים עניו ושפל רוח זריז ממולא עלוב ואהוב לכל אדם."],
["Tractate_Derekh_Eretz_Zuta:2:1:0",2,2,1,"פרק ב׳, הלכה א׳","כל דרכיך יהיו לשם שמים. הוי אוהב את השמים וירא מן השמים. הוי חרד ושש על כל המצות."],
["Tractate_Derekh_Eretz_Zuta:2:5:0",2,2,5,"פרק ב׳, הלכה ה׳","הוי אוהב את התורה ומכבד את התורה. אוהב את הצדקות ואת התוכחות ואת המישרים. ואל תרדוף אחר כבוד."],
["Tractate_Derekh_Eretz_Zuta:2:8:0",2,2,8,"פרק ב׳, הלכה ח׳","יהי כבוד חבירך חביב עליך כשלך. הוי מיקר את כל האדם. אל תאמר אחנוף לזה שיאכילני ולזה שישקני ולזה שילבישני ולזה שיכסני מוטב שתתבייש מעצמך ואל תתבייש מאחרים."],
["Tractate_Derekh_Eretz_Zuta:3:2:0",2,3,2,"פרק ג׳, הלכה ב׳","הוי דן את חבירך לכף זכות. ואל תכריעהו לכף חובה. הוי שש בחלקך."],
["Tractate_Derekh_Eretz_Zuta:3:8:77",2,3,8,"פרק ג׳, הלכה ח׳","הוי מחשב להשבה ולהפסיק את החשבון. קנה שם טוב קנה לעצמו. קנה לו דברי תורה קנה לו חיי העוה״ב."],
["Tractate_Derekh_Eretz_Zuta:3:11:106",2,3,11,"פרק ג׳, הלכה י״א","היה כאסקופה התחתונה שרוב בני אדם דורסין אותה לסוף כל הבנין כולה נסתר והיא במקומה עומדת:"],
["Tractate_Derekh_Eretz_Zuta:4:3:0",2,4,3,"פרק ד׳, הלכה ג׳","עשה תורתך בחנם ולא תטול עליה שכר שהמקום נתנה בחנם. ואין נוטלין שכר על דברי תורה. ואם אתה נוטל שכר על דברי תורה נמצאת מחריב את כל העולם כולו:"],
["Tractate_Derekh_Eretz_Zuta:5:4:30",2,5,4,"פרק ה׳, הלכה ד׳","הדר ענוה יראה. הדר יראה מצוה. הדר מצוה צניעות."],
["Tractate_Derekh_Eretz_Zuta:5:5:0",2,5,5,"פרק ה׳, הלכה ה׳","לא יהא אדם ער בין הישינים ולא ישן בין העירים. ולא בוכה בין השוחקים ולא שוחק בין הבוכים."],
["Tractate_Derekh_Eretz_Zuta:8:1:0",2,8,1,"פרק ח׳, הלכה א׳","הוי רך כקנה שהרוח נושבת בו לכל רוח שתרצה שאין התורה מתקיימת אלא במי שרוחו נמוכה עליו למה נמשלה תורה למים לומר לך מה דרכו של מים אינן הולכין למקום גבוה אלא למקום נמוך כך אין התורה מתקיימת אלא במי שרוחו נמוכה עליו:"],
["Tractate_Derekh_Eretz_Zuta:8:6:0",2,8,6,"פרק ח׳, הלכה ו׳","כל זמן שאדם חוטא מורא הבריות עליו וכל זמן שאינו חוטא מוראו על הבריות."],
["Tractate_Derekh_Eretz_Zuta:9:3:0",2,9,3,"פרק ט׳, הלכה ג׳","הוי אוהב את בית הכנסת כדי שתטול שכרך בכל יום."],
["Tractate_Derekh_Eretz_Zuta:9:5:0",2,9,5,"פרק ט׳, הלכה ה׳","הוי אוהב את העניים כדי שלא יבואו בניך לידי אותה מדה:"],
["Tractate_Derekh_Eretz_Zuta:10:8:26",2,10,8,"פרק י׳, הלכה ח׳","שנה ולא קרא עם הארץ. קרא ושנה ולא פירש חכם. קרא ושנה ופירש נבון."],
["Tractate_Derekh_Eretz_Zuta:11:10:0",2,11,10,"פרק השלום, הלכה י׳","א״ר יהושע גדול הוא השלום שברית כהנים כרותה בשלום."],
["Tractate_Derekh_Eretz_Zuta:11:11:274",2,11,11,"פרק השלום, הלכה י״א","מי שהוא אוהב שלום ורודף שלום ומקדים שלום ומשיב שלום ומטיל שלום בין ישראל לאביהם שבשמים על אחת כמה וכמה."],
["Tractate_Derekh_Eretz_Zuta:11:17:0",2,11,17,"פרק השלום, הלכה י״ז","רשב״ג אומר גדול הוא השלום שמצינו שדברו השבטים דברי בדאות כדי להטיל שלום בין יוסף לאחיו."],
["Tractate_Derekh_Eretz_Zuta:11:19:0",2,11,19,"פרק השלום, הלכה י״ט","ר׳ יהושע דסכנין בשם רבי לוי אמר גדול השלום שכל הברכות והתפלות חותמין בשלום."],
["Tractate_Derekh_Eretz_Rabbah:7:7:0",3,7,7,"פרק ז׳, הלכה ז׳","לא ישמח אדם בין הבוכים ולא יבכה בין השמחים. ולא יהא ער בין הישינים ולא ישן בין הערים."],
["Tractate_Derekh_Eretz_Rabbah:11:17:388",3,11,17,"פרק י״א, הלכה י״ז","יהי רצון מלפני הקדוש ברוך הוא שיראנו בשמחתה של ירושלים ונחמותיה אמן:"],
["Ein_Yaakov:2:13:990",4,2,13,"ברכות · פרק ב׳, פסקה י״ג","כָּל הַמִּתְפַּלֵּל וְיוֹצֵא לַדֶּרֶךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לוֹ חֲפָצָיו, שֶׁנֶּאֱמַר: \"צֶדֶק לְפָנָיו יְהַלֵּךְ, וְיָשֵׂם לְדֶרֶךְ פְּעָמָיו\"."],
["Ein_Yaakov:2:14:364",4,2,14,"ברכות · פרק ב׳, פסקה י״ד","כָּל הַמַּשְׂבִּיעַ עַצְמוֹ מִדִּבְרֵי תּוֹרָה וְלָן, אֵין מְבַשְּׂרִין אוֹתוֹ בְּשׂוֹרוֹת רָעוֹת, שֶׁנֶּאֱמַר: \"וְשָׂבֵעַ יָלִין, בַּל יִפָּקֶד רָע\"."],
["Ein_Yaakov:2:15:522",4,2,15,"ברכות · פרק ב׳, פסקה ט״ו","יְהִי רָצוֹן מִלְּפָנֶיךָ, ה' אֱלֹהֵינוּ, שֶׁתָּצִיץ בְּבָשְׁתֵּנוּ, וְתַבִּיט בְּרָעָתֵנוּ, וְתִתְלַבֵּשׁ בְּרַחֲמֶיךָ, וְתִתְכַּסֶּה בְּעֻזֶּךָ, וְתִתְעַטֵּף בַּחֲסִידוּתֶךָ, וְתִתְאַזֵּר בַּחֲנִינוּתֶיךָ, וְתָבוֹא לְפָנֶיךָ מִדַּת טוּבְךָ וְעַנְוְתָנוּתֶךָ."],
["Ein_Yaakov:2:16:499",4,2,16,"ברכות · פרק ב׳, פסקה ט״ז","יְהִי רָצוֹן מִלְּפָנֶיךָ, ה' אֱלֹהֵינוּ, שֶׁתָּשִׂים שָׁלוֹם בְּפָמַלְיָא שֶׁל מַעְלָה וּבְפָמַלְיָא שֶׁל מַטָּה, וּבֵין הַתַּלְמִידִים הָעוֹסְקִים בְּתוֹרָתֶךָ, בֵּין עוֹסְקִים לִשְׁמָהּ, בֵּין עוֹסְקִים שֶׁלֹּא לִשְׁמָהּ, וְכָל הָעוֹסְקִים שֶׁלֹּא לִשְׁמָהּ, יְהִי רָצוֹן מִלְּפָנֶיךָ שֶׁיִּהְיוּ עוֹסְקִים לִשְׁמָהּ."],
["Ein_Yaakov:2:17:58",4,2,17,"ברכות · פרק ב׳, פסקה י״ז","יְהִי רָצוֹן מִלְּפָנֶיךָ, ה' אֱלֹהֵינוּ, שֶׁתַּעֲמִידֵנוּ בְּקֶרֶן אוֹרָה, וְאַל תַּעֲמִידֵנוּ בְּקֶרֶן חֲשֵׁכָה, וְאַל יִדְוֶה לִבֵּנוּ, וְאַל יֶחְשְׁכוּ עֵינֵינוּ."],
["Ein_Yaakov:2:22:2634",4,2,22,"ברכות · פרק ב׳, פסקה כ״ב","עוֹלָמְךָ תִּרְאֶה בְּחַיֶּיךָ, וְאַחֲרִיתְךָ לְחַיֵּי הָעוֹלָם הַבָּא, וְתִקְוָתְךָ לְדוֹר דּוֹרִים, לִבְּךָ יֶהְגֶּה תְּבוּנָה, פִּיךָ יְדַבֵּר חָכְמוֹת, וּלְשׁוֹנְךָ יַרְחִישׁ רְנָנוֹת, עַפְעַפֶּיךָ יַיְשִׁירוּ נֶגְדֶּךָ, עֵינֶיךָ יָאִירוּ בִּמְאוֹר תּוֹרָה, וּפָנֶיךָ יַזְהִירוּ כְּזֹהַר הָרָקִיעַ, שִׂפְתוֹתֶיךָ יַבִּיעוּ דַּעַת וְכִלְיוֹתֶיךָ תַּעֲלֹזְנָה מֵישָׁרִים, וּפְעָמֶיךָ יָרוּצוּ לִשְׁמֹעַ דִּבְרֵי עַתִּיק יוֹמִין."],
["Ein_Yaakov:4:4:146",4,4,4,"ברכות · פרק ד׳, פסקה ד׳","כָּל תַּלְמִיד חָכָם שֶׁאֵין תּוֹכוֹ כְּבָרוֹ אַל יִכָּנֵס לְבֵית הַמִּדְרָשׁ."],
["Ein_Yaakov:4:10:925",4,4,10,"ברכות · פרק ד׳, פסקה י׳","אַל תַּאֲמֵן בְּעַצְמְךָ עַד יוֹם מוֹתְךָ, שֶׁהֲרֵי יוֹחָנָן כֹּהֵן גָּדוֹל שִׁמֵּשׁ בִּכְהֻנָּה גְּדוֹלָה שְׁמוֹנִים שָׁנָה וְלִבְסוֹף נַעֲשָׂה צְדוֹקִי."],
["Ein_Yaakov:5:1:1624",4,5,1,"ברכות · פרק ה׳, פסקה א׳","אֵין עוֹמְדִין לְהִתְפַּלֵּל, לֹא מִתּוֹךְ עַצְבוּת, וְלֹא מִתּוֹךְ עַצְלוּת, וְלֹא מִתּוֹךְ שְׂחוֹק, וְלֹא מִתּוֹךְ שִׂיחָה, וְלֹא מִתּוֹךְ קַלּוּת רֹאשׁ, וְלֹא מִתּוֹךְ דְּבָרִים בְּטֵלִים, אֶלָּא מִתּוֹךְ שִׂמְחָה שֶׁל מִצְוָה."],
["Ein_Yaakov:5:11:30",4,5,11,"ברכות · פרק ה׳, פסקה י״א","לְעוֹלָם יְסַדֵּר אָדָם שִׁבְחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאַחַר כָּךְ יִתְפַּלֵּל."],
["Ein_Yaakov:5:12:1942",4,5,12,"ברכות · פרק ה׳, פסקה י״ב","אַרְבַּע צְרִיכִין חִזּוּק. וְאֵלּוּ הֵן: תּוֹרָה, וּמַעֲשִׂים טוֹבִים, תְּפִלָּה, וְדֶרֶךְ אֶרֶץ."],
["Ein_Yaakov:5:17:558",4,5,17,"ברכות · פרק ה׳, פסקה י״ז","כָּל אָדָם שֶׁיֵּשׁ בּוֹ דֵּעָה, כְּאִלּוּ נִבְנָה בֵּית־הַמִּקְדָּשׁ בְּיָמָיו. 'דֵּעָה' נִתְּנָה בֵּין שְׁתֵּי אוֹתִיּוֹת."],
["Ein_Yaakov:5:30:309",4,5,30,"ברכות · פרק ה׳, פסקה ל׳","כָּל הַמְבַקֵּשׁ רַחֲמִים עַל חֲבֵרוֹ, אֵינוֹ צָרִיךְ לְהַזְכִּיר שְׁמוֹ."],
["Ein_Yaakov:7:2:818",4,7,2,"ברכות · פרק ז׳, פסקה ב׳","יְהִי רָצוֹן, שֶׁלֹּא יֵבוֹשׁ בַּעַל הַבַּיִת בָּעוֹלָם הַזֶּה, וְלֹא יִכָּלֵם לָעוֹלָם הַבָּא."],
["Ein_Yaakov:7:14:114",4,7,14,"ברכות · פרק ז׳, פסקה י״ד","אָמַר שְׁמוּאֵל: לְעוֹלָם אַל יוֹצִיא אָדָם אֶת עַצְמוֹ מִן הַכְּלָל."],
["Ein_Yaakov:9:11:311",4,9,11,"ברכות · פרק ט׳, פסקה י״א","רִבּוֹנוֹ שֶׁל עוֹלָם, אֲנִי שֶׁלְּךָ וַחֲלוֹמוֹתַי שֶׁלְּךָ, חֲלוֹם חָלַמְתִּי וְאֵינִי יוֹדֵעַ מָה הוּא."],
["Ein_Yaakov:9:27:0",4,9,27,"ברכות · פרק ט׳, פסקה כ״ז","אָמַר רַבִּי יְהוֹשֻׁעַ בֶּן לֵוִי: הָרוֹאֶה רָקִיעַ בְּטָהֳרָתָהּ, אוֹמֵר: \"בָּרוּךְ עוֹשֶׂה בְּרֵאשִׁית\"."],
["Ein_Yaakov:9:54:937",4,9,54,"ברכות · פרק ט׳, פסקה נ״ד","דרש בר קפרא איזו היא פרשה קטנה שכל גופי תורה תלויין בה בכל דרכיך דעהו והוא יישר אורחותיך."],
["Ein_Yaakov:9:56:1119",4,9,56,"ברכות · פרק ט׳, פסקה נ״ו","תנו רבנן הרואה מלכי ישראל אומר ברוך שחלק מכבודו ליראיו. חכמי ישראל אומר ברוך שחלק מחכמתו ליראיו."],
["Ein_Yaakov:9:70:524",4,9,70,"ברכות · פרק ט׳, פסקה ע׳","אמר ר' אבין הלוי כל הנהנה מסעודה שתלמיד חכם שרוי בתוכה כאלו נהנה מזיו שכינה שנאמר ויבא אהרן וכל זקני ישראל לאכל לחם עם חותן משה לפני האלהים."],
["Ein_Yaakov:10:7:709",4,10,7,"שבת · פרק א׳, פסקה ז׳","לְעוֹלָם אַל יְשַׁנֶּה אָדָם בְּנוֹ בֵּין הַבָּנִים, שֶׁבִּשְׁבִיל מִשְׁקַל שְׁנֵי סְלָעִים מֵילָת, שֶׁנָּתַן יַעֲקֹב לְיוֹסֵף יוֹתֵר מִשְּׁאָר בָּנָיו, נִתְקַנְּאוּ בּוֹ אֶחָיו, וְנִתְגַּלְגֵּל הַדָּבָר, וְיָרְדוּ אֲבוֹתֵינוּ לְמִצְרַיִם."],
["Ein_Yaakov:11:22:900",4,11,22,"שבת · פרק ב׳, פסקה כ״ב","יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהֵינוּ, שֶׁתַּצִּילֵנִי הַיּוֹם מֵעַזֵּי פָנִים וּמֵעַזּוּת פָּנִים."],
["Ein_Yaakov:11:24:20",4,11,24,"שבת · פרק ב׳, פסקה כ״ד","לְעוֹלָם יְהֵא אָדָם עַנְוְתָן כְּהִלֵּל, וְאַל יְהֵא קַפְּדָן כְּשַׁמַּאי."],
["Ein_Yaakov:18:2:469",4,18,2,"שבת · פרק ט׳, פסקה ב׳","לְעוֹלָם אַל יִמְנַע אָדָם אֶת עַצְמוֹ מִבֵּית הַמִּדְרָשׁ, וַאֲפִלּוּ שָׁעָה אַחַת, שֶׁהֲרֵי כַּמָּה שָׁנִים נִשְׁנֵית מִשְׁנָה זוֹ בְּבֵית הַמִּדְרָשׁ, וְלֹא נִתְגַּלָּה טַעְמָהּ, עַד שֶׁבָּא רַבִּי חֲנִינָא בֶּן עֲקַבְיָא וּפֵרְשָׁהּ."],
["Ein_Yaakov:25:17:721",4,25,17,"שבת · פרק ט״ז, פסקה י״ז","שְׁנֵי מַלְאֲכֵי הַשָּׁרֵת מְלַוִּין לוֹ לָאָדָם בְּעֶרֶב שַׁבָּת מִבֵּית הַכְּנֶסֶת לְבֵיתוֹ, אֶחָד טוֹב, וְאֶחָד רָע."],
["Ein_Yaakov:25:19:24",4,25,19,"שבת · פרק ט״ז, פסקה י״ט","לְעוֹלָם יְסַדֵּר אָדָם שֻׁלְחָנוֹ בְּעֶרֶב שַׁבָּת, אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ אֶלָּא לְכַזַּיִת."],
["Ein_Yaakov:32:13:147",4,32,13,"שבת · פרק כ״ג, פסקה י״ג","נִשְׁמָתָן שֶׁל צַדִּיקִים גְּנוּזוֹת תַּחַת כִּסֵּא הַכָּבוֹד, שֶׁנֶּאֱמַר: \"וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים\"."],
["Ein_Yaakov:38:5:2256",4,38,5,"עירובין · פרק ה׳, פסקה ה׳","אַשְׁרֵיכֶם יִשְׂרָאֵל, שֶׁכֻּלְּכֶם חֲכָמִים אַתֶּם, מִגְּדוֹלְכֶם וְעַד קְטַנְּכֶם."],
["Ein_Yaakov:39:5:380",4,39,5,"עירובין · פרק ו׳, פסקה ה׳","כָּל הָאוֹמֵר: שְׁמוּעָה זוֹ נָאָה וּשְׁמוּעָה זוֹ אֵינָה נָאָה, מְאַבֵּד הוֹנָהּ שֶׁל תּוֹרָה."],
["Ein_Yaakov:47:8:272",4,47,8,"פסחים · פרק ד׳, פסקה ח׳","לְעוֹלָם יַעֲסֹק אָדָם בְּתוֹרָה וּבְמִצְווֹת, אַף עַל פִּי שֶׁלֹּא לִשְׁמָהּ, שֶׁמִתּוֹךְ שֶׁלֹּא לִשְׁמָהּ, בָּא לִשְׁמָהּ."],
["Ein_Yaakov:49:2:34",4,49,2,"פסחים · פרק ו׳, פסקה ב׳","כָּל הַמִּתְיַהֵר, אִם חָכָם הוּא, חָכְמָתוֹ מִסְתַּלֶּקֶת מִמֶּנּוּ, וְאִם נָבִיא הוּא, נְבוּאָתוֹ מִסְתַּלֶּקֶת מִמֶּנּוּ."],
["Ein_Yaakov:49:4:36",4,49,4,"פסחים · פרק ו׳, פסקה ד׳","אֵין לָאָדָם בְּיוֹם־טוֹב, אֶלָּא אוֹ אוֹכֵל וְשׁוֹתֶה, אוֹ יוֹשֵׁב וְשׁוֹנֶה. רַבִּי יְהוֹשֻׁעַ אוֹמֵר: חַלְּקֵהוּ, חֶצְיוֹ לַאֲכִילָה וּשְׁתִיָּה, וְחֶצְיוֹ לְבֵית הַמִּדְרָשׁ."],
["Ein_Yaakov:54:5:994",4,54,5,"יומא · פרק א׳, פסקה ה׳","לִמְּדָה תּוֹרָה דֶרֶךְ אֶרֶץ, שֶׁלֹּא יֹאמַר אָדָם דָּבָר לַחֲבֵרוֹ, אֶלָּא אִם כֵּן קוֹרְאֵהוּ."],
["Ein_Yaakov:56:11:1382",4,56,11,"יומא · פרק ג׳, פסקה י״א","רִבּוֹנוֹ שֶׁל עוֹלָם, בְּשָׁעָה שֶׁחוֹטְאִין יִשְׂרָאֵל, וְעוֹשִׂין תְּשׁוּבָה, עֲשֵׂה לָהֶם זְדוֹנוֹת כִּשְׁגָגוֹת."],
["Ein_Yaakov:56:22:1446",4,56,22,"יומא · פרק ג׳, פסקה כ״ב","וְאָמַר רַבִּי חִיָּא בַּר אַבָּא, אָמַר רַבִּי יוֹחָנָן: כֵּיוָן שֶׁיָּצְאוּ רֹב שְׁנוֹתָיו שֶׁל אָדָם וְלֹא חָטָא, שׁוּב אֵינוֹ חוֹטֵא, שֶׁנֶּאֱמַר: \"רַגְלֵי חֲסִידָיו יִשְׁמֹר\"."],
["Ein_Yaakov:61:24:2507",4,61,24,"יומא · פרק ח׳, פסקה כ״ד","אַשְׁרֵי פְּלוֹנִי, שֶׁלָּמַד תּוֹרָה, אַשְׁרֵי אָבִיו, שֶׁלִּמְּדוֹ תּוֹרָה, אַשְׁרֵי רַבּוֹ, שֶׁלִּמְּדוֹ תּוֹרָה. אוֹי לָהֶם לִבְנֵי אָדָם, שֶׁלֹּא לָמְדוּ תּוֹרָה, רְאִיתֶם פְּלוֹנִי שֶׁלָּמַד תּוֹרָה, כַּמָּה יָפִים דְּרָכָיו, כַּמָּה מְתֻקָּנִים מַעֲשָׂיו."],
["Ein_Yaakov:65:16:419",4,65,16,"סוכה · פרק ד׳, פסקה ט״ז","אֵין הַצְּדָקָה מִשְׁתַּלֶּמֶת, אֶלָּא לְפִי גְּמִילוּת חֲסָדִים שֶׁבָּהּ, שֶׁנֶּאֱמַר: \"זִרְעוּ לָכֶם לִצְדָקָה, קִצְרוּ לְפִי חֶסֶד\"."],
["Ein_Yaakov:65:17:1217",4,65,17,"סוכה · פרק ד׳, פסקה י״ז","תּוֹרָה לְלַמְּדָהּ, זוֹ הִיא תּוֹרָה שֶׁל חֶסֶד, שֶׁלֹּא לְלַמְּדָהּ, זוֹ הִיא תּוֹרָה שֶׁאֵינָהּ שֶׁל חֶסֶד."],
["Ein_Yaakov:66:20:163",4,66,20,"סוכה · פרק ה׳, פסקה כ׳","אַשְׁרֵי זִקְנָתֵנוּ שֶׁכִּפְּרָה עַל יַלְדּוּתֵנוּ, אֵלּוּ בַּעֲלֵי תְּשׁוּבָה."],
["Ein_Yaakov:71:1:1006",4,71,1,"ביצה · פרק ב׳, פסקה א׳","אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל: בָּנַי, לְווּ עָלַי וְקַדְּשׁוּ קְדֻשַּׁת הַיּוֹם, וְהַאֲמִינוּ בִּי, וַאֲנִי פּוֹרֵעַ."],
["Ein_Yaakov:71:4:58",4,71,4,"ביצה · פרק ב׳, פסקה ד׳","כָּל מְזוֹנוֹתָיו שֶׁל אָדָם קְצוּבִין לוֹ מֵרֹאשׁ הַשָּׁנָה וְעַד יוֹם הַכִּפּוּרִים, חוּץ מֵהוֹצָאַת שַׁבָּתוֹת, וְהוֹצָאַת יָמִים טוֹבִים, וְהוֹצָאַת בָּנָיו לְתַלְמוּד תּוֹרָה, שֶׁאִם פּוֹחֵת, פּוֹחֲתִין לוֹ, וְאִם הוֹסִיף, מוֹסִיפִין לוֹ."],
["Ein_Yaakov:75:11:1042",4,75,11,"ראש השנה · פרק א׳, פסקה י״א","אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: תִּקְעוּ לְפָנַי בְּשׁוֹפָר שֶׁל אַיִל, כְּדֵי שֶׁאֶזְכֹּר לָכֶם עֲקֵדַת יִצְחָק בֶּן אַבְרָהָם, וּמַעֲלֶה אֲנִי עֲלֵיכֶם כְּאִלּוּ עֲקַדְתֶּם עַצְמְכֶם לְפָנַי."],
["Ein_Yaakov:75:18:201",4,75,18,"ראש השנה · פרק א׳, פסקה י״ח","כָּל הַמַּעֲבִיר עַל מִדּוֹתָיו מַעֲבִירִין לוֹ עַל כָּל פְּשָׁעָיו, שֶׁנֶּאֱמַר: \"נֹשֵׂא עָוֹן וְעֹבֵר עַל פֶּשַׁע\"."],
["Ein_Yaakov:75:19:75",4,75,19,"ראש השנה · פרק א׳, פסקה י״ט","אִלְמָלֵא מִקְרָא כָּתוּב, אִי־אֶפְשָׁר לְאָמְרוֹ, מְלַמֵּד שֶׁנִּתְעַטֵּף הַקָּדוֹשׁ בָּרוּךְ הוּא כִּשְׁלִיחַ־צִבּוּר, וְהֶרְאָה לוֹ לְמֹשֶׁה סֵדֶר תְּפִלָּה."],
["Ein_Yaakov:76:3:1080",4,76,3,"ראש השנה · פרק ב׳, פסקה ג׳","וְאָמַר רַבִּי יוֹחָנָן: כָּל הַלּוֹמֵד תּוֹרָה וְאֵינוֹ מְלַמְּדָהּ, דּוֹמֶה לַהֲדַס בַּמִּדְבָּר."],
["Ein_Yaakov:80:21:380",4,80,21,"מגילה · פרק א׳, פסקה כ״א","כשם שבקטנותו הקטין עצמו אצל מי שגדול ממנו בתורה, כך במלכותו הקטין עצמו אצל מי שגדול ממנו בחכמה:"],
["Ein_Yaakov:80:37:1314",4,80,37,"מגילה · פרק א׳, פסקה ל״ז","מנהגו של עולם אדם צר צורה בכותל ואין יכול להטיל בה רוח ונשמה קרביים ובני מעיים. אבל הקדוש ברוך הוא צר צורה בתוך צורה ומטיל בה רוח ונשמה קרביים ובני מעיים."],
["Ein_Yaakov:80:39:820",4,80,39,"מגילה · פרק א׳, פסקה ל״ט","ואמר רבי אלעזר אמר רבי חנינא צדיק אבד לדורו משל לאדם שאבדה ממנו מרגלית כל מקום שהיא מרגלית שמה והיא לא אבדה אלא לבעלה."],
["Ein_Yaakov:81:4:3080",4,81,4,"מגילה · פרק ב׳, פסקה ד׳","\"וַעֲלֵיהֶם כְּכָל הַדְּבָרִים\", מְלַמֵּד, שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה בְּסִינַי, דִּקְדּוּקֵי תּוֹרָה, וְדִקְדּוּקֵי סוֹפְרִים, וּמַה שֶּׁסוֹפְרִים עֲתִידִים לְחַדֵּשׁ."],
["Ein_Yaakov:83:14:365",4,83,14,"מגילה · פרק ד׳, פסקה י״ד","כָּל מָקוֹם שֶׁאַתָּה מוֹצֵא גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה מוֹצֵא עַנְוְתָנוּתוֹ. דָּבָר זֶה כָּתוּב בַּתּוֹרָה, וְשָׁנוּי בַּנְּבִיאִים, וּמְשֻׁלָּשׁ בַּכְּתוּבִים."],
["Ein_Yaakov:84:4:1166",4,84,4,"תענית · פרק א׳, פסקה ד׳","כְּשֵׁם שֶׁאִי־אֶפְשָׁר לָעוֹלָם בְּלֹא רוּחוֹת, כָּךְ אִי־אֶפְשָׁר לָעוֹלָם בְּלֹא יִשְׂרָאֵל."],
["Ein_Yaakov:84:13:215",4,84,13,"תענית · פרק א׳, פסקה י״ג","אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: לֹא אָבוֹא בִּירוּשָׁלַיִם שֶׁל מַעְלָה, עַד שֶׁאָבוֹא בִּירוּשָׁלַיִם שֶׁל מַטָּה."],
["Ein_Yaakov:84:34:866",4,84,34,"תענית · פרק א׳, פסקה ל״ד","אֵין הַבְּרָכָה מְצוּיָה, אֶלָּא בְּדָבָר שֶׁאֵין הָעַיִן שׁוֹלֶטֶת בּוֹ, שֶׁנֶּאֱמַר: \"יְצַו ה' אִתְּךָ אֶת הַבְּרָכָה בַּאֲסָמֶיךָ\"."],
["Ein_Yaakov:84:49:294",4,84,49,"תענית · פרק א׳, פסקה מ״ט","בִּזְמַן שֶׁהַצִּבּוּר שָׁרוּי בְּצַעַר, אַל יֹאמַר אָדָם: אֵלֵךְ לְבֵיתִי וְאֹכַל וְאֶשְׁתֶּה, וְשָׁלוֹם עָלַיִךְ נַפְשִׁי."],
["Ein_Yaakov:84:53:596",4,84,53,"תענית · פרק א׳, פסקה נ״ג","לֹא הַכֹּל לְאוֹרָה, וְלֹא הַכֹּל לְשִׂמְחָה. צַדִּיקִים לְאוֹרָה, וִישָׁרִים לְשִׂמְחָה."],
["Ein_Yaakov:86:3:1112",4,86,3,"תענית · פרק ג׳, פסקה ג׳","רִבּוֹנוֹ שֶׁל עוֹלָם, גָּלוּי וְיָדוּע לְפָנֶיךָ שֶׁלֹּא לִכְבוֹדִי עָשִׂיתִי, וְלֹא לִכְבוֹד בֵּית אַבָּא עָשִׂיתִי, אֶלָּא לִכְבוֹדְךָ עָשִׂיתִי, כְּדֵי שֶׁיְּהוּ מַיִם מְצוּיִין לְעוֹלֵי רְגָלִים."],
["Ein_Yaakov:86:7:1077",4,86,7,"תענית · פרק ג׳, פסקה ז׳","מתיירא אני שמא על הנס שאתה עושה לי, אתה מנכה מזכיותי, ונמצאתי קטן מכל החסדים ומכל האמת."],
["Ein_Yaakov:87:17:864",4,87,17,"תענית · פרק ד׳, פסקה י״ז","'בְּיוֹם חֲתֻנָּתוֹ', זוֹ מַתַּן תּוֹרָה, 'וּבְיוֹם שִׂמְחַת לִבּוֹ', זֶה בִּנְיַן בֵּית הַמִּקְדָּשׁ, שֶׁיִּבָּנֶה בִּמְהֵרָה בְּיָמֵינוּ אָמֵן."],
["Ein_Yaakov:90:35:4592",4,90,35,"מועד קטן · פרק ג׳, פסקה ל״ה","תַּלְמִידֵי חֲכָמִים, אֵין לָהֶם מְנוּחָה אֲפִלּוּ לָעוֹלָם הַבָּא, שֶׁנֶּאֱמַר: \"יֵלְכוּ מֵחַיִל אֶל חָיִל, יֵרָאֶה אֶל אֱלֹהִים בְּצִיּוֹן\"."],
["Ein_Yaakov:91:3:2008",4,91,3,"חגיגה · פרק א׳, פסקה ג׳","'בַּעֲלֵי אֲסֻפּוֹת', אֵלּוּ תַּלְמִידֵי חֲכָמִים, שֶׁיּוֹשְׁבִין אֲסֻפּוֹת אֲסֻפּוֹת וְעוֹסְקִין בַּתּוֹרָה."],
["Ein_Yaakov:99:23:78",4,99,23,"יבמות · פרק ו׳, פסקה כ״ג","כְּשֵׁם שֶׁמִּצְוָה עַל אָדָם לוֹמַר דָּבָר הַנִּשְׁמָע, כָּךְ מִצְוָה עַל אָדָם שֶׁלֹּא לוֹמַר דָּבָר שֶׁלֹּא נִשְׁמָע."],
["Ein_Yaakov:103:7:54",4,103,7,"יבמות · פרק י׳, פסקה ז׳","רִבּוֹנוֹ שֶׁל עוֹלָם, יְהִי רָצוֹן שֶׁיֹּאמְרוּ דְּבַר שְׁמוּעָה מִפִּי בָּעוֹלָם הַזֶּה."],
["Ein_Yaakov:110:3:792",4,110,3,"כתובות · פרק א׳, פסקה ג׳","אַל יַשְׁמִיעַ אָדָם לְאָזְנָיו דְּבָרִים בְּטֵלִים, מִפְּנֵי שֶׁהֵם נִכְוִים תְּחִלָּה לָאֵבָרִים."],
["Ein_Yaakov:121:4:1160",4,121,4,"כתובות · פרק י״ב, פסקה ד׳","רִבּוֹנוֹ שֶׁל עוֹלָם, גָּלוּי וְיָדוּעַ לְפָנֶיךָ שֶׁיָּגַעְתִּי בְּעֶשֶׂר אֶצְבְּעוֹתַי בַּתּוֹרָה, וְלֹא נֶהֱנֵיתִי אֲפִלּוּ בְּאֶצְבַּע קְטַנָּה, יְהִי רָצוֹן מִלְּפָנֶיךָ, שֶׁיְּהֵא שָׁלוֹם בִּמְנוּחָתִי."],
["Ein_Yaakov:122:3:546",4,122,3,"כתובות · פרק י״ג, פסקה ג׳","כָּל הַמֵּבִיא דּוֹרוֹן לְתַלְמִיד חָכָם, כְּאִלּוּ מַקְרִיב בִּכּוּרִים."],
["Ein_Yaakov:125:18:381",4,125,18,"נדרים · פרק ג׳, פסקה י״ח","'וּמָצָא בָהּ אִישׁ מִסְכֵּן חָכָם', זֶה יֵצֶר־הַטּוֹב. 'וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ', זוֹ תְּשׁוּבָה וּמַעֲשִׂים טוֹבִים."],
["Ein_Yaakov:146:5:405",4,146,5,"גיטין · פרק ד׳, פסקה ה׳","אֵין אָדָם עוֹמֵד עַל דִּבְרֵי תּוֹרָה אֶלָּא אִם כֵּן נִכְשַׁל בָּהֶן."],
["Ein_Yaakov:156:4:473",4,156,4,"סוטה · פרק ה׳, פסקה ד׳","גָּדוֹל הָעוֹשֶׂה מֵאַהֲבָה יוֹתֵר מִן הָעוֹשֶׂה מִיִּרְאָה, שֶׁזֶּה תָּלוּי לְאֶלֶף דּוֹר וְזֶה תָּלוּי לְאַלְפַּיִם דּוֹר."],
["Ein_Yaakov:161:15:734",4,161,15,"קידושין · פרק א׳, פסקה ט״ו","שֶׁכָּל הַמְלַמֵּד אֶת בְּנוֹ תּוֹרָה, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ לִמְּדוֹ לוֹ וְלִבְנוֹ וּלְבֶן בְּנוֹ, עַד סוֹף כָּל הַדּוֹרוֹת."],
["Ein_Yaakov:161:39:365",4,161,39,"קידושין · פרק א׳, פסקה ל״ט","כִּבּוּד אָב וָאֵם, וּגְמִילוּת חֲסָדִים, וְהַכְנָסַת אוֹרְחִים, וַהֲבָאַת שָׁלוֹם בֵּין אָדָם לַחֲבֵרוֹ, וְתַלְמוּד תּוֹרָה כְּנֶגֶד כֻּלָּם."],
["Ein_Yaakov:161:44:20",4,161,44,"קידושין · פרק א׳, פסקה מ״ד","לְעוֹלָם יִרְאֶה אָדָם עַצְמוֹ, כְּאִלּוּ חֶצְיוֹ חַיָּב וְחֶצְיוֹ זַכַּאי, עָשָׂה מִצְוָה אַחַת, אַשְׁרָיו שֶׁהִכְרִיעַ עַצְמוֹ לְכַף זְכוּת."],
["Ein_Yaakov:164:26:152",4,164,26,"קידושין · פרק ד׳, פסקה כ״ו","לְעוֹלָם יְלַמֵּד אָדָם אֶת בְּנוֹ אֻמָּנוּת נְקִיָּה וְקַלָּה, וְיִתְפַּלֵּל לְמִי שֶׁהָעֹשֶׁר וְהַנְּכָסִים שֶׁלּוֹ, שֶׁאֵין אֻמָּנוּת שֶׁאֵין בָּהּ עֲנִיּוּת וַעֲשִׁירוּת, שֶׁלֹּא עֲנִיּוּת מִן הָאֻמָּנוּת, וְלֹא עֲשִׁירוּת מִן הָאֻמָּנוּת, אֶלָּא הַכֹּל לְפִי זְכוּתוֹ."],
["Ein_Yaakov:168:3:653",4,168,3,"בבא קמא · פרק ד׳, פסקה ג׳","לְעוֹלָם יַקְדִּים אָדָם לִדְבַר מִצְוָה, שֶׁבִּשְׁבִיל לַיְלָה אַחַת שֶׁקִּדְּמָתָהּ בְּכִירָה לִצְעִירָה, קִדְּמָתָהּ אַרְבָּעָה דּוֹרוֹת לְיִשְׂרָאֵל:"],
["Ein_Yaakov:172:20:515",4,172,20,"בבא קמא · פרק ח׳, פסקה כ׳","לְעוֹלָם יְהֵא אָדָם מִן הַנִּרְדָּפִין, וְלֹא מִן הָרוֹדְפִין, שֶׁאֵין לְךָ נִרְדָּף בָּעוֹפוֹת יוֹתֵר מִתּוֹרִים וּבְנֵי־יוֹנָה, וְהִכְשִׁירָן הַכָּתוּב לְגַבֵּי הַמִּזְבֵּחַ."],
["Ein_Yaakov:177:5:162",4,177,5,"בבא מציעא · פרק ג׳, פסקה ה׳","לְעוֹלָם יְשַׁלֵּשׁ אָדָם מָעוֹתָיו, שְׁלִישׁ בַּקַּרְקַע וּשְׁלִישׁ בִּפְרַקְמַטְיָא וּשְׁלִישׁ תַּחַת יָדוֹ."],
["Ein_Yaakov:178:11:2922",4,178,11,"בבא מציעא · פרק ד׳, פסקה י״א","רִבּוֹנוֹ שֶׁל עוֹלָם, גָּלוּי וְיָדוּעַ לְפָנֶיךָ שֶׁלֹּא לִכְבוֹדִי עָשִׂיתִי, וְלֹא לִכְבוֹד בֵּית אַבָּא עָשִׂיתִי, אֶלָּא לִכְבוֹדְךָ, שֶׁלֹּא יִרְבּוּ מַחֲלוֹקוֹת בְּיִשְׂרָאֵל."],
["Ein_Yaakov:181:20:308",4,181,20,"בבא מציעא · פרק ז׳, פסקה כ׳","כָּל מַה שֶּׁעָשָׂה אַבְרָהָם לְמַלְאֲכֵי הַשָּׁרֵת בְּעַצְמוֹ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָנָיו בְּעַצְמוֹ."],
["Ein_Yaakov:185:5:1556",4,185,5,"בבא בתרא · פרק א׳, פסקה ה׳","\"וְהֵם תֻּכּוּ לְרַגְלֶךָ\", תָּנִי רַב יוֹסֵף: אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁמְּכַתְּתִין רַגְלֵיהֶם מֵעִיר לְעִיר, וּמִמְּדִינָה לִמְדִינָה לִלְמֹד תּוֹרָה."],
["Ein_Yaakov:185:20:768",4,185,20,"בבא בתרא · פרק א׳, פסקה כ׳","אָמַר רַב נַחְמָן בַּר יִצְחָק: אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁמְּנַדְּדִין שֵׁנָה מֵעֵינֵיהֶם בָּעוֹלָם הַזֶּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׂבִּיעָן מִזִּיו הַשְּׁכִינָה לָעוֹלָם הַבָּא."],
["Ein_Yaakov:186:1:51",4,186,1,"בבא בתרא · פרק ב׳, פסקה א׳","בְּרַם זָכוּר אוֹתוֹ הָאִישׁ לַטּוֹב, וִיהוֹשֻׁעַ בֶּן גַּמְלָא שְׁמוֹ, שֶׁאִלְמָלֵא הוּא נִשְׁתַּכְּחָה תּוֹרָה מִיִּשְׂרָאֵל."],
["Ein_Yaakov:198:21:625",4,198,21,"סנהדרין · פרק ד׳, פסקה כ״א","\"חָכְמוֹת בָּנְתָה\", זוֹ מִדָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבָּרָא אֶת כָּל הָעוֹלָם כֻּלּוֹ בְּחָכְמָה."],
["Ein_Yaakov:200:9:75",4,200,9,"סנהדרין · פרק ו׳, פסקה ט׳","לְעוֹלָם יַקְדִּים אָדָם תְּפִלָּה לְצָרָה, שֶׁאִלְמָלֵא לֹא הִקְדִּים אַבְרָהָם תְּפִלָּה לַצָּרָה בֵּין בֵּית־אֵל וּבֵין הָעָי, לֹא נִשְׁתַּיֵּר מִשּׂוֹנְאֵיהֶן שֶׁל יִשְׂרָאֵל שָׂרִיד וּפָלִיט."],
["Ein_Yaakov:204:4:47",4,204,4,"סנהדרין · פרק י׳, פסקה ד׳","עַנְוְתָן, וּשְׁפַל בֶּרֶךְ, שַׁיִף עַיִל, שַׁיִף וְנָפִיק, וְגָרִיס בְּאוֹרַיְתָא תְּדִירָא, וְלָא מַחֲזִיק טִיבוּתָא לְנַפְשֵׁיהּ."],
["Ein_Yaakov:205:9:1323",4,205,9,"סנהדרין · פרק י״א, פסקה ט׳","אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מַה שֶּׁאֲנִי מֵמִית, אֲנִי מְחַיֶּה, וַהֲדַר מַה שֶּׁמָּחַצְתִּי, אֲנִי אֶרְפָּא."],
["Ein_Yaakov:217:1:81",4,217,1,"עדויות · פרק א׳, פסקה א׳","לְלַמֵּד לַדּוֹרוֹת הַבָּאִים שֶׁלֹּא יְהֵא אָדָם עוֹמֵד עַל דְּבָרָיו, שֶׁהֲרֵי אֲבוֹת הָעוֹלָם לֹא עָמְדוּ עַל דִּבְרֵיהֶם."],
["Ein_Yaakov:225:2:3",4,225,2,"עבודה זרה · פרק א׳, פסקה ב׳","אמר רבי יהושע בן לוי כל מצות שישראל עושין בעולם הזה הן באות ומעידות עליהם לעולם הבא שנאמר יתנו עדיהם ויצדקו."],
["Ein_Yaakov:225:19:303",4,225,19,"עבודה זרה · פרק א׳, פסקה י״ט","תנא דבי אליהו לעולם ישים אדם עצמו על דברי תורה כשור לעול וכחמור למשאוי:"],
["Ein_Yaakov:225:52:499",4,225,52,"עבודה זרה · פרק א׳, פסקה נ״ב","חסידים וצדיקים לא נאמר כאן אלא ענוים הא למדת שענוה גדולה מכלם:"],
["Ein_Yaakov:226:5:319",4,226,5,"עבודה זרה · פרק ב׳, פסקה ה׳","אַשְׁרֵי רַבִּי עֲקִיבָא וְתַלְמִידָיו, שֶׁלֹּא פָּגַע בָּהֶן אָדָם רַע מֵעוֹלָם."],
["Ein_Yaakov:264:5:91",4,264,5,"מנחות · פרק י״ג, פסקה ה׳","אָמַר רַבִּי יוֹחָנָן: אֵלּוּ תַּלְמִידֵי חֲכָמִים הָעוֹסְקִים בַּתּוֹרָה בַּלַּיְלָה, מַעֲלֶה עֲלֵיהֶם הַכָּתוּב כְּאִלּוּ עוֹסְקִים בַּעֲבוֹדָה."],
["Ein_Yaakov:267:4:444",4,267,4,"חולין · פרק ג׳, פסקה ד׳","זוֹכֶה וְנוֹחֵל שְׁנֵי עוֹלָמוֹת, הָעוֹלָם הַזֶּה, וְהָעוֹלָם הַבָּא. \"אַשְׁרֶיךָ\", בָּעוֹלָם הַזֶּה, \"וְטוֹב לָךְ\", לָעוֹלָם הַבָּא."],
["Ein_Yaakov:267:5:95",4,267,5,"חולין · פרק ג׳, פסקה ה׳","לָמַדְנוּ בְּרָכָה לְיִשְׂרָאֵל מִפִּי כֹּהֲנִים, לְכֹהֲנִים עַצְמָן לֹא לָמַדְנוּ, כְּשֶׁהוּא אוֹמֵר: \"וַאֲנִי אֲבָרֲכֵם\", הֱוֵי אוֹמֵר כֹּהֲנִים מְבָרְכִים לְיִשְׂרָאֵל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ לַכֹּהֲנִים."],
["Ein_Yaakov:267:18:184",4,267,18,"חולין · פרק ג׳, פסקה י״ח","מְלַמֵּד שֶׁיָּצְאוּ דְּשָׁאִים, וְעָמְדוּ עַל פֶּתַח קַרְקַע, עַד שֶׁבָּא אָדָם הָרִאשׁוֹן וּבִקֵּשׁ עֲלֵיהֶם רַחֲמִים, וְיָרְדוּ גְּשָׁמִים וְצָמְחוּ. לְלַמֶּדְךָ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְאַוֶּה לִתְפִלָּתָן שֶׁל צַדִּיקִים."],
["Ein_Yaakov:267:21:473",4,267,21,"חולין · פרק ג׳, פסקה כ״א","אָמַר רַבִּי יוֹחָנָן: כֵּיוָן שֶׁבָּאָה רָחָם, בָּאוּ רַחֲמִים לָעוֹלָם."],
["Ein_Yaakov:267:22:379",4,267,22,"חולין · פרק ג׳, פסקה כ״ב","אָמַר רַב הוּנָא אָמַר רַב מִשּׁוּם רַבִּי מֵאִיר: לְעוֹלָם יִשְׁנֶה אָדָם לְתַלְמִידָיו דֶּרֶךְ קְצָרָה."],
["Ein_Yaakov:288:4:1983",4,288,4,"ערכין · פרק ג׳, פסקה ד׳","כָּל הַמְּסַפֵּר לָשׁוֹן הָרָע, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֵין אֲנִי וְהוּא יְכוֹלִין לָדוּר בָּעוֹלָם."],
["Ein_Yaakov:296:3:226",4,296,3,"כריתות · פרק א׳, פסקה ג׳","כָּל תַּעֲנִית שֶׁאֵין בָּהּ מִפּוֹשְׁעֵי יִשְׂרָאֵל, אֵינָה תַּעֲנִית, שֶׁהֲרֵי חֶלְבְּנָה רֵיחָהּ רַע, וּמְנָאָהּ הַכָּתוּב בֵּין סַמָּנֵי הַקְּטֹרֶת."],
["Mivchar_HaPeninim:1:5:5",5,1,5,"פרק א׳, פסקה ה׳","ראוי למחזיק בחכמה ובצדק. שלא ירא משום אדם: ואמר הצדיקים אינם יראים כי אם האלהים לבדו:"],
["Mivchar_HaPeninim:1:11:11",5,1,11,"פרק א׳, פסקה י״א","איני דורש החכמה לתקוה שאבוא עד קצה. ואגיע עד תכליתה. אבל אדרוש אותה שלא אהיה סכל ואין ראוי למשכיל זולתו:"],
["Mivchar_HaPeninim:1:20:5",5,1,20,"פרק א׳, פסקה כ׳","אין דבר שמועיל לאדם כדעת מעלתו והשגתו שכלו בחכמה וידבר בפיהם:"],
["Mivchar_HaPeninim:1:21:6",5,1,21,"פרק א׳, פסקה כ״א","האדם חכם בעודנו מבקש החכמה. וכאשר יחשוב שהגיע אל תכליתה. הוא סכל."],
["Mivchar_HaPeninim:1:22:5",5,1,22,"פרק א׳, פסקה כ״ב","לא הנחילו האבות לבנים דבר שהוא חשוב מן החכמה. כי האדם קונה הון בחכמה. ומאבדו באולת וישאר חסר כל."],
["Mivchar_HaPeninim:1:29:5",5,1,29,"פרק א׳, פסקה כ״ט","מי שמתעסק בתורה. לא יתכן שיהא צוארו עב וגופו שמן:"],
["Mivchar_HaPeninim:1:45:5",5,1,45,"פרק א׳, פסקה מ״ה","מי שלבש בבקשת החכמה לבוש הבושת. ילבוש מהכסילות אפוד מעיל. ועל כן תקרעו מעיל הבושת בבקשת החכמה:"],
["Mivchar_HaPeninim:1:53:5",5,1,53,"פרק א׳, פסקה נ״ג","בקשת החכמה בימי הזקנה כתיו על החול. ובקשת החכמה בימי הנערות כפתוח על האבן:"],
["Mivchar_HaPeninim:1:55:5",5,1,55,"פרק א׳, פסקה נ״ה","הזריזות. שתשמור מה שצוית בו לעשות. ותעזוב מה שלא צוית בו."],
["Mivchar_HaPeninim:1:65:5",5,1,65,"פרק א׳, פסקה ס״ה","מי שמתחכם מבלי חכמה. כחמור הרחים סובב סובב ואינו זז ממקומו:"],
["Mivchar_HaPeninim:1:66:5",5,1,66,"פרק א׳, פסקה ס״ו","חמלו על נכבד שנקל. ועל עשיר שנורש. ועל חכם שנפל בין הפתאים."],
["Mivchar_HaPeninim:3:6:5",5,3,6,"פרק ג׳, פסקה ו׳","אין זו טובה שתמנע מהזיק. אבל מדה טובה היא שתסבול הנזק."],
["Mivchar_HaPeninim:3:20:5",5,3,20,"פרק ג׳, פסקה כ׳","תחלת ריוח העניו. שיעזרו אותו בני אדם על הסבל:"],
["Mivchar_HaPeninim:8:3:5",5,8,3,"פרק ח׳, פסקה ג׳","שאדם אחד בא לפני מושל. אמר לו. באתי אליך לשאול דבר ששאלתיו תחלה מהבורא. אם תעשהו אשבח האלהים ואודך. ואם לא תעשה. אשבח את ה׳ ואודהו ואדינך לזכות וצוה למלאת משאלו:"],
["Mivchar_HaPeninim:10:5:5",5,10,5,"פרק י׳, פסקה ה׳","הסתפק במה שחלק לך הבורא. ואל תביט אל מה שיש לזולתך:"],
["Mivchar_HaPeninim:10:14:5",5,10,14,"פרק י׳, פסקה י״ד","ראש ההסתפקות והזריזות. שלא יגדל בעיניך הרב על זולתך. ואל ימעט בעיניך המעט שלך. גם אל תשקול מי שלמעלה ממך בך:"],
["Mivchar_HaPeninim:15:7:5",5,15,7,"פרק ט״ו, פסקה ז׳","מי שידע שהאלהים רואהו ושומע זה ימנענו מן המעשים הרעים. הוא הירא את דבריו והמשיב נפשו מן התאוה:"],
["Mivchar_HaPeninim:15:12:5",5,15,12,"פרק ט״ו, פסקה י״ב","מי שאינו מושל בנפשו להשיבה מן תאותה אינו בטוח מן רע אחריתה ואינו יכול למשל באחרים:"],
["Mivchar_HaPeninim:15:13:5",5,15,13,"פרק ט״ו, פסקה י״ג","כשיעלה על לבך דבר. ולא תמצא עם מי שתועץ שתבטח בו ובעצתו. סור מן הקרב אל תאותך כי התאוה אויבת השכל:"],
["Mivchar_HaPeninim:16:3:5",5,16,3,"פרק ט״ז, פסקה ג׳","עשה חסד עם מי שראוי לו ועם מי שאינו ראוי לו. כי אם יהיה ראוי לו תשיבהו במקומו. ואם אינו ראוי לו תהיה אתה ראוי לו. כי הבורא צוה לעשות הטוב והחסד:"],
["Mivchar_HaPeninim:17:4:5",5,17,4,"פרק י״ז, פסקה ד׳","הראיה על דעת האדם בחירתו ולא נגמרה אמונת האדם עד שנגמרה דעתו:"],
["Mivchar_HaPeninim:18:12:5",5,18,12,"פרק י״ח, פסקה י״ב","המוסר מעביר מהדעתן שכרות. ויוסיף לשוטה שכרות כמו שהיום מוסיף לבעלי העינים ראות ולעטלף עורון:"],
["Mivchar_HaPeninim:18:16:5",5,18,16,"פרק י״ח, פסקה ט״ז","ראוי לאדם שיהא בוחר בארבעה. שידבר בטוב שבדברים. ושיאזין הטוב כשידברו עמו. ושיסבור פנים למי שיפגע. וילמד לשונו לדבר טוב. ויברח מהארבעה. מלדבר עם הכסיל. ומחלוק עם עקש. ומהחליק לשון לנבל. ומחבורות המשחית."],
["Mivchar_HaPeninim:20:10:5",5,20,10,"פרק כ׳, פסקה י׳","אני מצאתי כל קניני עולם ומכמניו אבודים. ואין מכמן כמוסר. ואין מעוז כחברים. ועל כן הרבה מהעוזרים ועוז ביקר המוסר:"],
["Mivchar_HaPeninim:20:17:5",5,20,17,"פרק כ׳, פסקה י״ז","החברים שלש כתות. מהם כמזון שלא תוכל לעמוד מבלעדיו. ומהם כרפואה אשר אתה צריך לעתים. ומהם כמדוה אשר אין אתה צריך לעולם:"],
["Mivchar_HaPeninim:22:2:5",5,22,2,"פרק כ״ב, פסקה ב׳","אין תוכחת בני אדם מועילה לאיש כשאין לו מוכיח משכלו:"],
["Mivchar_HaPeninim:25:2:5",5,25,2,"פרק כ״ה, פסקה ב׳","כשיתקיימו השרשים בלבבות. יראו הסעיפים על הלשונות. ולא תראה לך אהבה ישרה אלא מלב שלם:"],
["Mivchar_HaPeninim:25:4:5",5,25,4,"פרק כ״ה, פסקה ד׳","אין נקב המחט צר לשני אוהבים. ואין רוחב העולם די לשני שונאים:"],
["Mivchar_HaPeninim:27:7:5",5,27,7,"פרק כ״ז, פסקה ז׳","כשתשב שב עם הנדיבים. כי אין כבודו של אדם וקלונו אלא באיש ישיבתו:"],
["Mivchar_HaPeninim:27:10:5",5,27,10,"פרק כ״ז, פסקה י׳","שב עם החכמים והאזן אל חידותם ואל יסורו מלבבך:"],
["Mivchar_HaPeninim:30:5:5",5,30,5,"פרק ל׳, פסקה ה׳","כשתירא מן החרטה אמר לא קודם הן. וכאשר תאמר הן סבול וקיים מה שאמרת. כי לא אחר הן מגונה מאוד:"],
["Mivchar_HaPeninim:32:15:5",5,32,15,"פרק ל״ב, פסקה ט״ו","מי שיהיו דבריו יותר משכלו יהיו דבריו עליו. ומי ששכלו יותר מדבריו יהיו דבריו לו:"],
["Mivchar_HaPeninim:32:18:5",5,32,18,"פרק ל״ב, פסקה י״ח","חכם כשתדבר המעט. כי כפי שימעטו דברי האדם ימעטו טעיותיו:"],
["Mivchar_HaPeninim:38:15:5",5,38,15,"פרק ל״ח, פסקה ט״ו","הנפש הטובה . והשכן הטוב. והדירה הטובה. והבגדים הנקיים מאריכין ימיו של אדם בטובה:"],
["Mivchar_HaPeninim:43:13:0",5,43,13,"פרק מ״ג, פסקה י״ג","בני אל תגזור דבר עד שתועץ את מי שיישר אותך. בני ירא מרעי בני אדם והזהר מטוביהם:"],
["Mivchar_HaPeninim:43:19:5",5,43,19,"פרק מ״ג, פסקה י״ט","אל תרבו לדבר מבלי זכר האלהים פן יקשה לבבכם. כי הלב הקשה רחוק מאלהים."],
["Mivchar_HaPeninim:43:21:5",5,43,21,"פרק מ״ג, פסקה כ״א","מי שנקה מן השלשה לא יחסר שלשה. מי שנקה מן הכעס. יגיע אל היקר. ומי שנקה מן העברות יגיע אל הכבוד. ומי שנקה מן הכילות יגיע אל הגדולה:"],
["Mivchar_HaPeninim:43:29:0",5,43,29,"פרק מ״ג, פסקה כ״ט","מי שמתקן את סתרו. יתקן הקדוש ברוך הוא גלויו. ומי שמתקן עניני אחריתו. יתקן הבורא עולמו ואחריתו. ומי שמתקן מה שבינו לבין הבורא. יתקן הבורא מה שבינו ובין בני אדם:"],
["Mivchar_HaPeninim:43:39:0",5,43,39,"פרק מ״ג, פסקה ל״ט","מי שגנה ענין עצמו בגלוי ישבחו לו בסתר. ומי שהראה מום בנפשו כבר שכחה:"],
["Mivchar_HaPeninim:43:43:5",5,43,43,"פרק מ״ג, פסקה מ״ג","מי שהיו בו שלשה דברים כבר נשלמה אמונתו. כשהוא רוצה אין רצונו מוציא אותו אל השקר. וכשהוא כועס אין כעסו מוציא אותו מן האמת. וכשהוא יכול אינו שולח יד במה שאינו שלו:"],
["Mivchar_HaPeninim:43:53:5",5,43,53,"פרק מ״ג, פסקה נ״ג","החל נפשך למונעה מתעותה. וכאשר תמנע תקרא חכם. ותהיה תוכחתך נשמעת. אם תוכיח ישמעו בני אדם דבריך וילמדו ממעשיך:"],
["Mivchar_HaPeninim:43:54:5",5,43,54,"פרק מ״ג, פסקה נ״ד","כשיתקבצו לאדם היראה והצדק אין מזיק לו החסרון:"],
["Mivchar_HaPeninim:44:2:5",5,44,2,"פרק מ״ד, פסקה ב׳","אין מבקשין העולם אלא לעושר ולמנוחה ולכבוד. ומבקש העולם לא יגיע אליו. והפורש ממנו יהיה יקר בעזיבת הבקשה מבני אדם. ועשיר בשמחתו בחלקו. ומניח בגופו. בהוצאות העולם מלבו ומגיע לבקשתו בלא טורח ובלא עמל:"],
["Mivchar_HaPeninim:44:6:5",5,44,6,"פרק מ״ד, פסקה ו׳","זכור עם כל טובה סורה. ועם כל צרה התקוה לאלהים שיעבירנה. כי בזה תתמיד הטובה ותנצל מן החטא:"],
["Mivchar_HaPeninim:44:18:5",5,44,18,"פרק מ״ד, פסקה י״ח","הגדולה עם השפלות. והכבוד עם היראה. והעושר עם ההסתפקות."],
["Mivchar_HaPeninim:44:25:5",5,44,25,"פרק מ״ד, פסקה כ״ה","טוב שתכאב נפשך לאנשי הצרות משתשמח באנשי הנעימות:"],
["Mivchar_HaPeninim:44:26:5",5,44,26,"פרק מ״ד, פסקה כ״ו","דמיתי האדם בבקשת העולם כצמא שהגיע למים מלוחים כל אשר ישתה מהם יוסיף צמאו:"],
["Mivchar_HaPeninim:44:28:5",5,44,28,"פרק מ״ד, פסקה כ״ח","מי שלא דאג על מה שלא הגיע לידו נחה נפשו וזך שכלו ויאריכו ימיו:"],
["Mivchar_HaPeninim:44:37:0",5,44,37,"פרק מ״ד, פסקה ל״ז","הפרישות מן העולם פנאי ללב ומנוחה לגוף. ואהבת עולם טרדת הלב ויגיעת הגוף. ומי שידע האל לא ידאג לחסרון ולא ישתומם לא מן הטרף ולא מן בני אדם:"],
["Mivchar_HaPeninim:44:38:0",5,44,38,"פרק מ״ד, פסקה ל״ח","מי ששם דאגתו אחר הבורא יעביר ממנו דאגת העולם הזה והעולם הבא:"],
["Mivchar_HaPeninim:44:39:5",5,44,39,"פרק מ״ד, פסקה ל״ט","לכל לבב יש דבר שמטרידו. והטרדה בעולם משברת העצמות ומכלה המוח:"],
["Mivchar_HaPeninim:47:20:5",5,47,20,"פרק מ״ז, פסקה כ׳","כשתשאל שאל מאנשי הנדיבות והחסד. ואל תשאל מן הכילי כי איננו שמח בשאלתך:"],
["Mivchar_HaPeninim:51:6:10",5,51,6,"פרק נ״א, פסקה ו׳","מי שיאמין הרכילות לא ישאר לו אוהב אפילו אם יהיה חביב או קרוב:"],
["Mivchar_HaPeninim:51:8:5",5,51,8,"פרק נ״א, פסקה ח׳","אל תגלה מסתורי רעות בני אדם פן יגלה הבורא מסתורי רעותיך. וספר בטובתם כשתזכיר שמם ואל תגנה אותם במה שיש בך:"],
["Mivchar_HaPeninim:55:2:5",5,55,2,"פרק נ״ה, פסקה ב׳","מי שבטח בעצתו תועה. ומי שסמך בשכלו נכשל. ומי שמתגאה על בני אדם שפל:"],
["Mivchar_HaPeninim:60:2:5",5,60,2,"פרק ס׳, פסקה ב׳","אל תתעקש עם הכעסן. כי תכעיסהו ותאשם. ואל יקבצו במושבך שני אנשים שחולקים לנצוח:"],
["Orchot_Chaim_LHaRosh:1:17:4",6,1,17,"פרק א׳, פסקה י״ז","שֶּׁלֹּא יָשִׂיחַ שִׂיחָה בְּטֵלָה. וְיִזָּהֵר לִלְמוֹד בַּלַּיְלָה עַד שֶּׁיִּשַּׁן מִתּוֹךְ דִּבְרֵי תּוֹרָה, וְלֹא מִתּוֹךְ שִׂיחָה בְּטֵלָה:"],
["Orchot_Chaim_LHaRosh:1:19:3",6,1,19,"פרק א׳, פסקה י״ט","כְּשֶּׁיַּגִּיעַ עֵת תְּפִלָּה מִשָּׁלשּׁ תְּפִלּוֹת שֶּׁבַּיּוֹם, יַנִּיחַ כָּל עֲסָקָיו וְיִתְפַּלֵּל. וְרֹאשּׁ כָּל הַדְּבָרִים שֶּׁיִּשְּׁמוֹר אֶת עֵינָיו מִכָּל דָּבָר שֶּׁאֵינוֹ שֶּׁלּוֹ:"],
["Orchot_Chaim_LHaRosh:2:2:4",6,2,2,"פרק ב׳, פסקה ב׳","מִדְּבַר שֶּׁקֶר תִּרְחָק. וְאַל תּוֹצִיא שֵּׁם שָּׁמַיִם לְבַטָּלָה וְלֹא בְּמָקוֹם מְטֻנָּף:"],
["Orchot_Chaim_LHaRosh:2:7:4",6,2,7,"פרק ב׳, פסקה ז׳","חָבֵר טוֹב הֱיֵה לְיִרְאֵי ה'. הִתְחַבֵּר בְּחֶבְרָתָם. וּמֵחֶבְרַת פּוֹעֲלֵי אָוֶן הַרְחֵק, וֶאֱהוֹב הַמּוֹכִיחִים:"],
["Orchot_Chaim_LHaRosh:2:9:4",6,2,9,"פרק ב׳, פסקה ט׳","יוֹמָם וָלַיְלָה זִכְרוֹ מִפִּיךָ אַל יָמוּשּׁ. בְּשָּׁכְבְּךָ תִּשְׁגֶּה בְּאַהֲבָתוֹ, וּבְקוּמֶךָ וּבְהִלּוּכֶךָ תִּמְצָאֶנּוּ, וַהֲקִיצוֹתָ בּוֹ תְּשַּׁעֲשָּׁע, וְהוּא יְיַשֵּׁר אוֹרְחוֹתֶיךָ:"],
["Orchot_Chaim_LHaRosh:3:5:4",6,3,5,"פרק ג׳, פסקה ה׳","עֶרֶב וָבֹקֶר וְצָהֳרַיִם שְּׁמוֹר הָעִתִּים הַקְּבוּעִים לַתְּפִלָּה, וּפְתַח לִבְּךָ שָּׁעָה אַחַת קוֹדֶם תְּפִלָּה. וֶהֱוֵי זָהִיר שֶּׁתִּהְיֶה מֵעֲשָׂרָה הָרִאשּׁוֹנִים. וְאַל תְּדַבֵּר שִׂיחָה בְּטֵלָה בְּבֵית הַכְּנֶסֶת. וּתְפִלִּין עַל רֹאשְּׁךָ וְעַל זְרֹעֲךָ אַל יֶחְסָרוּ:"],
["Orchot_Chaim_LHaRosh:3:8:4",6,3,8,"פרק ג׳, פסקה ח׳","שְׂמַח בְּשָּׁמְעֲךָ תּוֹכַחַת, כְּמוֹצֵא שָּׁלָל רָב. וְהוֹכַח לְחָכָם וְיֶאֱהָבֶךָ. כִּי טוֹבָה תּוֹכַחַת מְגֻלָּה מֵאַהֲבָה מְסוּתָּרֶת, וְלַמּוֹכִיחִים יִנְעָם:"],
["Orchot_Chaim_LHaRosh:3:10:4",6,3,10,"פרק ג׳, פסקה י׳","הִזָּהֵר שֶּׁלֹּא תִּסְמוֹךְ בִּלְבָבְךָ, וּשְּׁמַע עֵצָה וְקַבֵּל מוּסָר, וְתִּהְיֶה זָרִיז לַעֲשׂוֹת כָּל מַה שֶּׁמֻּטָּל עָלֶיךָ לַעֲשׂוֹת, וּמִכָּל מִשְׁמָר נְצוֹר לִבֶּךָ:"],
["Orchot_Chaim_LHaRosh:3:11:4",6,3,11,"פרק ג׳, פסקה י״א","אַל תָּקוּם מִמִּטָּתְךָ כְּאִישּׁ עָצֵל, כִּי אִם בִּזְרִיזוּת כְּדֵי לַעֲבוֹד לְיוֹצְרֶךָ:"],
["Orchot_Chaim_LHaRosh:4:1:4",6,4,1,"פרק ד׳, פסקה א׳","אַל תִּתְרַשֵּׁל בְּמִצְוָה אִם בָּאָה לְיָדְךָ וְתַעֲשֶׂנָּה לְשֵּׁם שָּׁמַיִם בְּלֹא אִיחוּר:"],
["Orchot_Chaim_LHaRosh:4:3:4",6,4,3,"פרק ד׳, פסקה ג׳","אַל תַּעֲשֶׂה דָּבָר שֶּׁיַּלְעִיגוּ הַבְּרִיּוֹת, שֶּׁדַּרְכָּם לְהַעֲלִים הַטּוֹבוֹת וּלְגַלּוֹת הָרָעוֹת:"],
["Orchot_Chaim_LHaRosh:4:10:4",6,4,10,"פרק ד׳, פסקה י׳","אַל תַּחֲזִיק כַּעַסְךָ עִם חֲבֵירְךָ יוֹם אֶחָד, וְתִכָּנַע לְפָנָיו לְבַקֵּשּׁ מִמֶּנּוּ מְחִילָה קוֹדֶם:"],
["Orchot_Chaim_LHaRosh:4:11:4",6,4,11,"פרק ד׳, פסקה י״א","אַל תְּדַבֵּר בְּצַוָּאר עָתָק וְאַל תָּעִיז מֶצַח שֶּׁלֹּא לְקַבֵּל עָלֶיךָ יִרְאַת שָּׁמַיִם:"],
["Orchot_Chaim_LHaRosh:4:13:4",6,4,13,"פרק ד׳, פסקה י״ג","אַל תִּתְעַבֵּר עַל רִיב לֹא לָךְ, כִּי לְסוֹף הֵם יַשְּׁלִימוּ בֵּינֵיהֶם וְאַתָּה תִּשָּׁאֵר בְּכַעַס:"],
["Orchot_Chaim_LHaRosh:4:15:4",6,4,15,"פרק ד׳, פסקה ט״ו","אַל תְּהִי בָּז לְכָל אָדָם וּלְכָל דָּבָר, שֶּׁאֵין לְךָ אָדָם שֶּׁאֵין לוֹ שָּׁעָה וְאֵין לְךָ דָּבָר שֶּׁאֵין לוֹ מָקוֹם:"],
["Orchot_Chaim_LHaRosh:4:20:4",6,4,20,"פרק ד׳, פסקה כ׳","אַל תִּתְפַּלֵּל כִּי אִם בְּכַוָּנַת הַלֵּב וּבְנַחַת, כְּדֵי שֶּׁיִּשְּׁמַע הָאוֹזֶן:"],
["Orchot_Chaim_LHaRosh:5:2:4",6,5,2,"פרק ה׳, פסקה ב׳","אַל תֹּאמַר עַל שּׁוּם מִצְוָה אֶעֱשֶׂה אוֹתָהּ לְמָחָר, שֶּׁמֶּא לֹא תִּפָּנֶה לַעֲשׂוֹת:"],
["Orchot_Chaim_LHaRosh:5:4:4",6,5,4,"פרק ה׳, פסקה ד׳","אַל תַּנִּיחַ דֶּרֶךְ חֲסִידוּת אַף עַל פִּי שֶּׁמַּלְעִיגִין עָלֶיךָ, וְאַל תֵּבוֹשּׁ לִדְבַר מִצְוָה:"],
["Orchot_Chaim_LHaRosh:5:8:4",6,5,8,"פרק ה׳, פסקה ח׳","אַל תַּבִּיט לְמִי שֶּׁהוּא קָטָן מִמְּךָ בַּעֲבוֹדָה וּבְיִרְאָה, כִּי אִם לְגָדוֹל מִמְּךָ:"],
["Orchot_Chaim_LHaRosh:5:11:4",6,5,11,"פרק ה׳, פסקה י״א","אַל תְּהִי נִבְהָל לְהָשִּׁיב בְּעַזּוּת לְמִי שֶּׁאָמַר דְּבָרִים אֲשֶּׁר לֹא טוֹבִים:"],
["Orchot_Chaim_LHaRosh:5:13:4",6,5,13,"פרק ה׳, פסקה י״ג","אַל תַּלְבִּין פְּנֵי חֲבֵרְךָ בָּרַבִּים, כִּי הָעוֹשֶׂה כֵּן אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא:"],
["Orchot_Chaim_LHaRosh:5:14:4",6,5,14,"פרק ה׳, פסקה י״ד","אַל תַּרְאֶה יְכוֹלֶת נֶגֶד שּׁוּם אָדָם אִם יָדְךָ גָּבְרָה, כִּי לֹא תֵדַע אִם תַּחֲלוֹשּׁ:"],
["Orchot_Chaim_LHaRosh:5:15:4",6,5,15,"פרק ה׳, פסקה ט״ו","אַל תִּרְדּוֹף אַחַר הַכָּבוֹד, וְלֹא תַּעֲלֶה בְּמַעֲלָה שֶּׁאֵינָה רְאוּיָה לָךְ:"],
["Orchot_Chaim_LHaRosh:5:29:4",6,5,29,"פרק ה׳, פסקה כ״ט","אַל תֶּרֶף יָדְךָ לִקְנוֹת לְךָ חָבֵר נֶאֱמָן וּשְּׁמוֹר אוֹתוֹ, וְאַל תְּאַבְּדֵהוּ כִּי טוֹב:"],
["Orchot_Chaim_LHaRosh:6:1:4",6,6,1,"פרק ו׳, פסקה א׳","אַל תְּפַתֶּה אֶת חֲבֵרְךָ בְּשִׂפְתֵי חֲלָקוֹת וּבַחֲנִיפוּת, וְאַל תְּדַבֵּר בְּלֵב וָלֵב:"],
["Orchot_Chaim_LHaRosh:6:4:4",6,6,4,"פרק ו׳, פסקה ד׳","אַל תַּעֲלֶה בְּדַעְתְּךָ לְנַצֵחַ אֶת הֶחָכָם, כִּי לֹא תַּרְבֶּה עַל חָכְמָתְךָ חָכְמָה:"],
["Orchot_Chaim_LHaRosh:6:5:4",6,6,5,"פרק ו׳, פסקה ה׳","אַל תְּהִי קַפְּדָן לְדָבָר מוּעָט נֶגֶד שּׁוּם אָדָם, פֶּן תְּלַקֵּט שׂוֹנְאִים עַל חִנָּם:"],
["Orchot_Chaim_LHaRosh:6:6:4",6,6,6,"פרק ו׳, פסקה ו׳","אַל תְּהִי לָהוּט לָדַעַת הַסְּתָרִים שֶּׁבֵּין אָדָם לַחֲבֵרוֹ וְדָבָר הַמְּכֻסֶּה מִמְּךָ:"],
["Orchot_Chaim_LHaRosh:6:8:4",6,6,8,"פרק ו׳, פסקה ח׳","אַל תַּחְשּׁוֹב עָוֹן לְמִי שֶּׁיָּבוֹא לְהִתְנַצֵל לְפָנֶיךָ אִם אֱמֶת וְאִם שֶּׁקֶר:"],
["Orchot_Chaim_LHaRosh:6:23:5",6,6,23,"פרק ו׳, פסקה כ״ג","אַל תְּהִי רָגִיל לֵישֵּׁב עִם הַלֵּצִים פְּחוּתֵי הַנֶּפֶשּׁ פֶּן יַחֲטִיאוּךָ:"],
["Orchot_Chaim_LHaRosh:6:24:5",6,6,24,"פרק ו׳, פסקה כ״ד","אַל תִּתְעַצֵל לְבַקֵּשּׁ חָכְמָה, וּלְיַסֵּר אֶת חֲבֵרְךָ בְּסֵתֶר וְדֶרֶךְ כָּבוֹד:"],
["Orchot_Chaim_LHaRosh:6:27:5",6,6,27,"פרק ו׳, פסקה כ״ז","אַל תְּהִי כְּפוּי טוֹבָה, וְכַבֵּד כָּל מִי שֶּׁפָּתַח לְךָ פֶּתַח לְבַקִּשּׁ דֵּי סִפּוּקְךָ:"],
["Orchot_Chaim_LHaRosh:6:30:5",6,6,30,"פרק ו׳, פסקה ל׳","אַל תַּרְגִּיל עַצְמְךָ לַעֲמוֹד, כִּי אִם אֵצֶל חָכָם, וּשְּׁמַע וְהַאֲזִין דְּבָרָיו:"],
["Orchot_Chaim_LHaRosh:7:23:4",6,7,23,"פרק ז׳, פסקה כ״ג","שֶּׁיְּקַיֵּם בְּהַצְנֵעַ לְכַלְכֵּל מַעֲשָׂיו הַטּוֹבִים כִּי הוּא עֲבוֹדַת ה' יִתְבָּרַךְ הַנִּבְחֶרֶת וְהָרְצוּיָה לְפָנָיו:"],
["Iggeret_HaRamban:1:2:0",7,1,2,"פסקה ב׳","תִּתְנַהֵג תָּמִיד לְדַבֵּר כָּל דְּבָרֶיךָ בְּנַחַת, לְכָל אָדָם וּבְכָל עֵת, וּבַזֶּה תִּנָּצֵל מִן הַכַּעַס, שֶׁהִיא מִדָּה רָעָה לְהַחְטִיא בְּנֵי אָדָם."],
["Iggeret_HaRamban:1:7:331",7,1,7,"פסקה ז׳","הַכָּל שָׁוֶה לִפְנֵי הַמָּקוֹם, כִּי בְאַפּוֹ מַשְׁפִּיל גֵּאִים, וּבִרְצוֹנוֹ מַגְבִּיהַ שְׁפָלִים."],
["Iggeret_HaRamban:1:9:0",7,1,9,"פסקה ט׳","בְּכָל דְּבָרֶיךָ וּמַעֲשֶֹיךָ וּמַחְשְׁבוֹתֶיךָ, וּבְכָל עֵת – חֲשׁוֹב בְּלִבָּךְ כְּאִלוּ אַתָּה עוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ עָלֶיךָ, כִּי כְּבוֹדוֹ מָלֵא הָעוֹלָם."],
["Maalot_HaMiddot:3:4:0",8,3,4,"ב; מעלת אהבת האל, פסקה ד׳","בני, בואו וראו כמה גדול שכרו של אוהב את המקום שכן זכותו עומדת לעד אלפים דורות כענין שנאמר ועושה חסד לאלפים לאהבי ולשמרי מצותי."],
["Maalot_HaMiddot:3:6:0",8,3,6,"ב; מעלת אהבת האל, פסקה ו׳","בני, התנהגו עם כל אדם במוסר הזה כי בדבר הזה תרבה עליכם אהבת בני אדם. כמו שאמר חכם אחד מי שרוצה להיות אהוב לבני אדם יתנהג עמם במוסר הטוב."],
["Maalot_HaMiddot:4:3:911",8,4,3,"ג; מעלת יראת שמים וכיבוד אב ואם, פסקה ג׳","שכשם שהוא ירא מן המקום, כך הקדוש ברוך הוא מטיל אימתו על הבריות ויראין מפניו."],
["Maalot_HaMiddot:4:7:2764",8,4,7,"ג; מעלת יראת שמים וכיבוד אב ואם, פסקה ז׳","גדולה מצות כיבוד אב ואם שמאריכין ימיו ושנותיו של אדם ומטיבין לו ונוחל חיי העולם הזה וחיי העולם הבא."],
["Maalot_HaMiddot:4:10:0",8,4,10,"ג; מעלת יראת שמים וכיבוד אב ואם, פסקה י׳","בני, בואו וראו כמה חביבה מצות כיבוד אב ואם לפני המקום שכן צוה עליהם קודם מתן תורה כענין שנאמר כבד את אביך ואת אמך כאשר צוך ה' אלהיך ואחז\"ל כאשר צוך במרה."],
["Maalot_HaMiddot:5:2:3572",8,5,2,"ד; מעלת התורה וקיום המצות, פסקה ב׳","מהו כל המצות שיהיו כל מצותיה של תורה חשובין בעיניך כמצוה אחת שקולות זו כזו שתהא זריז לעשות מצוה קלה כמצוה חמורה."],
["Maalot_HaMiddot:5:5:0",8,5,5,"ד; מעלת התורה וקיום המצות, פסקה ה׳","בני, הוו זהירין מאד בתורה ובמצות ובמעשים טובים לפי שבשעת פטירתו של אדם אין מלווין לו לאדם אלא תורה ומעשים טובים בלבד."],
["Maalot_HaMiddot:5:6:0",8,5,6,"ד; מעלת התורה וקיום המצות, פסקה ו׳","בני, אם באת מצוה לידכם אל תחמצוה אלא עשו אותה מיד בהשתדלות בלי רישול כענין שנאמר ושמרתם את המצות אל תיקרי המצות אלא המצוות שכשם שאין מחמיצין את המצה כך אין מחמיצין את המצוה אלא אם באת מצוה לידך עשה מיד."],
["Maalot_HaMiddot:5:7:575",8,5,7,"ד; מעלת התורה וקיום המצות, פסקה ז׳","הוי מקדים לדבר מצוה כדי שלא יקדמוך הפורעניות אם באת מצוה לידך אל תשמח לאותה מצוה אלא לאותה הבאה אחריה."],
["Maalot_HaMiddot:5:9:1054",8,5,9,"ד; מעלת התורה וקיום המצות, פסקה ט׳","גדול כח התורה וקיום המצות שכן מצילין את האדם מיצר הרע שכך אמרו חז\"ל אם פגע בך מנוול זה משכהו לבית המדרש."],
["Maalot_HaMiddot:6:2:0",8,6,2,"ה; מעלת גמילות חסדים, פסקה ב׳","בני, בואו ואלמדכם מעלת גמילות חסדים, דעו בני כי מעלת גמילות חסדים מעלה חביבה מאד לפני הקדוש ברוך הוא, ובעבורה יזכה האדם לקנות חייה העולם הזה והעולם הבא."],
["Maalot_HaMiddot:6:7:0",8,6,7,"ה; מעלת גמילות חסדים, פסקה ז׳","גדולה גמילות חסדים שאדם אוכל הפירות בעולם הזה והקרן קיימת לו לעולם הבא."],
["Maalot_HaMiddot:6:14:0",8,6,14,"ה; מעלת גמילות חסדים, פסקה י״ד","בני, הוו זהירין בגמילות חסדים מפני שזכותה עומדת לו לאדם ולבניו ולבני ביתו עד סוף כל הדורות."],
["Maalot_HaMiddot:6:17:162",8,6,17,"ה; מעלת גמילות חסדים, פסקה י״ז","הטיב חסדיך עד שתקדים בלא שאלה, וכן ירגיל אדם עצמו לשלם טובה למי שגמל עמו טובה, כדי שלא יהיה מכפויי הטובה, שכשם שנוח לו לאדם שיהו כל הבריות גומלין עמו חסד בשעה שהוא צריך להם, כך הוא ראוי לגמול חסד לכל אחד בשעה שהן צריכין לו."],
["Maalot_HaMiddot:7:4:494",8,7,4,"ו; מעלת הצדקה, פסקה ד׳","גדול הצדקה שהוא אוכל הפירות בעולם הזה והקרן קיימת לו לעולם הבא, שנאמר צדקתו עומדת לעד."],
["Maalot_HaMiddot:7:14:0",8,7,14,"ו; מעלת הצדקה, פסקה י״ד","לעולם יבקש אדם רחמים מלפני המקום, שלא יביאהו לידי עוני, שאם לא בא הוא בא בנו."],
["Maalot_HaMiddot:9:2:571",8,9,2,"ח; מעלת הענוה ומדת הגאוה, פסקה ב׳","כל מקום שאתה מוצא גדולתו של הקדוש ברוך הוא שם אתה מוצא ענוותנותו."],
["Maalot_HaMiddot:9:3:0",8,9,3,"ח; מעלת הענוה ומדת הגאוה, פסקה ג׳","בני, בואו וראו כמה גדולה מעלת הענוה, שהרי משה רבינו היה רבן של כל הנביאים ומבחר כל הנבראים שהיו מאדם הראשון עד כאן."],
["Maalot_HaMiddot:9:5:0",8,9,5,"ח; מעלת הענוה ומדת הגאוה, פסקה ה׳","בני, אהבו את הענוה ותדבקו בשפלות מפני שמביאין את האדם לידי כבוד, כענין שנאמר: כי השפילו ותאמר גוה ושח עיניים יושיע."],
["Maalot_HaMiddot:9:8:183",8,9,8,"ח; מעלת הענוה ומדת הגאוה, פסקה ח׳","לעולם יהא אדם ענוותן כהלל. ואמר חכם אחד: כל מעלה באדם מתקנאין עליה חוץ מן הענוה."],
["Maalot_HaMiddot:9:12:207",8,9,12,"ח; מעלת הענוה ומדת הגאוה, פסקה י״ב","יועץ המדע הענוה ואמר כי פרי הענוה, הנצחון, ופרי השפלות, השלום והשלוה. ומעולם לא ראינו עניו מתחרט ושפל נכשל."],
["Maalot_HaMiddot:9:14:0",8,9,14,"ח; מעלת הענוה ומדת הגאוה, פסקה י״ד","בני, התנהגו במידת הענוה כי בעבורה ירבו אוהביכם וימעטו אויביכם וירבו עוזריכם וימעטו חומסיכם. כמו שאמר חכם אחד: מי שרב שכלו ונראית ענוותנותו ימעטו חומסיו וירבו עוזריו."],
["Maalot_HaMiddot:9:20:543",8,9,20,"ח; מעלת הענוה ומדת הגאוה, פסקה כ׳","הגדולה מעטרה לבורא וכל מי שרוצה להכנס עליו במעשהו יהדפהו. וכל המתגאה הקדוש ברוך הוא משפילו, כענין שנאמר: גאות אדם תשפילנו."],
["Maalot_HaMiddot:9:21:260",8,9,21,"ח; מעלת הענוה ומדת הגאוה, פסקה כ״א","כלומר, אם השפיל אדם את עצמו למטה, מגביהין אותו למעלה. ואם הגביה עצמו מלמטה, משפילין אותו מן השמים למעלה."],
["Maalot_HaMiddot:10:2:0",8,10,2,"ט; מעלת הצניעות ומדת הפריצות, פסקה ב׳","גדול הוא מדת הצניעות לפני המקום, שכך אמרו חז\"ל באגדה התורה תחילתה צניעות וסופה צניעות."],
["Maalot_HaMiddot:11:4:567",8,11,4,"י; מעלת הבושת ומדת העזות, פסקה ד׳","כלל הדבר, יתבייש מן הבורא ואז תשלם לו מעלת מדת הבושת על שלמותה. כמו שאמר חכם אחד כשתעשה דבר בתוך ביתך תתבייש מבני ביתך, וכשתעשה דבר בשוק תתבייש מן האנשים, ואם לאו תתבייש מעצמך."],
["Maalot_HaMiddot:11:5:0",8,11,5,"י; מעלת הבושת ומדת העזות, פסקה ה׳","בני, הוו זהירין במידת הבושת, שבשעה שאדם מתבייש מן האנשים הרי הוא נזהר מן הדברים המגונים והמכוערים ואינו נכשל בהן."],
["Maalot_HaMiddot:12:1:0",8,12,1,"יא; מעלת האמונה ומדת הגזל, פסקה א׳","בני, בואו ואלמדכם מעלת האמונה, דעו בני כי מעלת האמונה מעלה נכבדת וגדולה מאוד בעיני המקום, שכל הנושא ונותן עם הבריות באמונה, ויושב במחיצתו של הקדוש ברוך הוא כענין שנאמר עיני בנאמני ארץ וגומר."],
["Maalot_HaMiddot:12:5:0",8,12,5,"יא; מעלת האמונה ומדת הגזל, פסקה ה׳","בני, אל תהי מעלת האמונה קלה בעיניכם, שהרי הדביקו בה אבות העליונים באברהם נאמר והאמין בה' וגומר."],
["Maalot_HaMiddot:12:11:0",8,12,11,"יא; מעלת האמונה ומדת הגזל, פסקה י״א","בני, אם בא לכם שום פגע יהיה הסבל מזומן ותדיחו אותו בסבל, ותנו הודאה לבורא במה שגזר עליכם, כי הסבל הוא העושר הגדול. ואמר חכם אחד, מה שיגביר הסבל בעת צרתו, יגיע אל חפצו מרום לבבו:"],
["Maalot_HaMiddot:12:12:0",8,12,12,"יא; מעלת האמונה ומדת הגזל, פסקה י״ב","בני, אם תתגבר עליכם תאותכם הכניעוה בסבל, כי הסבל הוא ממדת החסידים, וכל מי שהוא סבלן, יהיה אדון."],
["Maalot_HaMiddot:13:2:245",8,13,2,"יב; מעלת התמימות ומדת הרמאות, פסקה ב׳","גדולה מעלת התמימות שכל מי שהולך בתמימות לב בכל דרכיו זוכה ויושב במחיצתו של מקום, כענין שנאמר ה' מי יגור באהליך הולך תמים וגומר."],
["Maalot_HaMiddot:13:4:0",8,13,4,"יב; מעלת התמימות ומדת הרמאות, פסקה ד׳","גדולה מידת התמימות לפני המקום שכל מי שהולך בתמימות הקדוש ברוך הוא רוצה וחפץ בו כענין שנאמר ורצונו תמימי דרך."],
["Maalot_HaMiddot:13:6:0",8,13,6,"יב; מעלת התמימות ומדת הרמאות, פסקה ו׳","גדולה מעלת האמת, שכן שמה הולכת מסוף העולם ועד סופו שכשם שאותיות אמת הן מפוזרין אלף בראש האותיות מם באמצען תיו בסופן."],
["Maalot_HaMiddot:14:3:0",8,14,3,"יג; מעלת הרחמנות ומדת אכזריות, פסקה ג׳","גדולה היא מידת הרחמנות לפני המקום, שכל המרחם על הבריות מביא טובה לעולם, שנאמר טוב ה' לכל, אימתי בזמן שרחמיו על כל מעשיו."],
["Maalot_HaMiddot:14:4:0",8,14,4,"יג; מעלת הרחמנות ומדת אכזריות, פסקה ד׳","גדולה היא החיבה שחיבב הקדוש ברוך הוא את ישראל שנתן להם הרחמים במתנה, שכך אמרו חז\"ל שלש מתנות טובות יש ביד ישראל, בויישנין ורחמנין וגומלי חסדים."],
["Maalot_HaMiddot:14:5:0",8,14,5,"יג; מעלת הרחמנות ומדת אכזריות, פסקה ה׳","גדולה היא מידת הרחמנות, שבזמן שישראל מרחמין זה על זה הקדוש ברוך הוא מרחם עליהן וגואל אותן שנאמר ברגע קטן עזבתיך וברחמים גדולים אקבצך."],
["Maalot_HaMiddot:14:6:0",8,14,6,"יג; מעלת הרחמנות ומדת אכזריות, פסקה ו׳","אשריהן בעלי רחמנות שאין הקדוש ברוך הוא פוסק רחמיו מהן ומתנהג עמהם תמיד בחסד וברחמים והן נוצרין אותו כענין שנאמר אתה ה' לא תכלא רחמיך ממני חסדך ואמתך תמיד יצרוני."],
["Maalot_HaMiddot:14:8:0",8,14,8,"יג; מעלת הרחמנות ומדת אכזריות, פסקה ח׳","בני, הוו רגילין במידת הרחמנות מפני שהיא מידה מיוחסת ויאות אל כל משכיל להתנהג בה כמו שאמר חכם אחד אשרי מי שליבותם מרחמים ונמוכים."],
["Maalot_HaMiddot:15:1:271",8,15,1,"יד; מעלת הרצון ומדת הכעס, פסקה א׳","גדולה היא מידת הרצון והדעת נוחה לפני המקום מפני שהיא מידה מקובלת בעיני המקום ובעיני הבריות."],
["Maalot_HaMiddot:15:2:241",8,15,2,"יד; מעלת הרצון ומדת הכעס, פסקה ב׳","בני התרצו במה שגזרו עליכם מן השמים, וקבלו אותו בשמחה, כי לא תוכלו לדחותו מעליכם כי אם בתשובה ומעשים טובים."],
["Maalot_HaMiddot:15:3:0",8,15,3,"יד; מעלת הרצון ומדת הכעס, פסקה ג׳","בני, התרצו לחביריכם קודם שיבקשו מכם המחילה, כי מי שמגיע עצמו אל בקשת המחילה, אינו מבעלי הרצון הטוב."],
["Maalot_HaMiddot:15:4:0",8,15,4,"יד; מעלת הרצון ומדת הכעס, פסקה ד׳","בני, התרצו אל כל האנשים במיטב שפתותיכם, ולשאול בשלומם ולדבר טוב עליהם, ועם האנשים החושבים התנהגו בענוה ובשפלות כדי שתפיקו מהם רצון טוב."],
["Maalot_HaMiddot:15:5:10",8,15,5,"יד; מעלת הרצון ומדת הכעס, פסקה ה׳","הגדול שבבני אדם מי שדעתו נוחה ואחריתו טובה, גדולה היא מידת הרצון שכל מי שהוא רצוי למטה בידוע שהוא רצוי למעלה, וכל מי שהוא אהוב למטה בידוע שהוא אהוב למעלה."],
["Maalot_HaMiddot:15:14:0",8,15,14,"יד; מעלת הרצון ומדת הכעס, פסקה י״ד","בני, תשמרו עצמכם מן הכעס, כי הוא מן החלאים שאין להן רפואה, לפיכך ראוי לכם להסיר כעס מליבכם ולמשול ברוחכם ואל יהיה כעסכם מושל על שכלכם."],
["Maalot_HaMiddot:15:17:745",8,15,17,"יד; מעלת הרצון ומדת הכעס, פסקה י״ז","שכל תוכיחה שמוכיח אדם מתוך כעס גמור, אינה מתקבלת על הלב, וכל תוכחה שמראה בעצמו כעוס כאילו הוא כעוס ואינו כעוס בלב, ודעתו נוחה עליו, ואחר כך מרצה את הנוכח הרי היא מתקבלת על הלב."],
["Maalot_HaMiddot:16:8:0",8,16,8,"טו; מעלת שם טוב, פסקה ח׳","בני, תתאוו לשם טוב בעבודת המקום ואהבת כל הבריות לכבוד שמים לא לכבוד עצמכם ולא לשם שררה בעולם כאשר יעשו הסכלים המתאוים לקנות שם טוב בעולם לכבוד עצמם בהבלי העולם ולא לכבוד שמים."],
["Maalot_HaMiddot:16:12:0",8,16,12,"טו; מעלת שם טוב, פסקה י״ב","בני, הוו יודעין שכל זמן שאדם מתכוין להגדיל שמו בעולם שמו אבד ומתמעט והולך שכך אמרו חז\"ל נגד שמא אבד שמיה. ועליו אמר שלמה בחכמתו, כבוד חכמים ינחלו וכסילים מרים קלון."],
["Maalot_HaMiddot:16:14:133",8,16,14,"טו; מעלת שם טוב, פסקה י״ד","שכל זמן שאדם מגדל ומשבח את עצמו הרי הוא משפילו, וכל זמן שאדם משפיל ומקטין את עצמו הרי הוא מרוממו."],
["Maalot_HaMiddot:19:1:0",8,19,1,"יח; מעלת החכמת ומדת הסכלות, פסקה א׳","בני, בואו ואלמדכם מעלת החכמה. דעו בני כי מעלת החכמה מעלה יקרה, אשרי מי שזכה לעלות במעלתה, מפני שהיא מתנה נתונה לאדם מאת הקדוש ברוך הוא."],
["Maalot_HaMiddot:19:4:0",8,19,4,"יח; מעלת החכמת ומדת הסכלות, פסקה ד׳","בני, צאו וראו כמה גדולה מעלת החכמה, שהיא קרית עוז לבעליה, ומגינה על האדם מן החטאים והעוונות."],
["Maalot_HaMiddot:19:13:445",8,19,13,"יח; מעלת החכמת ומדת הסכלות, פסקה י״ג","ראש כל מוסר השתיקה. ואמר אחד: כשתשב עם החכמים יהיה רצונך לשמוע יותר מדבר."],
["Maalot_HaMiddot:19:17:0",8,19,17,"יח; מעלת החכמת ומדת הסכלות, פסקה י״ז","בני, אל תהי מעלת החכמה קלה בעיניכם, מפני שהיא מעלה כללית וכוללת עמה כל שאר מעלות המדות החמודות. כי אם האדם ריק מן החכמה, לא ייתכן שיהיו לו מידות טובות, כי בה יבחין הטוב מן הרע, ודבר נאה מן המכוער."],
["Maalot_HaMiddot:19:19:394",8,19,19,"יח; מעלת החכמת ומדת הסכלות, פסקה י״ט","במוסר לא תצטרך ליחס, ואומר כי פרי המוסר המנוחה והצלחת כל העניינים."],
["Maalot_HaMiddot:19:27:19",8,19,27,"יח; מעלת החכמת ומדת הסכלות, פסקה כ״ז","הסכל קטן ואם יהיה זקן, וחכם גדול ואם יהיה נער."],
["Maalot_HaMiddot:20:13:0",8,20,13,"יט; מעלת העושר, פסקה י״ג","בני, השתדלו לקנות עושר ונכסים באמונה וביושר כדי שתוכלו לחיות בעולם ואל תצטרכו לבריות וכדי שתוכלו לזכות ממנו לעניים."],
["Maalot_HaMiddot:20:14:398",8,20,14,"יט; מעלת העושר, פסקה י״ד","אי זהו עשיר השמח בחלקו שנאמר יגיע כפיך כי תאכל אשריך וטוב לך. אשריך בעולם הזה וטוב לך לעולם הבא."],
["Maalot_HaMiddot:21:6:818",8,21,6,"כ; מעלת הזריזות ומדת העצלות, פסקה ו׳","גדולה היא מדת הזריזות שכל זמן שאדם זריז לעשות מלאכתו וענייניו בזריזות נכסיו מצליחין."],
["Maalot_HaMiddot:22:1:33",8,22,1,"כא; מעלת ההסתפקות ומדת זולל וסובא, פסקה א׳","דעו בני כי מעלת ההסתפקות מעלה חשובה ויקרה עד מאד ואינה נמצאת אלא בחסידים שמסתפקין בדבר מועט כדרך שמסתפקין שאר האנשים בדבר מרובה, שכל מי שמסתפק במה שיש לו ונהנה מיגיעו קונה לו חיי העולם הזה וחיי העולם הבא, כעניין שנאמר יגיע כפיך כי תאכל אשריך וטוב לך."],
["Maalot_HaMiddot:22:3:0",8,22,3,"כא; מעלת ההסתפקות ומדת זולל וסובא, פסקה ג׳","בני, בואו וראו כמה טובה מידת ההסתפקות שכל מי שמרגיל את עצמו במידת ההסתפקות זוכה להיות ביתו מליאה מכל טוב, כענין שנאמר חכמות בנתה ביתה חצבה עמודיה שבעה טבחה טבחה מסכה יינה אף ערכה שלחנה."],
["Maalot_HaMiddot:22:5:0",8,22,5,"כא; מעלת ההסתפקות ומדת זולל וסובא, פסקה ה׳","בני, בואו וראו כמה גדולה מידת ההסתפקות שהרי יעקב אבינו עליו השלום לא שאל מאת המקום אלא מה שמספיק לו בלבד בדבר שאין מנוס ממנו ולא יוכל לחיות בלעדיו כענין שנאמר ונתן לי לחם לאכול ובגד ללבוש."],
["Maalot_HaMiddot:22:8:166",8,22,8,"כא; מעלת ההסתפקות ומדת זולל וסובא, פסקה ח׳","דבש מצאת אכול דייך פן תשבענו והקאתו. ואמר חכם אחד מי שרצה מן העולם כדי ספקו יהיה המעט שבו מספיק לו. ומי שירצה במעט הטרף יקבל הבורא המעט ממעשיו."],
["Maalot_HaMiddot:23:4:0",8,23,4,"כב; מעלת הנדיבות ומדת הכילות וצרות עין, פסקה ד׳","בני, אם באתם לשאול שאלה משום אדם שאלו אותה מן הנדיבים, כי ישמחו בשאילתכם וישתדלו למלאותה בעין טובה."],
["Maalot_HaMiddot:23:5:288",8,23,5,"כב; מעלת הנדיבות ומדת הכילות וצרות עין, פסקה ה׳","צאו וראו שאין בכל המידות מידה טובה כעין טובה, שאם האדם עושה כל המצות שבתורה ואינו נוהג בהן עין טובה אינן עולין לו מן המניין."],
["Maalot_HaMiddot:23:6:0",8,23,6,"כב; מעלת הנדיבות ומדת הכילות וצרות עין, פסקה ו׳","גדולה מידת הנדיבות, שהרי משה רבינו עליו השלום החזיק במידת הנדיבות ועין טובה."],
["Maalot_HaMiddot:24:3:32",8,24,3,"כג; מעלת דרך ארץ, פסקה ג׳","דעו בני כי מעלת דרך ארץ מידה חשובה עד מאד, ובעבורה יקנה האדם חיי העולם הזה וחיי העולם הבא."],
["Maalot_HaMiddot:24:5:365",8,24,5,"כג; מעלת דרך ארץ, פסקה ה׳","עץ החיים זו תורה, כמה שנאמר עץ חיים היא למחזיקים בה ותומכיה מאושר. הא למדת שחביבה מעלת דרך ארץ לפני המקום שהקדימה לתורה."],
["Maalot_HaMiddot:24:6:0",8,24,6,"כג; מעלת דרך ארץ, פסקה ו׳","חביבה היא מידת דרך ארץ לפני המקום, שכל זמן שיש בו באדם דרך ארץ הרי הקדוש ברוך הוא והבריות מתפארין בו, ואף התורה מתפארת בו מפני שכל מי שיש בו דרך ארץ עם התורה היא מתקשטת בה ומתקנת את לומדיה והרי הוא מקובל ומכובד בפני הבריות והבריות מתקרבין אצלו מפני דרך ארץ שבו."],
["Maalot_HaMiddot:24:7:0",8,24,7,"כג; מעלת דרך ארץ, פסקה ז׳","דרך ארץ הוא שיהא האדם מחשב בליבו הדרכים שיש לו לנהוג ולילך בהן כדי שיתרצה בהן בפני המקום ובפני הבריות, כענין שאמר דוד עליו השלום חישבתי דרכי ואשיבה רגלי אל עדותיך."],
["Maalot_HaMiddot:24:8:0",8,24,8,"כג; מעלת דרך ארץ, פסקה ח׳","בני, התנהגו בחסידות וביראת שמים עם הבריות, ותתנהגו עמם בענוה ורוח נמוכה ולשון רכה, ואל תשנו ממנהגות בני אדם, שכל המשנה ידו על התחתונה."],
["Maalot_HaMiddot:24:10:0",8,24,10,"כג; מעלת דרך ארץ, פסקה י׳","בני, השתדלו לידע ולהכיר את בוראכם שברא אתכם מאין והמצא אתכם מאפס וגמלכם כל טוב וגומל לכם תמיד בכל יום."],
["Maalot_HaMiddot:24:17:0",8,24,17,"כג; מעלת דרך ארץ, פסקה י״ז","בני, אהבו את הענוה ובחרו בשפלות מפני שהקדוש ברוך הוא אוהב את הענוים והשפלים ונמוכי הרוח."],
["Maalot_HaMiddot:24:20:0",8,24,20,"כג; מעלת דרך ארץ, פסקה כ׳","בני, אהבו מעלת הבושת ותחזיקו בה שכל המתבייש לא במהרה הוא חוטא וניצל מן החטאים והעונות וזוכה לגן עדן."],
["Maalot_HaMiddot:24:22:0",8,24,22,"כג; מעלת דרך ארץ, פסקה כ״ב","בני, בחרו במידת האמונה, מפני שהיא ממידות הבורא. וכל הזוכה בה זוכה ויושב במחיצתו של הקדוש ברוך הוא."],
["Maalot_HaMiddot:24:24:0",8,24,24,"כג; מעלת דרך ארץ, פסקה כ״ד","בני, אהבו את התמימות, שהקדוש ברוך הוא חפץ בתמימים."],
["Maalot_HaMiddot:24:26:0",8,24,26,"כג; מעלת דרך ארץ, פסקה כ״ו","בני, אהבו מידת הרחמנות שהיא ממידות הבורא. ולא היה העולם מתקיים אילמלא שיתף בו הקדוש ברוך הוא מידת הרחמים."],
["Maalot_HaMiddot:24:28:0",8,24,28,"כג; מעלת דרך ארץ, פסקה כ״ח","בני, אהבו מידת הרצון, שכל מי שהוא רצוי ומקובל מן הבריות למטה בעבור שיודע לרצותם בדבריו ולדבר להם בלשון רכה, בידוע שהוא רצוי ומקובל למעלה, שכל שרוח הבריות נוחה הימנו רוח המקום נוחה הימינו והקדוש ברוך הוא מעלה אותו למעלה ושררה."],
["Maalot_HaMiddot:24:30:0",8,24,30,"כג; מעלת דרך ארץ, פסקה ל׳","בני, בחרו במידת שם טוב בעבודת המקום, שהקדוש ברוך הוא בעצמו חיזר לקנות שם טוב בעולמו."],
["Maalot_HaMiddot:24:35:0",8,24,35,"כג; מעלת דרך ארץ, פסקה ל״ה","בני, בחרו במידת הזריזות, שלא נברא האדם אלא שיהיה זריז ומהיר במלאכתו, והאדם הזריז ממנין אותו על עבודת המלכים והשלטונים וכל מי שמתכבד במלאכתו מלאכתו מכבדתו ונכסיו מצליחין."],
["Maalot_HaMiddot:24:36:0",8,24,36,"כג; מעלת דרך ארץ, פסקה ל״ו","בני, בחרו במידת ההסתפקות מפני שהיא ממדות החסידים המסתפקים בין ברב בין במעט."],
["Maalot_HaMiddot:24:37:0",8,24,37,"כג; מעלת דרך ארץ, פסקה ל״ז","בני, בחרו במידת הנדיבות שלא נבנה העולם עד שלא שיתף בו הקדוש ברוך הוא מידת הנדיבות. והנדיבות מורה על היחס והחסידות."],
["Maalot_HaMiddot:24:38:156",8,24,38,"כג; מעלת דרך ארץ, פסקה ל״ח","בקשו אחר השלום ורדפו אחר השלום שהקדוש ברוך הוא אוהב את השלום ומתחילת ברייתו של עולם נתעסק לבראות דבר של שלום והוא האור."],
["Maalot_HaMiddot:24:39:0",8,24,39,"כג; מעלת דרך ארץ, פסקה ל״ט","בני, אל תתפארו בנפשכם ואל תתנשאו בעצמכם על הבריות בשביל מעלותיכם ובשביל תורה ומעשים טובים שקדמתם אלא תשפילו עצמכם ותכניעו רוחכם לפני כל אדם ותהיו כאסקופה התחתונה שהכל דשין בה וכיתד נמוכה שהכל תולין עליה."],
["Maalot_HaMiddot:24:43:0",8,24,43,"כג; מעלת דרך ארץ, פסקה מ״ג","בני, אם ידברו אחרים עליכם דבר רע גדול אל תגדילו אותו יותר מדאי ואל יהי בעיניכם גדול, אבל יהי בעיניכן כקטון כדי שתניחו מקום לשלום."],
["Maalot_HaMiddot:24:44:0",8,24,44,"כג; מעלת דרך ארץ, פסקה מ״ד","בני, יהי פירקכם נאה ושמועתכם טובה והשתדלו להוסיף על השמועה הטובה כדי שיבחרו הבריות בחברתכם וידבקו בכם ויתקרבו אצלכם כי כל מי שפירקו רע ושמועתו מגונה לא ימצא חברים ויתרחקו הבריות ממנו ויסורו מעליו."],
["Maalot_HaMiddot:24:45:0",8,24,45,"כג; מעלת דרך ארץ, פסקה מ״ה","בני, אהבו את התורה ותכבדו אותה ואת לומדיה שכל המכבד את התורה גופו מכובד על הבריות וכל המחלל את התורה ואינו מכבדה כראוי גופו מחולל ומבוזה על הבריות."],
["Maalot_HaMiddot:24:46:0",8,24,46,"כג; מעלת דרך ארץ, פסקה מ״ו","בני, אם תראו חבריכם תאבים וחפצים בדבר שבידכם וברשותכם למלאות חפצם ורצונם השתדלו לעשות חפצם ובטלו רצונכם מפני רצון חבריכם שכן עשתה רחל ללאה."],
["Maalot_HaMiddot:24:49:0",8,24,49,"כג; מעלת דרך ארץ, פסקה מ״ט","בני, התרחקו שלא יתרעמו עליכם בני אדם שמא תצטרכו להתרעם על אחרים ותוסיפו לחטוא."],
["Maalot_HaMiddot:24:50:0",8,24,50,"כג; מעלת דרך ארץ, פסקה נ׳","בני, אם תרצו ללמוד תורה או דבר חכמה או דבר מדרך ארץ אל תאמרו על מה שלא שמעתם שמענו ואם ישאלו אתכם דבר ואין אתם בקיאין בו אל תתביישו לומר אין אנו יודעין אותו, אבל תאמרו למדוהו לנו."],
["Maalot_HaMiddot:24:52:0",8,24,52,"כג; מעלת דרך ארץ, פסקה נ״ב","בני, אהבו את התוכחות וקנו את המוסר כי יביאו אתכם להצלחת העולם הזה וינחילו אתכם חיי העולם הבא."],
["Maalot_HaMiddot:24:53:0",8,24,53,"כג; מעלת דרך ארץ, פסקה נ״ג","בני, אהבו את כל אדם איש כפי מעלתו ותהיה לשונכם רכה עם כל אדם כי בלשון רכה ייכנעו הקשים וישחו הגאים והאויבים יהפכו לאוהבים."],
["Maalot_HaMiddot:24:55:0",8,24,55,"כג; מעלת דרך ארץ, פסקה נ״ה","בני, יהי כבוד חבריכם חביב עליכם כשלכם ואל תתכבדו בקלונם שכל המתכבד בקלון חברו אין לו חלק לעולם הבא."],
["Maalot_HaMiddot:24:56:0",8,24,56,"כג; מעלת דרך ארץ, פסקה נ״ו","בני, אם חפצים אתם שידבק בכם אהבת הבריות הוו נושאין ונותנין עמהן באמונה וביושר ובצדק והוו נושאין ונותנין בטובתן ואל תספרו בגנותן ויהיו דבריכם עמהן נוחין ועריבים כדי שתהיו אהובים למעלה ונחמדים למטה."],
["Maalot_HaMiddot:24:58:0",8,24,58,"כג; מעלת דרך ארץ, פסקה נ״ח","בני, תעשו המצות על דרך האהבה, ואם עשיתם מצות הרבה יהו בעיניכם מעטים לפי חיובכם בהם."],
["Maalot_HaMiddot:24:59:0",8,24,59,"כג; מעלת דרך ארץ, פסקה נ״ט","בני, אם עשיתם טובה וגמילות חסדים וצדקה אל תאמרו משלנו היטבנו, אלא ממה שהיטיבו לכם מן השמים, לפיכך צריכין אתם ליתן שבח והודאה לבורא שספן לכם טובה והיטיב לכם, ואם היטיבו לכם מן השמים דבר מועט יהי בעיניכם הרבה."],
["Maalot_HaMiddot:24:63:0",8,24,63,"כג; מעלת דרך ארץ, פסקה ס״ג","בני, לעולם הוו דנין את כל האדם לכף זכות, ואל תכריעו אותו לכף חובה, שכל המכריע את חבירו לכף חובה מפריד החברה וסוגר דלתי השלום ופותח דלתי התחרות והאיבה, ולא עוד אלא שמן השמים ידינו אותו לכף חובה."],
["Maalot_HaMiddot:24:71:0",8,24,71,"כג; מעלת דרך ארץ, פסקה ע״א","בני, הוו יושבין עם החכמים, והתרחקו משבת עם הכסילים מפני שאין כבודו של אדם וקלונו אלא בישיבתו."],
["Maalot_HaMiddot:24:72:0",8,24,72,"כג; מעלת דרך ארץ, פסקה ע״ב","בני, אל תהיו כאסקופה העליונה שמנגפת את הרגלים ולא כאמצעית שכל היושב עליה זועף וסופה להיסתר. אלא הוו כאסקופה התחתונה שרוב בני אדם דורסין אותה וסיף כל הבניין כולו נסתר והיא במקומה עומדת."],
["Maalot_HaMiddot:24:73:0",8,24,73,"כג; מעלת דרך ארץ, פסקה ע״ג","בני, אם תראו אדם חכם יותר מכם אל תאמרו מפני מה זה האיש חכם יותר ממנו מפני שלא שימשתם כיוצא בו ולא נתעסקתם בחכמה כמוהו."],
["Maalot_HaMiddot:24:77:412",8,24,77,"כג; מעלת דרך ארץ, פסקה ע״ז","אזניך שלא שמעת בהם דברים בטילין הם יאזינו לך לחיי העולם הבא. פיך שלא סיפר בלשון הרע עליו יהרגו כל בעלי הריגה. פיך שעמל בדברי תורה עליו יתברכו כל בעלי ברכה."],
["Maalot_HaMiddot:24:79:0",8,24,79,"כג; מעלת דרך ארץ, פסקה ע״ט","בני, אהבו לילך תמיד לבית הכנסת כדי להתפלל בו כדי שתיטלו שכרכם בכל יום שאפילו על פסיעותיכם אתם מקבלין שכר."],
["Maalot_HaMiddot:24:80:0",8,24,80,"כג; מעלת דרך ארץ, פסקה פ׳","בני, אהבו את המדרש ואת חכמי התורה כדי שתזכו ויבואו בניכם לתלמוד תורה."],
["Maalot_HaMiddot:24:82:0",8,24,82,"כג; מעלת דרך ארץ, פסקה פ״ב","בני, אהבו את תלמידי חכמים שנוהגין בעצמן כדרך שתלמידי חכמים נוהגין ותכבדו אותם כבוד גדול והמקום יכבד אתכם ויעלה אתכם אל המעלות העליונות."],
["Maalot_HaMiddot:24:85:79",8,24,85,"כג; מעלת דרך ארץ, פסקה פ״ה","הדר תורה חכמה, הדר חכמה יראה, הדר יראה ענוה, הדר ענוה צניעות."],
["Maalot_HaMiddot:24:91:0",8,24,91,"כג; מעלת דרך ארץ, פסקה צ״א","הוי רך כקנה שהרוח מנשבת בו לכל צד שתרצה, שאין התורה מתקיימת אלא במי שרוחו נמוכה עליו ולא במי שרוחו מושלת עליו."],
["Maalot_HaMiddot:24:92:145",8,24,92,"כג; מעלת דרך ארץ, פסקה צ״ב","כל המתחכם בדברי תורה מוסיפין לו חכמה על חכמתו שנאמר תן לחכם ויחכם עוד."],
["Maalot_HaMiddot:25:1:244",8,25,1,"כד; מעלת השלום ומדות המחלוקת · לשון הרע ורכילות, פסקה א׳","גדול השלום לפני המקום, שכך אמרו חז\"ל באגדה ז\"ל גדול השלום שאפילו הכתובים דיברו דברי בדאים להטיל שלום בין אברהם לשרה, שהרי היא אמרה ואדוני זקן, והוא אמר לאברהם ואני זקנתי."],
["Maalot_HaMiddot:25:3:362",8,25,3,"כד; מעלת השלום ומדות המחלוקת · לשון הרע ורכילות, פסקה ג׳","מהו לשלום כל האדם, כלומר אפילו אם אתה רואה שליבו עליך, הוי מקדים לו שלום, שאם אתה עושה כן תגרום לך שיאהבך."],
["Maalot_HaMiddot:25:4:470",8,25,4,"כד; מעלת השלום ומדות המחלוקת · לשון הרע ורכילות, פסקה ד׳","בקשהו היום, ורדפהו למחר. ואל תתיאש לומר לא אוכל להשלים, אלא רדוף אחר השלום עד שתגיענו."],
["Maalot_HaMiddot:25:10:806",8,25,10,"כד; מעלת השלום ומדות המחלוקת · לשון הרע ורכילות, פסקה י׳","שכל זמן שהן שרויין בשלום זה עם זה השכינה ביניהן."],
["Kad_HaKemach:7:5:751",9,7,5,"אֵבֶל · חלק ג׳, פסקה ה׳","צריך אדם להזהר במדת החסד שעם מדה זו יתמשל לבוראו ית' וילך בדרכיו כי המדה הזאת היא ממדותיו ובה הוא יתעלה מנהיג עולמו."],
["Kad_HaKemach:9:3:0",9,9,3,"בטחון · חלק א׳, פסקה ג׳","ענין הבטחון בהשי\"ת פירש הרב הקדוש ר' יונה זצ\"ל כי הוא שידע האדם עם לבבו כי הכל בידי שמים ובידו לשנות הטבעים ולהחליף המזל ואין לו מעצור להושיע ברב או במעט."],
["Kad_HaKemach:31:2:1609",9,31,2,"טהרת הלב · חלק א׳, פסקה ב׳","רבי עקיבא אומר למה נמשלו דברי תורה לזכוכית לומר לך מה זכוכית זה כל מה שאתה נותן לתוכו הוא מראה לך כך תלמיד חכם צריך שיהא מראה בפיו כל מה שיש בלבו."],
["Kad_HaKemach:38:9:0",9,38,9,"לשון הרע · חלק א׳, פסקה ט׳","יתחייב אדם לשמור דרכיו מחטוא בלשונו ושלא ישתמש בדבורו באחד מדרכי החטא, כי הדיבור באדם מצד הנפש המשכלת שבו ועמו יש לו יתרון על כל שאר בעלי חיים."],
["Kad_HaKemach:46:1:107",9,46,1,"שמחה · חלק א׳, פסקה א׳","אין השמחה ראויה בעוה\"ז כי אם בעבודת הש\"י ולא תמצא בכל ספרי הקדש שישבח השמחה אלא בענין העבודה וההשגה בהקב\"ה."],
["Kad_HaKemach:48:5:3371",9,48,5,"שנאת חנם · חלק א׳, פסקה ה׳","עיקר קבלת התוכחת שיגיע אדם מזה לתיקון המדות שאם לא כן לשוא יוכיח המוכיח, והנה זה בדמיון החורש שאם לא יגיע לזריעה לשוא יחרוש."],
["Kad_HaKemach:76:2:0",9,76,2,"שלום · חלק א׳, פסקה ב׳","גדולה מדת השלום שכל המצות כולן נחתמות בשלום והשלום חתימת הכל, ועל כן תקנו לנו רבותינו חתימת התפלה בשלום המברך את עמו ישראל בשלום."],
["Ohr_Yisrael:13:2:417",10,13,2,"שערי אור · פרק י״ב, פסקה ב׳","כל המרחם על הבריות מרחמין עליו מן השמים. ואין לך רחמנות גדולה. מלהזכיר ולעורר בני אדם ללימוד היראה."],
["Kav_HaYashar:6:8:0",11,6,8,"פרק ה׳, פסקה ח׳","יְהִי רָצוֹן מִלְּפָנֶיךָ, ה' אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ, שֶׁתַּחְתֹּר חֲתִירָה מִתַּחַת כִּסֵּא כְּבוֹדֶךָ לִתְשׁוּבַת פְּלוֹנִי בֶּן פְּלוֹנִית, וְכָל הָעוֹבְרִים עַל מִצְווֹתֶיךָ יֵהָפֵךְ לְבָבָם לַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם, כִּי יְמִינְךָ פְשׁוּטָה לְקַבֵּל שָׁבִים, וְהַחֲזִירֵנוּ בִּתְשׁוּבָה שְׁלֵמָה לְפָנֶיךָ."],
["Kav_HaYashar:11:1:0",11,11,1,"פרק י׳, פסקה א׳","צָרִיךְ הָאָדָם לְהִזָּהֵר כְּשֶׁיַּעֲשֶׂה סְעוּדַת מִצְוָה, כְּגוֹן מִילָה אוֹ סְעוּדַת אֵרוּסִין אוֹ נִשּׂוּאִין וּסְעוּדַת בַּר מִצְוָה, יִזָּהֵר לִהְיוֹת בְּתוֹךְ הַקְּרוּאִים עֲנִיִּים וְאֶבְיוֹנִים, וּלְהַשְׁגִּיחַ עֲלֵיהֶם בִּדְבָרִים נָאִים."],
["Kav_HaYashar:22:12:0",11,22,12,"פרק כ״א, פסקה י״ב","אַשְׁרֵי מִי שֶׁהוֹלֵךְ תָּמִים, וַעֲמָלוֹ בַּתּוֹרָה, וְכָל דְּרָכָיו הוּא לְשֵׁם שָׁמַיִם, אֲזַי נִשְׁמָתוֹ הוּא מוּכֶנֶת לִכָּנֵס לְעֵדֶן, דְּאִקְרֵי \"גִּנַּת אֱגוֹז\", וְהוּא חַיֵּי עוֹלָם הַבָּא."],
["Kav_HaYashar:40:15:0",11,40,15,"פרק ל״ט, פסקה ט״ו","יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי, שֶׁתִּסְלַח וְתִמְחַל לִי עַל כָּל פְּשָׁעִים וַחֲטָאִים מַה שֶּׁעָשִׂיתִי, הֵן בִּרְאוֹת עֵינַי, הֵן מַה שֶּׁחָטָאתִי בְּיָדַי וְרַגְלַי וּבְגוּפִי."],
["Kav_HaYashar:54:1:0",11,54,1,"פרק נ״ג, פסקה א׳","כָּל מַה שֶּׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם — הַכֹּל הוּא לִכְבוֹדוֹ בָּרָא."],
["Kav_HaYashar:54:13:0",11,54,13,"פרק נ״ג, פסקה י״ג","כְּשֵׁם שֶׁמְּחֻיָּב הָאָדָם לְקַיֵּם מִצְוַת הַגַּשְׁמִית, כָּךְ הוּא מְצֻוֶּה עַל הָרוּחָנִית לְחַדֵּשׁ חִדּוּשִׁים בַּתּוֹרָה."],
["Kav_HaYashar:55:8:0",11,55,8,"פרק נ״ד, פסקה ח׳","צָרִיךְ הָאָדָם לִהְיוֹת אוֹהֵב לוֹמְדֵי תּוֹרָה אַהֲבָה גְּמוּרָה, וּמִכָּל שֶׁכֵּן שֶׁצָּרִיךְ לֶאֱהֹב אֶת רַבּוֹ וְצָרִיךְ לֶאֱהֹב אֶת רַבּוֹ יוֹתֵר מֵאַהֲבַת אָבִיו."],
["Kav_HaYashar:56:3:800",11,56,3,"פרק נ״ה, פסקה ג׳","אֵין עוֹמְדִין לְהִתְפַּלֵּל אֶלָּא מִתּוֹךְ כֹּבֶד רֹאשׁ. חֲסִידִים הָרִאשׁוֹנִים הָיוּ שׁוֹהִין שָׁעָה אַחַת קֹדֶם שֶׁיִּתְפַּלְּלוּ, כְּדֵי שֶׁיְּכַוְּנוּ אֶת לִבָּם לַמָּקוֹם."],
["Kav_HaYashar:60:2:552",11,60,2,"פרק נ״ט, פסקה ב׳","דַּע בְּנִי, הָעִנְיָן הוּא מְבֹאָר בְּזֹהַר שְׁלַח לְךָ, כִּי נִשְׁמַת הָאָדָם דּוֹמָה לְנֵר, וְטֶבַע הַנֵּר, כְּשֶׁאֵינוֹ מֵאִיר כָּרָאוּי — אֲזַי מְנַעְנְעִים אוֹתוֹ קְצָת, וְעַל יְדֵי כֵן מִתְלַהֵב יוֹתֵר וְיָאִיר כָּרָאוּי."],
["Kav_HaYashar:63:2:885",11,63,2,"פרק ס״ב, פסקה ב׳","כְּשֵׁם שֶׁמִּצְוָה לוֹמַר דָּבָר הַנִּשְׁמָע, כָּךְ מִצְוָה שֶׁלֹּא לוֹמַר דָּבָר שֶׁאֵינוֹ נִשְׁמָע."],
["Kav_HaYashar:64:3:150",11,64,3,"פרק ס״ג, פסקה ג׳","יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי, שֶׁתְּהֵא תְּפִלָּתִי צְלוּלָה וְזַכָּה וּבְרוּרָה מִכָּל עִרְבּוּבְיָא הַמְבַטְּלִים כַּוָּנוֹת הַתְּפִלָּה."],
["Kav_HaYashar:66:1:299",11,66,1,"פרק ס״ה, פסקה א׳","לְעוֹלָם יִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ חֶצְיוֹ חַיָּב, וְחֶצְיוֹ זַכַּאי. עָשָׂה מִצְוָה אַחַת — אַשְׁרָיו, שֶׁהִכְרִיעַ עַצְמוֹ וְאֶת כָּל הָעוֹלָם לְכַף זְכוּת."],
["Kav_HaYashar:67:3:359",11,67,3,"פרק ס״ו, פסקה ג׳","כָּל הַמַּלְבִּין פְּנֵי חֲבֵרוֹ בָּרַבִּים — אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. גַּם גּוֹרֵם עִרְבּוּב הַשֵּׂכֶל בַּתּוֹרָה וּבַתְּפִלָּה."],
["Kav_HaYashar:80:3:1043",11,80,3,"פרק ע״ט, פסקה ג׳","עַל כֵּן בָּאנוּ לְהוֹדִיעַ אוֹתְךָ, כִּי לְשָׁעָה קַלָּה תָּבוֹא אֶל בֵּית שִׂמְחָתְךָ וְתָבוֹא מֵאֲפֵלָה לְאוֹרָה, וְתַעֲמֹד לִפְנֵי הַבּוֹרֵא הָעוֹלָם יִתְבָּרַךְ וְתֵשֵׁב בֵּין חֲבוּרוֹת צַדִּיקִים, וְתִזְכֶּה לוֹמַר שִׁירָה לִפְנֵי רִבּוֹן עָלְמָא."],
["Kav_HaYashar:85:5:0",11,85,5,"פרק פ״ד, פסקה ה׳","עַל כֵּן, אַחַי וְרֵעַי, סוּרוּ סוּרוּ מִן דַּרְכֵי הַגַּאֲוָה וְתִרְאוּ לְדַבֵּר עִם כָּל אָדָם וּלְקָרֵב הָעֲנִיִּים, וּבִפְרָט שֶׁצָּרִיךְ לְהַקְדִּים שָׁלוֹם לָעֲנִיִּים, וּמִכָּל שֶׁכֵּן מְחֻיָּב לְהַחֲזִיר לוֹ שָׁלוֹם, וְאָז עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל."],
["Kav_HaYashar:86:16:0",11,86,16,"פרק פ״ה, פסקה ט״ז","יְהִי רָצוֹן מִלְּפָנֶיךָ, ה' אֱלֹהַי וֵאלֹהֵי אֲבוֹתַי, שֶׁלֹּא אֶכְעַס וְלֹא אַכְעִיסֶךָ, רִבּוֹנוֹ שֶׁל עוֹלָם! זַכֵּנִי לְמִדַּת עֲנָוָה וּלְמִדַּת הַכְנָעָה, וְדֶרֶךְ שֶׁקֶר הָסֵר מִמֶּנִּי וְתוֹרָתְךָ חָנֵּנִי!"],
["Kav_HaYashar:94:6:1542",11,94,6,"פרק צ״ג, פסקה ו׳","כָּל מִי שֶׁבְּלִבּוֹ תָּדִיר צַעַר עַל גָּלוּת הַשְּׁכִינָה — זוֹכֶה לְכֶתֶר תּוֹרָה."],
["Kav_HaYashar:101:1:35",11,101,1,"פרק ק׳, פסקה א׳","דַּע, כִּי מִדַּת הַתְּמִימוּת הִיא מַעֲלָה הַמְעֻלָּה שֶׁבְּכָל הַמַּעֲלוֹת וּמִדּוֹת הַטּוֹבוֹת, שֶׁצָּרִיךְ לִהְיוֹת בִּבְנֵי אָדָם."],
["Reshit_Chokhmah:51:53:0",12,51,53,"שער הקדושה · פרק י״ב, פסקה נ״ג","הרוצה להנצל מן החניפות יזהר להתרחק מן הכבוד, כי מי שאינו חושש להתכבד לא יצטרך חניפות, וגם צריך ליזהר מאחרים, כי רוב המחניפים הם מחניפים לאדם שהם סבורים שיהיה לו הנאה ממנו."],
["Reshit_Chokhmah:51:100:338",12,51,100,"שער הקדושה · פרק י״ב, פסקה ק׳","אל תבוש לקבל האמת מאיזה המקום שיבא, אפילו מקטן שבקטנים ונבזה שבנבזים תקבל האמת ממנו, כי מרגלית טובה שהיא ביד קטן ונבזה לעולם היא חשובה כמרגלית."],
["Reshit_Chokhmah:80:7:194",12,80,7,"פרק דרך ארץ · שער א׳, פסקה ז׳","כל דבריו יהיו לשם שמים, חרד לכל המצות, אל יהי נבהל להשיב, משיב על ראשון ראשון ועל אחרון אחרון, ועל מה שלא שמע אומר לא שמעתי, אם שאלוהו אפילו דבר קטן אל יבוש לומר לא ידעתי, אלא ילמד לשונו לומר לא ידעתי, שמא יתבדה ויאחז בדבר."],
["Reshit_Chokhmah:80:9:0",12,80,9,"פרק דרך ארץ · שער א׳, פסקה ט׳","לעולם יהיה תלמיד חכם נאה במשאו ובמתנו ובכסותו ובמנעלו ובמאכלו ובשתייתו."],
["Reshit_Chokhmah:80:27:713",12,80,27,"פרק דרך ארץ · שער א׳, פסקה כ״ז","הא למדת שצריך תלמיד חכם לנהוג דרך ארץ בעצמו כדי שלא יבא לידי בזיון."],
["Reshit_Chokhmah:82:52:0",12,82,52,"פרק דרך ארץ · שער ג׳, פסקה נ״ב","הוי גומר בטוב ומשלם טוב ושוחר טוב ומבקש טוב ואפילו על רע. הוי עלוב ואוהב הכל, ושפל רוח ולשון רכה."],
["Reshit_Chokhmah:83:29:0",12,83,29,"פרק דרך ארץ · שער ד׳, פסקה כ״ט","דרך ארץ הסוחר בסחורה, כשימכור סחורתו לא ישבח אותה, וכשיקנה לא יפליג בגנותה, ויהיה משאו ומתנו באמונה, וישמור דבריו לקיים אותם, ואם אמר אמכור לך במנה ונזדמן לו אחר שיתן לו מאתים, לא ישנה דבריו."],
["Reshit_Chokhmah:96:8:0",12,96,8,"אור עולם · שער א׳, פסקה ח׳","לעולם הוי שמח על שלחנך בשעה שהרעבים נהנין ממנו, כדי שתאריך ימים בעולם הזה ובעולם הבא."],
["Reshit_Chokhmah:97:1:0",12,97,1,"אור עולם · שער ב׳, פסקה א׳","בענין התפלה לעולם ישכים אדם לבית הכנסת כדי שימנה עם עשרה ראשונים, שאפילו מאה באין אחריו הוא נוטל שכר כלם, שכר כלם סלקא דעתך, אלא נוטל שכר כנגד כלם."],
["Reshit_Chokhmah:97:9:0",12,97,9,"אור עולם · שער ב׳, פסקה ט׳","לעולם יכוין אדם את עצמו, אם יוכל לכוין את לבו יתפלל, ואם לאו אל יתפלל."],
["Reshit_Chokhmah:97:15:0",12,97,15,"אור עולם · שער ב׳, פסקה ט״ו","לעולם יקדים אדם תפלה לצרה, שאלמלא לא הקדים אברהם עליו השלום תפלה לצרה בין בית אל ובין העי, לא נשתייר משונאיהם של ישראל שריד ופליט."],
["Reshit_Chokhmah:98:4:0",12,98,4,"אור עולם · שער ג׳, פסקה ד׳","לעולם יהא אדם מפחד וירא מחטאיו, ויחזור לפני הקדוש ברוך הוא בתשובה שלימה, ויבקש סליחה וכפרה מאתו."],
["Reshit_Chokhmah:99:3:0",12,99,3,"אור עולם · שער ד׳, פסקה ג׳","לעולם יהא אדם רך כקנה ולא קשה כארז, לפיכך זכה קולמוס לכתוב בו ספר תורה תפלין ומזוזות."],
["Reshit_Chokhmah:99:4:0",12,99,4,"אור עולם · שער ד׳, פסקה ד׳","לעולם יהא אדם רגיל לומר כל מה דעבדין מן שמיא לטב."],
["Reshit_Chokhmah:99:6:0",12,99,6,"אור עולם · שער ד׳, פסקה ו׳","לעולם ישתדל אדם להיות צנוע וענו, וירגיל תמיד את עצמו ללכת בדרכי החכמים ובצניעות ובענוה."],
["Reshit_Chokhmah:100:2:0",12,100,2,"אור עולם · שער ה׳, פסקה ב׳","לעולם ישתדל אדם ללמוד תורה ודרך ארץ כדי שיהיה אהוב ונחמד למעלה ולמטה."],
["Reshit_Chokhmah:100:3:0",12,100,3,"אור עולם · שער ה׳, פסקה ג׳","לעולם ישים אדם את עצמו כשור לעול וכחמור למשאוי."],
["Reshit_Chokhmah:100:6:0",12,100,6,"אור עולם · שער ה׳, פסקה ו׳","לעולם אל יפטר אדם מחבירו אלא מתוך דבר הלכה שמתוך כך זוכרהו."],
["Reshit_Chokhmah:100:7:0",12,100,7,"אור עולם · שער ה׳, פסקה ז׳","לעולם ישתדל אדם לעשות לו רב ללמוד תורה ממנו, דתנן עשה לך רב וקנה לך חבר."],
["Reshit_Chokhmah:102:4:0",12,102,4,"אור עולם · שער ז׳, פסקה ד׳","לעולם ידבק אדם בג' דברים ואלו הן, הבאת שלום בין אדם לחבירו, ובאהבת שלום לאנשי ביתו, ובאהבתו של הקדוש ברוך הוא."],
["Reshit_Chokhmah:106:6:0",12,106,6,"אור עולם · שער י״א, פסקה ו׳","לעולם ישתדל אדם ללמד את בנו תורה ולהדריכו על הדרך הישרה, ואף על פי שטורח גדול בנים קשה עד מאד, אפילו הכי אל יתרשל בו, ואם עשה כן אשריו וטוב לו שכרו הרבה מאד."],
["Reshit_Chokhmah:107:9:0",12,107,9,"אור עולם · שער י״ב, פסקה ט׳","לעולם יהא אדם ירא שמים בסתר, ומודה על האמת, ודובר אמת בלבבו."],
["Reshit_Chokhmah:112:9:0",12,112,9,"אור עולם · שער י״ז, פסקה ט׳","לעולם תהא אימת הצבור עליך, שהרי כהנים אחוריהם כלפי שכינה ופניהם כלפי העם."],
["Reshit_Chokhmah:112:10:0",12,112,10,"אור עולם · שער י״ז, פסקה י׳","לעולם אל יוציא אדם עצמו מן הכלל. לעולם לשתתף איניש נפשיה בהדי צבורא."],
["Reshit_Chokhmah:113:4:0",12,113,4,"אור עולם · שער י״ח, פסקה ד׳","לעולם ישמור אדם פיו ולשונו ואל יספר לשון הרע, שכל המספר לשון הרע גורם לעצמו פשעים ועונות לאין תכלית."],
["Reshit_Chokhmah:116:4:0",12,116,4,"אור גדול · שער א׳, פסקה ד׳","גדול המלוה לעני בשעת דחקו יותר מן העושה צדקה."],
["Reshit_Chokhmah:120:2:0",12,120,2,"אור גדול · שער ה׳, פסקה ב׳","גדולה תורה שבזכותה הקדוש ברוך הוא מציל את ישראל מן היסורין, ולא ישלוט בהם היצר הרע, ושורה עליהם רוח הקדש."],
["Reshit_Chokhmah:120:5:0",12,120,5,"אור גדול · שער ה׳, פסקה ה׳","גדולה תורה וגדול שכרה משכר הצלת נפשות ומשכר בנין בית המקדש."],
["Reshit_Chokhmah:124:2:0",12,124,2,"אור גדול · שער ט׳, פסקה ב׳","גדול כבוד אב ואם שהקישו הקדוש ברוך הוא לכבודו."],
["Reshit_Chokhmah:129:3:0",12,129,3,"אור גדול · שער י״ד, פסקה ג׳","גדולה מלאכה שכמה בריות ברא הקדוש ברוך הוא בעולמו ולא מסר מלאכה אלא לבני אדם בלבד."],
["Reshit_Chokhmah:134:2:0",12,134,2,"אור גדול · שער י״ט, פסקה ב׳","גדול המכסה סוד חברו, שהוא מקיים מחשבות חברו, ואם אינו מכסהו הוא מפר מחשבתו, ולא יתקיים הדבר מפני שהוא מגלהו."],
["Reshit_Chokhmah:135:2:40",12,135,2,"אור גדול · שער כ׳, פסקה ב׳","גדולה דרך ארץ שכל מי שיש בידו דרך ארץ הוא אוהב להקדוש ברוך הוא ולבריות."],
["Sefer_Chasidim:11:1:0",13,11,1,"סימן י״א, פסקה א׳","אין חסיד אלא מי שעובר על מדותיו כשבאין ב\"א בפניו אשר חטאו ועשו לו שלא כהוגן ועתה מתחרטים ומבקשים מחילתו ממנו."],
["Sefer_Chasidim:13:1:671",13,13,1,"סימן י״ג, פסקה א׳","אדם שיש בו תורה ואין בו מעשים דומה למי שמסרו לו מפתחות הפנימיות ומפתחות החיצוניות לא מסרו לו בהי עייל ואיך יכנס:"],
["Sefer_Chasidim:83:1:0",13,83,1,"סימן פ״ג, פסקה א׳","אל תבהל ברוחך לכעוס איש חסיד צוה לבנו בפטירתו כשם שכבדתני בחיי כך תכבדני לאחר מותי וקיים מצותי ותלין כעסך לילה אחת ועצור ברוחך שלא תדבר כלל בשעת הכעס:"],
["Sefer_Chasidim:158:1:236",13,158,1,"סימן קנ״ח, פסקה א׳","טוב מעט ביראת ה' מאוצר רב ומהומה בו. יראת ה' מוסר חכמה ולפני כבוד ענוה."],
["Sefer_Chasidim:286:1:0",13,286,1,"סימן רפ״ו, פסקה א׳","אל יערב לך אם יכבדוך בשביל העושר אלא בשביל החכמה ומוסר:"],
["Sefer_Chasidim:373:1:0",13,373,1,"סימן שע״ג, פסקה א׳","טוב אחרית דבר מראשיתו כל דבר מראשיתו או אחריתו טוב."],
["Sefer_Chasidim:542:1:0",13,542,1,"סימן תקמ״ב, פסקה א׳","לא יוציא אדם מפיו דבר אלא אם כן יודע שרצון הבורא בדבר אז ותגזור אומר ויקם לך:"],
["Sefer_Chasidim:550:1:0",13,550,1,"סימן תק״נ, פסקה א׳","יהא אדם רגיל לומר יהי רצון מלפניך שלא נחטא לך ולבריותיך ושלא יחטאו לך בריותיך ושלא יחטאו בני ומחה כעב וכענן חטאתינו למען שמך הגדול:"],
["Sefer_Chasidim:554:1:0",13,554,1,"סימן תקנ״ד, פסקה א׳","אל תהי חכם בעיניך ירא את ה' וסור מרע. אל תהי חכם בעיניך לומר אשנה מה שאמרו חכמים."],
["Sefer_Chasidim:591:1:0",13,591,1,"סימן תקצ״א, פסקה א׳","מי שעשה זכות גדול וקשה בעיניו לעשות וכופה את יצרו עד שעושה עדיף מן האיש שאין יצרו תוקפו מלעשותו."],
["Sefer_Chasidim:592:1:0",13,592,1,"סימן תקצ״ב, פסקה א׳","איזהו יועץ וחכם שיודע לתת עצה שלא יבא לידי מכשול. אבל יועץ שעצתו באה לידי מכשול אע\"פ שנתן עצה טובה כיון שלמכשול באה עצתו אין זה יועץ חכם."],
["Sefer_Chasidim:595:1:271",13,595,1,"סימן תקצ״ה, פסקה א׳","טוב לו לאדם שלא יגזול שוה פרוטה ולא יתן הרבה לצדקה מאשר יגזול מעט ויתן הרבה לצדקה:"],
["Sefer_Chasidim:650:1:0",13,650,1,"סימן תר״נ, פסקה א׳","כשם שצריך האדם שיהא עניו מן המחרפים אותו כך יש לו לעשות שבני ביתו וחביריו ותלמידיו לא יענו קשות."],
["Sefer_Chasidim:752:1:0",13,752,1,"סימן תשנ״ב, פסקה א׳","אל יהא אדם מבקש צרכיו תחלה שיבקש כל חפצי שמים שהרי תקנו תחלה אתה חונן ואחר כך השיבנו אבינו ואחר כך סלח לנו ואחר כך צרכיו:"],
["Sefer_Chasidim:785:1:0",13,785,1,"סימן תשפ״ה, פסקה א׳","טוב לו לאדם שיתפלל ויקרא את שמע וברכות בלשון שמבין בו משיתפלל בלשון הקודש ואין מבין בו."],
["Sefer_Chasidim:1062:1:155",13,1062,1,"סימן א׳ אלף ס״ב, פסקה א׳","מי שנושא ונותן באמונה נותנים לו שכר אף על משא ומתן שלא עשה לפי שאם הי' בידו היה עושה אמונה כי בידו לעשות עולה ולא עשה כי לבו לשמים ולא הניח בשביל הבושת."],
["Moreh_BeEtzba:278:1:0",14,278,1,"סעיף רע״ח, פסקה א׳","כל התפלות והתחנונים יאמר בלב נשבר באמת ובכונה נכונה:"],
["Tzavaat_HaRivash:17:1:0",15,17,1,"פרק י״ז, פסוק א׳","לא להניח שום יום בלא מצוה הן קלה הן חמורה כמו שאמרו רז\"ל הוי זהיר במצוה קלה כבחמורה."],
["Tzavaat_HaRivash:45:1:0",15,45,1,"פרק מ״ה, פסוק א׳","הבכי' הוא רעה מאד שהאדם צריך לעבוד בשמחה רק אם הבכי' הוא מחמת שמחה אז טובה הוא מאד:"],
["Tzavaat_HaRivash:52:1:0",15,52,1,"פרק נ״ב, פסוק א׳","כשאדם עובד תמיד אותו ית' בכל רגע אין לו פנאי להתגאות ולאהוב את הגאוה ושאר מדות הרעות:"],
["Tzavaat_HaRivash:54:1:0",15,54,1,"פרק נ״ד, פסוק א׳","כשלומד צריך ליישב עצמו לפני מי הוא לומד שלפעמים מתרחק עצמו בלימודו מהבורא ית' לכך הוא צריך ליישב עצמו בכל עת ובכל שעה:"],
["Tzavaat_HaRivash:66:1:0",15,66,1,"פרק ס״ו, פסוק א׳","מתחלה כשרוצה להתפלל יהי' ביראה שהוא השער לכנוס לפניו ית' ויאמר בלבו למי אני רוצה לדבק א\"ע להבורא בדיבורו כל העולמות ומהווה אותם ומקיים אותם."],
["Tzavaat_HaRivash:133:1:0",15,133,1,"פרק קל״ג, פסוק א׳","כל המרבה דברים מביא חטא. פי' חיסרון שאפי' כשמדבר דברים עם בני אדם בחכמת התורה מ\"מ השתיקה יפה מאד יותר שיוכל יותר בשתיקה לחשוב בגדולתו יתברך ולקשר א\"ע יותר משיקשר את עצמו בדיבור:"],
["Tzavaat_HaRivash:137:1:0",15,137,1,"פרק קל״ז, פסוק א׳","יחשוב שהבורא מלא כל הארץ כבודו ושכינתו תמיד אצלו והוא דק מן הדק והוא אדון כל מעשים שבעולם והוא יכול לעשות כל מה שאני אחפוץ ולכך אינו יפה לו לבטוח רק בו יתברך:"],
["Meor_Einayim:49:77:0",16,49,77,"ליקוטים, פסקה ע״ז","הנה איך אפשר לירא מהשי\"ת כיון שאין יודעים אותו אך יראה הוא אותיות ראיה כי כשרואה שפלות עצמו אז אפשר לירא משם יתברך."],
["Kedushat_Levi:5:25:38",17,5,25,"בראשית · וירא, פסקה כ״ה","הנה שכוונת השם יתברך במה שפקדם לעת זקנותם ולא כדרך כל הארץ בשני נעורים כדי שתצטער על זה ואחר כך כשיפקוד אותה יהיה שמחה גדולה, כי הדבר שבא בנקל בלי שום צער אין בה שמחה."],
["Kedushat_Levi:12:23:33",17,12,23,"בראשית · דרושים לחנוכה, פסקה כ״ג","הנה ידוע, שעיקר עבודת האדם בתפלה ובתורה ובמצות, להתלהב נפשו ולבו לה' באהבה ותשוקה נפלאה, על ידי התבוננות בגדלות ה' בהעמקת הדעת אז תתלהב נפשו לה' בעריכות מתיקות ידידות כר."],
["Kedushat_Levi:15:13:110",17,15,13,"שמות · שמות, פסקה י״ג","הנה לבאר, כי כשהאדם מבקש איזה טובה מהבורא יתברך אזי לא יהיה עיקר כוונתו מחמת דבר הנוגע לעצמותו רק עיקר כוונתו יהיה כדי שעל ידי זה יעבוד את הבורא יתברך שמו בטוב לב."],
["Kedushat_Levi:68:164:778",17,68,164,"ליקוטים, פסקה קס״ד","הנה מרוב השגת גדולת הבורא ברוך הוא נתעורר לבו נכספה וגם כלתה נפשו ובוער כאש תשוקתו באהבת אמת ולהתקרב לה' תמיד שלא יהיה נבדל ממנו ולא יתרחק ולא יפרד ממנו, דק יהיה תמיד דבוק אצלו שיראה גדולתו ורוממתו והדר גאונו."],
["Sefat_Emet:136:4:477",18,136,4,"בראשית · חיי שרה · חלק ז׳, קטע ד׳","שמתמרמר על שנתרחק מהשי\"ת ויש תשובה מאהבה בלבד שמבטל עצמו בכלות הנפש להשי\"ת ויודע ומבין שאחר כל צדקותיו לא התחיל בעבודת הבורא כלום."],
["Sefat_Emet:509:3:380",18,509,3,"שמות · בשלח · חלק ד׳, קטע ג׳","צריך להיות אח\"כ אמונה ושתיקה ע\"י שמשיג מתוך החכמה שא\"א להשיגו. ועי\"ז חל עליו בושה ושותק ומאמין בה'."],
["Sefat_Emet:745:4:29",18,745,4,"שמות · כי תשא · חלק ט״ז, קטע ד׳","צריך כל איש ישראל להיות כל ימיו שומר ומצפה התגלות הקדושה וכבודו ית' בעולם."],
["Sefat_Emet:1126:3:0",18,1126,3,"במדבר · במדבר · חלק ג׳, קטע ג׳","כל העוסק בתורה לשמה. פי' להגדיל שם התורה כי השם הוא כשנתפרסם במקומות רחוקים וכ\"כ במדרש ברחובות תתן קולה במקום שמרחיבין אותה. והאדם צריך לעסוק בתורה כדי שדברי תורה יכנסו בלבו וימשיכו כל מעשיו אחרי'."],
["Sefat_Emet:1506:2:586",18,1506,2,"דברים · עקב · חלק כ״ב, קטע ב׳","כל ימי חייו צריך לעסוק בתו\"מ ויתרחבו הדברים ויוכל למצא בכל דבר קיום מצוה. וזה מצות קלות שדש בעקביו ואינו מבין מתחילה איך יש בזה מצוה. ובאמת כל העולם ומלואו מלא מצות כי הכל לכבודו ברא."],
["Sefat_Emet:1563:2:86",18,1563,2,"דברים · שופטים · חלק כ״ה, קטע ב׳","עיקר התמימות היא להיות בכל דבר שלמטה דביקות בחלק שלמעלה ואיש ישראל צריך להיות כל מעשיו למטה כמו שנעשה למעלה."],
["Sefat_Emet:1689:4:0",18,1689,4,"דברים · ראש השנה · חלק י״ד, קטע ד׳","זכור רחמיך ה' וחסדיך כי מעולם המה. פי' כי הקב\"ה ברא עולמו כדי להטיב ולגמול חסד להצריכים לו וכביכול נשתלמו מדותיו ית' בפועל ע\"י הבריאה כי העשיר צריך להדל להטיב עמו."],
["Sefat_Emet:1704:2:424",18,1704,2,"דברים · ראש השנה · חלק כ״ט, קטע ב׳","עיקר העוז לבנ\"י לשמוח בחלק אלקות המיוחד לנפשות בנ\"י. ובר\"ה מתחדש זה הכח שבו נברא האדם ויפח באפיו נשמת חיים."],
["Tzav_VeZeruz:1:1:77",19,1,1,"פרק א׳, פסקה א׳","כל ימי שנותינו אנו יגעים לחנך עצמינו, לישר העקמומיות ולגדל גדלויות בקרבנו, ואז בחיים השניים כבר היינו יכולים לחיות חיים מצוחצחים, חיים זכים אף בעולם הזה."],
["Tzav_VeZeruz:14:3:0",19,14,3,"פרק י״ד, פסקה ג׳","הן יש לכל איש ישראל רצון שיהי׳ צדיק, אבל זהו רק ברכה שמברך לעצמו שישכים בבוקר וימצא את עצמו צדיק, ולא זה רצון."],
["Tzav_VeZeruz:35:7:140",19,35,7,"פרק ל״ה, פסקה ז׳","אין לך ראשית ולא אחרית, אף חסדיך וטובותיך לנו, בלא גבול ובלי תכלית. ולמה זה לא אזכה למצער להוציא את געשי לבי בשירה, ואת להבי נפשי אליך בזמרה."],
["Tzav_VeZeruz:35:41:288",19,35,41,"פרק ל״ה, פסקה מ״א","העבר נא את מניעותי מבית ומבחוץ והושיעה את ישראל ואותנו בניך בגוף רוח ונפש וקרבנו להשתעבד לך ולעבדך בשמחה בכל פרטיות עצמותינו באמת."],
["Hakhsharat_HaAvrekhim:13:28:0",20,13,28,"פרק י״א, פסקה כ״ח","כל ספרי חסידות קדושים וטובים הם, ומקדשים ומטהרים את הלומד בהם, אבל רשות לכל אחד להתמיד יותר בספר מספרי חסידות אשר מרגיש בפועל שעושה לו טובה לקדשו ולקרבו לד׳."],
["Hakhsharat_HaAvrekhim:14:7:0",20,14,7,"פרק י״ב, פסקה ז׳","כל חנו של הילד הוא על שהוא תמים ופשוט, כשמדברים עמו מרגישים כאילו עם נפשו היינו מדברים, וכששואלים אותו דבר, השאלה חודרת עד לנפשו וממנה באה לנו תשובה תמימה ופשוטה, את כל לבו נותן הוא בתשובתו."],
["Mevo_HaShearim:11:16:0",21,11,16,"פרק י׳, פסקה ט״ז","יפסיעו נא פסיעה קטנה אחר פסיעה קטנה, עקב בצד אגודל, ופתאום יאירו עיניהם וישמחו לבביהם מאור התורה ונוגה החסידות אשר יבהיק לפניהם."],
["Eight_Chapters:4:3:488",22,4,3,"פרק ג׳, פסקה ג׳","שומע לעצת החכם - חכם, מפני שיודיענו הדרך שהוא ישר באמת, לא אשר יחשבהו הוא 'ישר'."],
["Netivot_Olam:52:1:54",23,52,1,"נתיב האמת · פרק א׳, פסקה א׳","שלמה המלך בא לדבר על מדת האמתית ועל מעלת האמת, כי כאשר האדם דבריו באמת ויושר, אף אם יבאו הכל לחלוק עליו ולבטל האמת ובכח נלחמים עמו עם כל זה האמת נשאר במקומו."],
["Netivot_Olam:106:1:0",23,106,1,"נתיב התשובה · פרק ב׳, פסקה א׳","מדת התשובה כאשר יתחרט האדם מעונותיו שעשה, ושב אל השם יתברך בכל לבו."],
["Netivot_Olam:106:9:0",23,106,9,"נתיב התשובה · פרק ב׳, פסקה ט׳","דע לך, כי התשובה היא לאדם מצד כי האדם נברא בהתחלתו בלא חטא. וכאשר הוא שב אל השם יתברך, אז האדם חוזר אל התחלתו. ומפני זה ראויה התשובה להביא רפואה לעולם, כי הרפואה גם כן שהוא שב להיות כבתחלה."],
["Netivot_Olam:117:4:0",23,117,4,"נתיב הזריזות · פרק ב׳, פסקה ד׳","הזריזות שיש לאדם במצות בוראו דבר זה הוא שלימות המצוה שבזה נחשב שהוא עושה המצוה בשלימות לגמרי."]];
